import type { MvBook } from '../molytvoslov';
const D: MvBook[] = [{"u":"Акафіст преподобному Силуану Афонському, чудотворцю","e":"Akathist to our Venerable Father Silouan the Athonite, the Wonderworker","secs":[{"h":"Кондак 1","ps":["Ізбра́нний подви́жниче і земни́й а́нгеле Христо́в, всеблаже́нне о́тче Силуа́не! В непреста́ннім бді́нії, по́сте і смире́нії отце́в афо́нських преізря́дний подража́телю, жа́ждею по Бо́зі і горі́нієм любве́ к Нему́ благода́ть оби́льную душі́ твоє́й стяжа́л єси́, всеблаже́нне. Христу́ подража́я, за том'я́щихся во а́ді, живи́х і гряду́щих, моли́твою сле́зною сраспина́лся єси́. Сицеви́я любве́ твоєя́ не лиши́ і нас, во юдо́лі гріхо́вній твоєго́ предста́тельства пред Бо́гом прося́щих і уми́льно зову́щих:","Ра́дуйся, о́тче Силуа́не, в моли́тві за мир горе́ніє любве́ неугаса́ющеє."]},{"h":"Ікос 1","ps":["А́нгелов Творе́ць і Госпо́дь Сил із чре́ва ма́тере твоєя́ предизбра́ тя і, по глаго́лу Псалмопе́вця, се́рдце глубоко́ дарова́ ті, богоно́сне о́тче Силуа́не, да я́ко в черто́зі преізря́днем, вмести́ши невмісти́моє і́м'я Бо́га Ви́шняго і си́лою Бо́жиєю і Бо́жиєю Прему́дростію житію́ а́нгельському всеусе́рдно послі́дуєши. Ми же, похваля́юще чу́дний по́двиг земни́х трудо́в твої́х, благогові́йно зове́м ті:","Ра́дуйся, роди́телей благочести́вих пло́де цілому́дренния чистоти́;","ра́дуйся, благово́нноє цвете́ніє їх по́двига ві́ри, неув'яда́ємия красоти́.","Ра́дуйся, благоче́стіє роди́телей твої́х душе́вні возлюби́вий;","ра́дуйся, цілому́дрію і боголю́бію їх уподо́битися благоволи́вий.","Ра́дуйся, ізмла́да ра́дости в Бо́зі іска́ти ди́вно умудри́вийся;","ра́дуйся, а́ки єле́нь, к істо́чнику благода́ті Бо́жия устреми́вийся.","Ра́дуйся, сло́вом Бо́жиїм, а́ки сла́дким ме́дом, ра́зум ю́ности твоєя́ услади́вий;","ра́дуйся, се́рдце твоє́ во́лі Бо́жієй всеці́ло покори́вий.","Ра́дуйся, о́тче Силуа́не, в моли́тві за мир горе́ніє любве́ неугаса́ющеє."]},{"h":"Кондак 2","ps":["Ви́ді тя Преблагослове́нная Богоро́диця в пучи́ні гріхо́вній погружа́єма, єгда́ сла́дость гріхо́вная, а́ки змій злосмра́дний, вни́де во утро́бу ю́ности твоєя́, Ма́терськи скорб'я́щи, ди́вно воззва́ ті: ча́до, неудо́бно Мі єсть ви́діти тя во гріхо́внім ді́ланії оскверня́ющася. Ю́же состра́ждущу о твоє́м гріхопаде́нії уразумі́в, змі́я гріхо́внаго мужему́дренно ізри́гнул єси́, покая́нієм і моли́твою того́ побіжда́я, лю́б'ящему же нас Го́споду ви́ну воспіва́я о Пречи́стій Ма́тері Єго́ благода́рную піснь: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум боже́ственний осіни́ тя, єгда́ глас Ма́тере Го́спода Сил усли́шати сподо́бился єси́, ізбра́нниче Бо́жий Силуа́не, і благода́ть Свята́го Ду́ха іспо́лни се́рдце твоє́. Тоя́ же ді́йствієм, а́ки се́рна от тене́т, во вертогра́д ди́вно призва́вшия тя Бо́жия Ма́тере, Го́ру Афо́нськую, от мирськи́я суєти́ устреми́лся єси́, во є́же приліпи́тися Бо́гу синолю́бне. Ми же, ви́дяще чу́дноє ізволе́ніє о тебі́ ми́ра Влади́чиці, уми́льно зове́м ті:","Ра́дуйся, от мра́ка гріхо́внаго к сві́ту і́стини Христо́ви Само́ю Пречи́стою призва́нний;","ра́дуйся, би́ти ві́рний ді́латель Єя́ земна́го вертогра́да ди́вно ізбра́нний.","Ра́дуйся, землі́ Украї́нськия гро́зде сладкоте́чний, на Горі́ Афо́нстій ізоби́льно прозрі́вий;","ра́дуйся, со́весте недре́млющая, покая́нною моли́твою жа́ло гріхо́вноє притупи́вшая.","Ра́дуйся, во сві́ті Пантелеї́моновей оби́телі а́нгельськи Бо́гу послужи́вий;","ра́дуйся, в труді́, по́сте і безмо́лвії врага́, борю́щаго тя, сла́вно покори́вий.","Ра́дуйся, вся ко́зні дия́вола смиренному́дренно попра́вий;","ра́дуйся, жа́ждею по Бо́зі ві́ру непоро́чную сла́вне стяжа́вий.","Ра́дуйся, о́тче Силуа́не, в моли́тві за мир горе́ніє любве́ неугаса́ющеє."]},{"h":"Кондак 3","ps":["Си́ла Ви́шняго воі́стину храня́ше тя, єгда́ дух а́да і сме́рті претя́ше ті і ду́шу твою́ прельще́ньми гріхо́вними обурева́ше, боголюби́ве о́тче Силуа́не. Ізнемога́яй же, Бо́га неумоли́ма поми́слил єси́ би́ти; тогда́ Человіколю́бець Госпо́дь, в неізрече́ннім Фаво́рстім блиста́нії, тя посіти́ і огне́м благода́ті Свята́го Ду́ха укріпи́ тя, всеблаже́нне. Ти же, а́ки Па́вел, но́воє рожде́ніє восприя́в, со стра́хом і ра́достію взива́л єси́ Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я бога́тство благода́ті, во є́же ду́хом на Небеса́ возведе́ну би́ти і та́мо неізрече́нния глаго́ли сли́шати, воі́стину, ра́дости тоя́ кто іспові́сть, о́тче преблаже́нне Силуа́не. Єгда́ бо, вні образо́в ми́ра, в созерца́нії Божества́ добро́ти несказа́нния, безмі́рно лю́б'ящаго і всепроща́ющаго Христа́ Бо́га лице́ ви́діти сподо́бился єси́, неізрече́нния любве́ Бо́жия преіспо́лнился єси́. Ми же, чудя́щеся твоєму́ неізглаго́ланному Боговиді́нію, вопіє́м:","Ра́дуйся, в по́двизі ві́ри Христо́ва посіще́нія і утіше́нія сподо́бивийся;","ра́дуйся, добро́ту неізрече́нния сла́ви Єго́ лицезре́ти удосто́ївийся.","Ра́дуйся, в Єде́м Небе́сний ди́вния красоти́ Ду́хом Святи́м возведе́нний;","ра́дуйся, та́мо благода́тними да́ри Свята́го Уті́шителя Ду́ха преізоби́льно напоє́нний.","Ра́дуйся, прича́стниче неізрече́нния ра́йськия красоти́;","ра́дуйся, Бо́гом возлю́бленний і їм облагода́тствованний щедро́тами Небе́сния добро́ти.","Ра́дуйся, тоя́ благода́ті всему́ челові́чу ро́ду прилі́жно хода́тайствуяй;","ра́дуйся, я́ко страж недре́мляй, к у́тру жи́зні ві́чния нас пробужда́яй.","Ра́дуйся, о́тче Силуа́не, в моли́тві за мир горе́ніє любве́ неугаса́ющеє."]},{"h":"Кондак 4","ps":["Бу́рю лю́тих іскуше́ній воздви́же на тя человікоуби́йця дия́вол, іскони́ іски́й пра́ведних погуби́ти, но ти, о́тче Силуа́не, Ду́хом Святи́м наставля́ємий держа́ ті ум твой во а́ді і не отчаява́тися, в непреста́ннім бді́нії і смире́нії ко́зні дия́вола предваря́я, того́ побіди́л єси́. Он же, тобо́ю посра́мленний, не обину́яся, рече́ ті, я́ко лжець єсть. І та́ко от сіте́й врага́ ду́шу твою́, а́ки голуби́цю кро́ткую, Бо́гу соблю́л єси́, непреста́нно воспіва́я Єму́: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шаще о тебі́, я́ко ди́вно от мирськи́я суєти́ к і́ночеському по́двигу призва́н бисть і благода́тію Бо́жиєю добр плод твори́ши, преподо́бне, не то́кмо младі́ї і́ноці, но і ста́рці, в по́двизі зіло́ іску́снії, к тебі́ притека́ху, і, а́ки ме́дом, ді́ли і словеси́ твої́ми услажда́хуся, і та́ко равноа́нгельськаго житія́ достига́юще, Го́споду уподобля́хуся. Ми же, ви́дяще тя смиренному́дрієм укра́шена, с ра́достію зове́м ті:","Ра́дуйся, смиренному́дрія і цілому́дрія кла́дязю неісчерпа́ємий;","ра́дуйся, земна́го Еде́ма кри́не благоуха́нний і неув'яда́ємий.","Ра́дуйся, благо́є і́го Христо́во в по́двизі твоє́м с любо́вію носи́вий;","ра́дуйся, ум твой, се́рдце і во́лю в Бо́зі моли́твою утверди́вий.","Ра́дуйся, чистоти́ душе́вния і тіле́сния храни́телю усе́рдний;","ра́дуйся, непреста́нною моли́твою на висоту́ безстра́стія возше́дий.","Ра́дуйся, святооте́чеським пра́вилом усе́рднійший подража́телю;","ра́дуйся, Небе́снаго Оте́чества і любве́ Бо́жия к нам непрестая́й глаша́таю.","Ра́дуйся, о́тче Силуа́не, в моли́тві за мир горе́ніє любве́ неугаса́ющеє."]},{"h":"Кондак 5","ps":["Звізду́, путь указу́ющую і ум просвіща́ющую, Боже́ственную благода́ть, дарова́ ті Госпо́дь, боголюби́ве о́тче Силуа́не, і то́ю, а́ки проро́ка Ілію́ у пото́ка Хора́фа, на спаси́тельний по́двиг укріпля́ше тя. Ти же, ди́вно пита́ємий от неіждива́ємих сокро́вищ Ду́ха Свята́го, в ю́ности і престаре́нії, от стра́жи у́треннія до но́щі, в моли́твах за всю вселе́нную, а́ки свирі́ль сладкопі́сненная, непреста́нно взива́л єси́ Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дим тя, о преблаже́нне о́тче Силуа́не, в по́двизі бла́зім, а́ки младе́нець млека́ ма́тере, любве́ Бо́жия і́щуща, і к Тому́ любо́вію пламене́юща, і сле́зно взива́юща: пом'яну́ душа́ моя́ любо́в Госпо́дню, і согрі́яся се́рдце моє́: кто бо дасть мі толи́кий жар, є́же не зна́ти мі поко́я во дні, ніже́ в но́щі от любве́ Бо́жия? Сего́ ра́ди содрага́ємся се́рдцем і умиля́ємся душе́ю о толи́ком горі́нії любве́ твоєя́ ко Всеще́дрому Бо́гу і уми́льно зове́м ті:","Ра́дуйся, па́че сла́дка ме́да неутоли́мо пра́вди Бо́жия жа́ждай;","ра́дуйся, в любві́ твоє́й ко Го́споду А́нгелом подража́яй.","Ра́дуйся, вознося́й кади́ло моли́тви чи́стия, а́ки пла́мень о́гненний;","ра́дуйся, красото́ю а́нгельськаго благогові́нія украси́вий го́рняя і до́льняя.","Ра́дуйся, я́ко огню́ купини́ несгара́ємия се́рдце твоє́ уподобля́шеся;","ра́дуйся, я́ко ру́ці твої́, а́ки Моїсе́йові за наро́д ізбра́нний, о всіх пред Го́сподем простира́стася.","Ра́дуйся, ти бо возлюби́л єси́ возжела́ти судьби́ Бо́жия на вся́коє вре́м'я і взиска́л єси́ оправда́ній Єго́;","ра́дуйся, я́ко непреста́нно Єму́ взива́л єси́: спаси́, Бо́же, лю́ди Твоя́ і благослови́ достоя́ніє Твоє́.","Ра́дуйся, о́тче Силуа́не, в моли́тві за мир горе́ніє любве́ неугаса́ющеє."]},{"h":"Кондак 6","ps":["Пропові́дник немо́лчен безмо́лвія яви́лся єси́, уго́дниче Бо́жий, єгда́ Человіколю́бець Госпо́дь восхоті́ в любві́ іспита́ти тя і посіще́нія Всесвята́го Ду́ха лиши́ тя. Ти же, уразумі́в себі́ лише́на Того́ благода́ті, а́ки Ада́м лише́нія Рая́ рида́ше, се́рдцем сокруше́нним сле́зно взива́л єси́: Го́споди! Ти пре́жде взиска́л єси́ м'я і дал мі єси́ наслади́тися Ду́хом Твої́м Святи́м, і душа́ моя́ возлюби́ Тя. Ни́ні же ту́жить душа́ моя́ по Тебі́. Си́це рида́я, оба́че на милосе́рдіє Бо́жиє упова́я, взива́л єси́ Єму́: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́л єси́, боголюби́ве о́тче Силуа́не, я́ко но́вий Тайнови́дець, отне́лиже смире́нієм і моли́твою со слеза́ми благода́ть Свята́го Ду́ха па́ки стяжа́л єси́, от нея́же любве́ неізрече́нния преіспо́лнися се́рдце твоє́. Ти же, уразумі́в благода́ті сея́ си́лу, дерзнове́нієм Іліїни́м воззва́л єси́: Го́споди! Не то́кмо мні, всему́ ми́ру да́руй позна́ти любо́в Твою́ і спасти́ся. Ми же, іму́ще тя моли́твенника пред Бо́гом неуси́пна, со умиле́нієм зове́м ті:","Ра́дуйся, я́ко моли́твенним сраспина́нієм за уме́рших, живи́х і гряду́щих бил єси́ не́бо отве́рстоє;","ра́дуйся, я́ко сицево́ю любо́вію ісхода́тайствовал єси́ душі́ твоє́й Ца́рство Небе́сноє.","Ра́дуйся, чистоти́ ві́ри і беззло́бія ди́вноє воплоще́ніє;","ра́дуйся, гріхопаде́нієм бли́жніх твої́х стяжа́вий Христо́во всепроще́ніє.","Ра́дуйся, ди́внаго святи́лища ми́ра уго́дником Бо́жиїм ві́рний сподви́жниче;","ра́дуйся, Преблагослове́нния Ігу́менії Афо́на ві́рний послу́шниче і даро́в Свята́го Ду́ха вмісти́лище.","Ра́дуйся, Тоя́ вертогра́да тру́дниче неуси́пний, в по́двизі ізнемога́ющих укріпля́яй;","ра́дуйся, Гори́ Афо́нськия свирі́ль сладкопі́сненная, о гряду́щей жи́зні возвіща́ющая.","Ра́дуйся, о́тче Силуа́не, в моли́тві за мир горе́ніє любве́ неугаса́ющеє."]},{"h":"Кондак 7","ps":["Хотя́ Человіколю́бець Госпо́дь яви́ти в тебі́ но́воє благосве́тлоє світи́ло, преподо́бне о́тче Силуа́не, я́ко вітв ма́сличную, от ко́рене землі́ Украї́нськия, в пусти́ні Афо́нстій насади́, і, Ду́ха Свята́го благода́тію ороша́я, многопло́дна тя сотвори́: ді́ли бо і словеси́ твої́ми, а́ки єле́єм животво́рним, чистоті́ і цілому́дрію, благоче́стію і братолю́бію всіх наставля́л єси́. Они́ же, сою́зом любве́ связу́ємі, покаря́юще ху́ждшеє лу́чшему, воспіва́ху Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́ваго пустинножи́телем сподви́жника, мона́хом і мирськи́м наста́вника і учи́теля яви́ тя Госпо́дь, преблаже́нне Силуа́не. Ти бо, єще́ в ми́рі жив, ні́коєго во́їна, о гріхопаде́нії жени́ своєя́ соблазни́вшагося і во гні́ві яря́щася, Христо́ву всепроще́нію научи́л єси́, і сим та́їнство бра́ка, ма́лая це́рков, от разруше́нія сохрани́ся; і́ноков же, в уни́ніє впа́дших, к стяжа́нію душе́внаго ми́ра призива́я і стра́ху Бо́жию наставля́я, к покая́нію приводи́л єси́, і та́ко рая́ жи́телей би́ти всіх приуготовля́л єси́. Ві́дуще тя та́ко о спасе́нії всіх печа́лящася, достодо́лжно с любо́вію вопіє́м ті:","Ра́дуйся, пустиннолю́бцев в іска́нії Бо́га усе́рдний сподви́жниче;","ра́дуйся, братолю́бія приле́жний строї́телю і те́плий о всіх моли́твенниче.","Ра́дуйся, на путі́ жите́йстім, в біда́х і напа́стіх сопу́тниче ві́рний;","ра́дуйся, в болі́зніх і печа́ліх і ско́рбіх душе́вних служи́телю нелицемі́рний.","Ра́дуйся, ве́стниче любве́ Бо́жия, к примире́нію с Бо́гом і бли́жнім свої́м всіх призива́яй;","ра́дуйся, свиді́тельством, я́ко благ Госпо́дь, ду́ші, от гріха́ ізнемога́ющия, в наде́жді проще́нія подкрепля́яй.","Ра́дуйся, ві́рний подви́жниче земна́го Еде́ма, спасе́ніє ми́ру сле́зно хода́тайствуяй;","ра́дуйся, за всіх нераска́янних грі́шников во ад сни́ти жела́яй.","Ра́дуйся, о́тче Силуа́не, в моли́тві за мир горе́ніє любве́ неугаса́ющеє."]},{"h":"Кондак 8","ps":["Стра́нноє чу́до яви́ тебі́ Госпо́дь, преблаже́нне о́тче Силуа́не, єгда́ ста́рця духовника́ Авраа́мія преображе́нна во о́бразі своє́м, невирази́мо сія́юща, ди́вно ті показа́, і та́ко че́стне почита́ти та́їнство покая́нія нас наста́ви. Ми же, ви́дяще тя, во́лю свою́, я́ко Самому́ Го́споду, духо́вному отцю́ своєму́ вверя́юща і та́ко смире́нієм і покая́нієм зла́я хоті́нія своя́ отсіка́юща, во́лі Бо́жієй, чрез па́стирей Це́ркве Христо́ви, науча́ємся уверя́тися і си́це, пре́жде ісхо́да на́шего, гні́ва Бо́жия і Суда́ гряду́щаго ізбіжа́ти, вопію́ще Трієди́ному Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Всім се́рдцем і душе́ю смире́ніє Христо́во стяжа́вий, преди́вний уго́дниче Бо́жий, і Тому́, возлю́бленному, за мир сраспина́яйся, сле́зно взива́л єси́: Сладча́йший Ісу́се! Ти воскреси́л єси́ ду́шу мою́ люби́ти Тя і бли́жняго своєго́. Да́руй мі у́бо істоча́ти сле́зи за всю вселе́нную, да всі лю́діє позна́ють Тя і да насладя́ться ми́ром Твої́м і у́зрять світ лиця́ Твоєго́. Ми же, во грісі́х житіє́ на́ше іжди́вшії і тобо́ю спаса́ємі, ублажа́єм тя си́це:","Ра́дуйся, Засту́пниці усе́рдния в моли́твах за мир сподви́жниче неутоми́мий;","ра́дуйся, я́ко Ієреми́я, о наро́ді пла́чай, Го́ру Святу́ю слеза́ми ороси́вий.","Ра́дуйся, преди́вний Афо́нський подви́жниче, всю вселе́нную моли́твою освяща́яй;","ра́дуйся, я́ко оте́ць чадолюби́вий, за всіх во грісі́х погиба́ющих сле́зно пред Бо́гом хода́тайствуяй.","Ра́дуйся, Христу́ Бо́гу возлю́бленне уго́дниче, А́нгелом ра́дость і удивле́ніє;","ра́дуйся, сі́вера сві́тлоє сія́ніє, в Афо́нстій пусти́ні Святи́я Русі́ чи́стоє отображе́ніє.","Ра́дуйся, в смире́нії і послуша́нії яви́вий ми́ру о́браз а́нгельськия красоти́;","ра́дуйся, теплото́ю моли́тви твоєя́ і нас дом Ду́ха Боже́ственнаго хотя́й сотвори́ти.","Ра́дуйся, о́тче Силуа́не, в моли́тві за мир горе́ніє любве́ неугаса́ющеє."]},{"h":"Кондак 9","ps":["Все єстество́ а́нгельськоє і подви́жников мно́жество удиви́шася смире́нію і человіколю́бію твоєму́, о́тче наш Силуа́не, єгда́ іконо́мства послуша́нієм целому́дренному Іо́сифу во Єги́пті уподо́бился єси́. І не то́кмо о бра́тії святи́я оби́телі, но і о мирськи́х ді́лателіх, та́мо труди́вшихся, я́ко о ча́діх Бо́жиїх, попече́ніє імі́вий, Бо́гу, лю́б'ящему вся́коє Своє́ созда́ніє, взива́л єси́: Го́споди, посли́ Ду́ха Свята́го Твоєго́ і уті́ши ско́рбния ду́ші бі́дних люде́й сих. Та́ко бо во вся́ком послуша́нії смиренному́дрія красоту́ показу́я, непреста́нно взива́л єси́ Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Ві́тіії многовіща́ннії не возмо́гуть ізрещи́ си́лу любве́ твоєя́, преди́вне о́тче Силуа́не, ти бо сле́зно жа́ждал єси́ вся́ку вражду́ і нестроє́ніє в лю́діх угаси́ти і вся́чеськая с Бо́гом примири́ти, взива́я Влади́ці ми́ра: Го́споди! Твої́м жа́жду би́ти і с Тобо́ю за всю вселе́нную сорасп'я́тися, да всі спасе́ни бу́дуть. К бра́тії же взива́л єси́: ча́да, молі́теся за враго́в свої́х, ті́ї бо суть бра́тія ва́ша, жизнь ва́ша, враг же ми́ра то́кмо дия́вол єсть. Ми же, та́ко к братолю́бію і человіколю́бію тобо́ю наставля́ємі, зове́м ті:","Ра́дуйся, добро́тою твоє́ю Христу́ на Голго́фі уподо́бивийся;","ра́дуйся, не рука́ми бо, се́рдцем і душе́ю за враго́в свої́х сраспина́вийся.","Ра́дуйся, о бли́жніх пеки́йся і красоту́ благода́тнаго безмо́лвія не утра́тивий;","ра́дуйся, люб'я́ бли́жніх свої́х, си́лу непреста́нния моли́тви стяжа́вий.","Ра́дуйся, посто́м і моли́твою стрі́ли лука́ваго до конця́ отрази́вий;","ра́дуйся, злоловле́нія і ухищре́нія дия́вола препобежда́ти нас научи́вий.","Ра́дуйся, в ме́льниці Христо́ві плоть трудо́м ізнуря́я, а́ки хлі́бом свяще́нним, се́рдце моли́твою услажда́вий;","ра́дуйся, ді́лателей вертогра́да Цари́ці Небе́сния хлі́бом насу́щним ізоби́льно пита́вий.","Ра́дуйся, о́тче Силуа́не, в моли́тві за мир горе́ніє любве́ неугаса́ющеє."]},{"h":"Кондак 10","ps":["Спасе́нія душі́ твоєя́ іща́ і Христу́ Сладча́йшему приліпи́тися жела́я, от землі́ оте́ць твої́х на Го́ру Святу́ю смире́нні прите́кл єси́, іді́же во воздержа́нії і безмо́лвії, трудолю́бії і человіколю́бії равноа́нгельную красоту́ стяжа́л єси́, всеблаже́нне. І та́ко преблагослове́ннаго у́тра, єгда́ всі пустиннолю́бці оби́телей Афо́нських полу́нощную піснь Творцю́ воспіва́ху, благи́я кончи́ни дости́гл єси́ і ду́шу твою́, Животворя́щим Ті́лом і Кро́вію Госпо́днею напита́нную, в Боже́ственнії ру́ці Того́ пре́дал єси́, во є́же непреста́нно со всі́ми святи́ми воспіва́ти святи́х Святі́йшему Сло́ву: Аллилу́я."]},{"h":"Ікос 10","ps":["Царя́ Небе́снаго, Єго́же славосло́в'ять Херуви́ми і Серафи́ми і святи́х собо́ри, житіє́м, ві́рою і любо́вію всеусе́рднійший служи́тель бил єси́, преподо́бне, і, я́ко крин благоуха́нний, со всі́ми ізбра́нники Пречи́стия Богоро́диці, у Престо́ла Всесвяти́я Тро́йці предста́л єси́. Бу́ди же, всеблаже́нне, о благоде́нственнем ми́рі землі́ оте́ць твої́х усе́рдний пред Бо́гом хода́тай, о Це́ркві же Святі́й а́нгел неуси́пния моли́тви і те́плий предста́тель, да тобо́ю от бід ізбавля́ємі, благода́рні зове́м ті:","Ра́дуйся, а́нгеле землі́ Украї́нськия, на Святі́й Горі́ преізря́дно потруди́вийся;","ра́дуйся, моли́твенниче теплі́йший, у Престо́ла Бо́жия за нас любо́вію сораспни́йся.","Ра́дуйся, о лю́діх землі́ отце́в твої́х усе́рдний пред Бо́гом хода́таю;","ра́дуйся, бра́тії Афо́нськаго вертогра́да, в по́двизі ізнемога́ющим, ско́рий предста́телю.","Ра́дуйся, я́зви Го́спода твоєго́ на ті́лі твоє́м безро́потно носи́вий;","ра́дуйся, ду́шу твою́, покая́нними слеза́ми убіле́ну, чи́сту Тому́ вве́ривий.","Ра́дуйся, ві́рний ді́лателю виногра́да Христо́ва, ко Го́рнему Сіо́ну Го́сподем призва́нний;","ра́дуйся, я́ко та́мо собесе́дуєши со святи́ми і А́нгели, сла́вою і че́стію увінча́нний.","Ра́дуйся, о́тче Силуа́не, в моли́тві за мир горе́ніє любве́ неугаса́ющеє."]},{"h":"Кондак 11","ps":["Піснь благохва́льную прино́сим ті, уго́дниче Бо́жий, о́тче Силуа́не, горі́нієм бо любве́ ко Го́споду, за спасе́ніє ми́ра взалка́вшему і смире́нієм Свої́м дия́вола посрами́вшему, ві́рно послі́дуя, пусти́ню Афо́нськую моли́твою чи́стою облагоуха́л єси́, о́браз равноа́нгельнаго житія́, многопло́дними да́ри Свята́го Ду́ха украше́нний, благода́тно нам показу́я. Си́це бо Го́ру Святу́ю рає́ві уподобля́я, врага́ посрами́л єси́, душі́ же твоє́й Ца́рствіє Небе́сноє стяжа́л єси́, подвиза́я і нас любо́вію к Бо́гу приліпля́тися, вопію́ще Єму́: Аллилу́я."]},{"h":"Ікос 11","ps":["Светопода́тельнаго Сві́та і благода́ті Свята́го Ду́ха носи́теля в житії́, і по сме́рті всему́ ми́ру яви́ тя Госпо́дь во днех на́ших, преподо́бне, во є́же взира́юще на тя, нетлі́нною красото́ю земни́х по́двигов блиста́юща і херуви́мськи у Престо́ла Бо́жия за нас моли́тви творя́ща, в наде́жді на́шего спасе́нія уверя́тися і благонра́вному житію́ всеусе́рднійше послі́довати, во́лю же свою́ любві́ Бо́жієй сла́дці покори́м, та́кожде і в тілесі́х і душа́х на́ших прославле́ніє і́мене лю́б'ящаго нас Го́спода да утверди́ться. Ті́мже, тобо́ю во ві́рі укріпля́ємі, с любо́вію зове́м ті:","Ра́дуйся, по́двигом жи́зні благонра́вния в любві́ к Бо́гу нас укріпля́яй;","ра́дуйся, усе́рдний обличи́телю злонра́вія, та́їнства і пра́вила ві́ри Правосла́вния храни́ти нас наставля́яй.","Ра́дуйся, пустинножи́тельством Петру́ Афо́нському в пості́ і безмо́лвії прилі́жно ревнова́вий;","ра́дуйся, попече́нієм о благонра́вії і́ночествующих а́вві Афана́сію ві́рно подража́вий.","Ра́дуйся, но́вий світи́льниче ві́ри, во дні на́ша ві́рний путь к Бо́гу указу́яй;","ра́дуйся, о неоскуде́нії благода́ті Свята́го Ду́ха в Це́ркві Правосла́вній всім ди́вно свиді́тельствуяй.","Ра́дуйся, ві́рний ра́бе Христо́в, досто́йно у Престо́ла сла́ви Єго́ предстоя́й;","ра́дуйся, благи́я кончи́ни і до́браго отві́та на Стра́шнім Суди́щі Христо́ві нам усе́рдно прося́й.","Ра́дуйся, о́тче Силуа́не, в моли́тві за мир горе́ніє любве́ неугаса́ющеє."]},{"h":"Кондак 12","ps":["Благода́ті неісповіди́мую си́лу ізлія́ на тя Христо́с Бог наш, преподо́бне, во є́же на Небесі́х, іді́же все живе́ть і дви́жеться в ра́дості Ду́ха Свята́го, яви́ти тя в ли́ці Афо́нських подви́жников, со всі́ми святи́ми о всіх земноро́дних моли́тви творя́ща. Та́ко ві́дуще тя, мо́лимся: проли́й, о всеблаже́нне, те́плую моли́тву ко Го́споду, да милосе́рдовав, Це́рков Свою́ Святу́ю, во спасе́ніє на́ше, во ві́ки утверди́ть, пустиннолю́бцев земна́го Еде́ма вся́чеськи сохрани́ть і укріпи́ть, да во ві́ки славосло́виться і́м'я Бо́жиє от земни́х і Небе́сних, пою́щих: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще пресла́вную па́м'ять твою́, богоно́сне о́тче Силуа́не, досто́йно ублажа́єм болі́зні і труди́ твоя́, я́же во бді́нії і поще́нії со всі́ми ізбра́нними Бо́жия Ма́тере всеусе́рдні поне́сл єси́. Кто бо ізочте́ть труди́ і воздиха́нія ва́ша, в моли́твах за мир сле́зно приноси́мия, і́миже Госпо́дь гнів Свой, гріхо́в ра́ди на́ших, на ми́лованіє преложи́ і человіколю́бієм Свої́м кля́тву, є́юже кля́тся, о є́же Це́ркві Святі́й до сконча́нія ві́ка утвержде́нней би́ти, не разори́. Ми же, благода́рні су́ще сицево́му предста́тельству твоєму́, уми́льно зове́м ті:","Ра́дуйся, води́тельству Свята́го Ду́ха усе́рдний послі́дователю;","ра́дуйся, Христа́, бла́гості і Прему́дрости Бо́жия, тіле́снима очи́ма лицезри́телю.","Ра́дуйся, Христо́в смире́нний подви́жниче, Ма́тере Бо́жия пред всі́ми Небе́сними і земни́ми ра́дость і похвале́ніє;","ра́дуйся, неуси́пний о ми́рі моли́твенниче, на́шего спасе́нія наде́ждо і утіше́ніє.","Ра́дуйся, наслі́дниче Ца́рствія Христо́ва, по́двигом свої́м Го́ру Афо́нськую украси́вий;","ра́дуйся, на́шего спасе́нія ві́рний сподви́жниче, путь, веду́щий к Бо́гу, нам освяти́вий.","Ра́дуйся, златоко́ванная трубо́, со всі́ми святи́ми і А́нгели сла́ву Бо́жию возвіща́ющая;","ра́дуйся, вінце́м безсме́ртія Бо́гом увінча́нний, в моли́твах свої́х нас не оставля́яй.","Ра́дуйся, о́тче Силуа́не, в моли́тві за мир горе́ніє любве́ неугаса́ющеє."]},{"h":"Кондак 13","ps":["О преди́вний уго́дниче Бо́жий Силуа́не, землі́ Украї́нськия благода́тноє рожде́ніє, пустиннолю́бцев Гори́ Афо́нськия похвало́ і украше́ніє! Прийми́ от нас ма́лоє сіє́ моле́ніє і іспроси́ у Распе́ншагося за мир Христа́ Бо́га на́шего, да поми́луєть всіх нас, чад Свої́х, і благода́тію Свята́го Ду́ха в сою́з любве́ Своєя́ свя́жеть нас, і ї́миже вість судьба́ми, к Себі́ приведе́ть, во є́же твої́ми моли́твами непости́дно яви́тися нам в день Су́дний пред лице́м сла́ви Єго́ і сподо́битися со всі́ми святи́ми і а́нгели воспіва́ти побі́дную піснь: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелов Творе́ць і Госпо́дь Сил із чре́ва ма́тере твоєя́ предизбра́ тя і, по глаго́лу Псалмопе́вця, се́рдце глубоко́ дарова́ ті, богоно́сне о́тче Силуа́не, да я́ко в черто́зі преізря́днем, вмести́ши невмісти́моє і́м'я Бо́га Ви́шняго і си́лою Бо́жиєю і Бо́жиєю Прему́дростію житію́ а́нгельському всеусе́рдно послі́дуєши. Ми же, похваля́юще чу́дний по́двиг земни́х трудо́в твої́х, благогові́йно зове́м ті:","Ра́дуйся, роди́телей благочести́вих пло́де цілому́дренния чистоти́;","ра́дуйся, благово́нноє цвете́ніє їх по́двига ві́ри, неув'яда́ємия красоти́.","Ра́дуйся, благоче́стіє роди́телей твої́х душе́вні возлюби́вий;","ра́дуйся, цілому́дрію і боголю́бію їх уподо́битися благоволи́вий.","Ра́дуйся, ізмла́да ра́дости в Бо́зі іска́ти ди́вно умудри́вийся;","ра́дуйся, а́ки єле́нь, к істо́чнику благода́ті Бо́жия устреми́вийся.","Ра́дуйся, сло́вом Бо́жиїм, а́ки сла́дким ме́дом, ра́зум ю́ности твоєя́ услади́вий;","ра́дуйся, се́рдце твоє́ во́лі Бо́жієй всеці́ло покори́вий.","Ра́дуйся, о́тче Силуа́не, в моли́тві за мир горе́ніє любве́ неугаса́ющеє."]},{"h":"Кондак 1","ps":["Ізбра́нний подви́жниче і земни́й а́нгеле Христо́в, всеблаже́нне о́тче Силуа́не! В непреста́ннім бді́нії, по́сте і смире́нії отце́в афо́нських преізря́дний подража́телю, жа́ждею по Бо́зі і горі́нієм любве́ к Нему́ благода́ть оби́льную душі́ твоє́й стяжа́л єси́, всеблаже́нне. Христу́ подража́я, за том'я́щихся во а́ді, живи́х і гряду́щих, моли́твою сле́зною сраспина́лся єси́. Сицеви́я любве́ твоєя́ не лиши́ і нас, во юдо́лі гріхо́вній твоєго́ предста́тельства пред Бо́гом прося́щих і уми́льно зову́щих:","Ра́дуйся, о́тче Силуа́не, в моли́тві за мир горе́ніє любве́ неугаса́ющеє."]},{"h":"Молитва","ps":["О преди́вний уго́дниче Бо́жий, о́тче Силуа́не! По благода́ті, тебі́ от Бо́га да́нній, сле́зно моли́тися о всей вселе́нній, ме́ртвих, живи́х і гряду́щих, не премолчи́ за нас ко Го́споду, к тебі́ усе́рдно припа́дающих і твоєго́ предста́тельства уми́льно прося́щих. Подви́гни, о всеблаже́нне, на моли́тву Усе́рдную Засту́пницю ро́да христия́нськаго, Преблагослове́нную Богоро́дицю і Присноді́ву Марі́ю, чу́дно призва́вшую тя би́ти ві́рна ді́лателя в Єя́ земні́м вертогра́ді, іді́же ізбра́нници Бо́жії о грісі́х на́ших ми́лостива і долготерпіли́ва би́ти Бо́га умоля́ють, во є́же не пом'яну́ти непра́вд і беззако́ній на́ших, но, по неізрече́нній бла́гости Го́спода на́шего Ісу́са Христа́, уще́дрити і спасти́ нас по вели́цій Єго́ ми́лості.","Єй, уго́дниче Бо́жий, с Преблагослове́нною Влади́чицею ми́ра, Святе́йшею Ігу́менією, і святи́ми подви́жниками Єя́ земна́го жре́бія, іспроси́ у святи́х Святі́йшаго Сло́ва Святі́й Горі́ Афо́нстій і боголюби́вим пустинножи́телем єя́ от всіх бід і наві́тов вра́жиїх в ми́рі сохрани́тися, да а́нгели святи́ми от зол ізбавля́ємі і Ду́хом Святи́м во ві́рі і братолю́бії укріпля́ємі, до сконча́нія ві́ка о Єди́ній, Святі́й, Собо́рній і Апо́стольстій Це́ркві моли́тви творя́ть і всім спаси́тельний путь указу́ють, да Це́рков земна́я і Небе́сная непреста́нно славосло́вить Творця́ і Отця́ Сві́тов, просвіща́ющи і освяща́ющи мир во ві́чній пра́вді і бла́гости Бо́жієй.","Наро́дом всего́ ми́ра іспроси́ благоде́нственнаго і ми́рнаго житія́, дух смиренному́дрія і братолю́бія, добронра́вія і спасе́нія, дух стра́ха Бо́жия, да не зло́ба і беззако́ніє ожесточа́ють сердца́ людська́я, жела́юще істреби́ти любо́в Бо́жию в челові́ціх і низве́ргнути їх в богопроти́вния вражду́ і братоуби́йства, но в си́лі Боже́ственния любве́ і пра́вди, я́коже на Небесі́, і на землі́, да святи́ться і́м'я Бо́жиє, да бу́деть во́ля Єго́ свята́я в челові́ціх і да воцаря́ться мир і Ца́рствіє Бо́жиє на землі́.","Та́кожде і земно́му оте́честву твоєму́, землі́ Украї́нській, іспроси́, уго́дниче Бо́жий, вожделі́ннаго ми́ра і Небе́снаго благослове́нія, во є́же, всемо́щним омофо́ром Ма́тере Бо́жия покрива́ємому, ізба́витися єму́ от гла́да, губи́тельства, тру́са, огня́, меча́, наше́ствія іноплеме́нников і междоусо́бния бра́ні і от всіх враг ви́димих і неви́димих, і та́ко же би́ти єму́ до сконча́нія ві́ка святі́йшему до́му Преблагослове́нния Богоро́диці, Креста́ Животворя́щаго си́лою, і в любві́ Бо́жієй неоскудіва́єму утверди́тися.","Нам же всім, во тьму гріхо́в погружа́ємим, і покая́нія те́пла, ніже́ стра́ха Бо́жия не іму́щим, і си́це безмі́рно лю́б'ящаго нас Го́спода непреста́нно оскорбля́ющим, іспроси́, о всеблаже́нне, у Всеще́драго Бо́га на́шего, да Своє́ю всеси́льною благода́тію Боже́ственне посіти́ть і оживотвори́ть ду́ші на́ша і вся́ку зло́бу і го́рдость жите́йськую, уни́ніє і нераді́ніє в сердця́х на́ших да упраздни́ть.","Єще́ мо́лимся, о є́же і нам, благода́тію Всесвята́го Ду́ха укріпля́ємим і любо́вію Бо́жиєю согрева́ємим, в человіколю́бії і братолю́бії, смиренному́дрії і моли́твеннім сраспина́нії друг за дру́га і за всіх, в пра́вді Бо́жієй утверди́тися, і в благода́тній любві́ Бо́жієй благонра́вно укріпи́тися, і синолю́бне Тому́ прибли́житися. Да та́ко, творя́ще Єго́ всесвяту́ю во́лю, во вся́ком благоче́стії і чистоті́, вре́меннаго житія́ путь непости́дно пре́йдем і со всі́ми святи́ми Небе́снаго Ца́рствія і Єго́ А́гнчаго бра́ка сподо́бимся. Єму́же от всіх земни́х і Небе́сних да бу́деть сла́ва, честь і поклоне́ніє, со Безнача́льним Єго́ Отце́м, і Пресвяти́м, і Благи́м, і Животворя́щим Єго́ Ду́хом, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Христа́ Учи́теля / в путі́ смире́нні помоли́вся прия́л єси́ / свиді́тельствующу Ду́ху в се́рдці твоє́м спасе́ніє. / Сего́ ра́ди веселя́ться ни́ні лю́діє всі / о па́м'яті твоє́й на упова́ніє зва́нії, / преподо́бне о́тче Силуа́не, // моли́ Христа́ Бо́га спасти́ся душа́м на́шим."]},{"h":"Інший тропар, глас 2","ps":["Серафи́мськия любве́ ко Го́споду пла́менний ревни́телю, / і Ієремі́ї, о наро́ді пла́чущему, / усе́рдний подража́телю, / всеблаже́нне о́тче Силуа́не, / ти зо́ву Ма́тере Го́спода сил вні́мляй, / змі́я гріхо́внаго мужему́дренно ізригну́л єси́, / і в го́ру Афо́нськую от суєти́ ми́ра удали́лся єси́, / іді́же в труді́х і моли́твах со слеза́ми / благода́ть Свята́го Ду́ха оби́льно стяжа́в, / є́юже сердця́ на́ша воспламени́ / і с тобо́ю уми́льно взива́ти укріпи́: / Го́споди мой, Жи́зне моя́ і Ра́досте Свята́я, // спаси́ мир і нас от вся́ких лю́тих."]},{"h":"Кондак, глас 2","ps":["Смиренному́дрія іспові́дниче преди́вний, / і человіколю́бія Ду́хом Святи́м согріва́ємая добро́то, / Бо́гу возлю́бленне Силуа́не, / о по́двизі твоє́м Це́рков Украї́нськая ра́дується, / і́ноці же Гори́ Афо́нськия і всі христия́нстії лю́діє, / веселя́щеся, сино́внею любо́вію к Бо́гу устремля́ються. / Єго́же моли́ о нас, равноа́нгельне богові́дче, // во є́же спасти́ся нам, в горі́нії любве́ тебі́ подража́ющим."]},{"h":"Величання","ps":["Ублажа́єм тя, / преподо́бне о́тче Силуа́не, / і чтим святу́ю па́м'ять твою́, / наста́вниче мона́хов // і собесі́дниче А́нгелов."]}],"notes":[]},{"u":"Акафіст преподобному Кукші Одеському","e":"Akathist to our Venerable Father Kuksha of Odesa","secs":[{"h":"Кондак 1","ps":["Ізбра́нний чудотво́рче і пресла́вний уго́дниче Христо́в, преди́вний іспові́дниче і неуси́пний о нас моли́твенниче, преподо́бне о́тче Ку́кшо, прославля́юще просла́вльшаго тя Го́спода, хвале́бноє пі́ніє воспису́єм ті, недосто́йнії. Ти же, я́ко імі́яй ве́ліє дерзнове́ніє ко Го́споду, от вся́ких нас іскуше́ній і бід свободи́, зову́щих ті:","Ра́дуйся, преподо́бне о́тче наш Ку́кшо, чудотво́рче і іспові́дниче Христо́в."]},{"h":"Ікос 1","ps":["А́нгела во пло́ті, распе́ншася ми́ру лука́вому зрим тя, блаже́нне о́тче. Святи́м бо преподобномученикам подража́л єси́, і́же ві́рою соді́яша пра́вду, угаси́ша си́лу о́гненную, загради́ша уста́ львов, обрати́ша в бі́гство полки́ чужди́х. Ті́мже со благогові́нієм вопіє́м ті такова́я:","Ра́дуйся, ізбра́нний би́ти світи́льником Оте́чества на́шего.","Ра́дуйся, свої́ми по́двиги і чудеси́ утверди́вий в нем ві́ру правосла́вную.","Ра́дуйся, сію́ іспові́давий да́же до кро́ве і уз.","Ра́дуйся, благи́й подража́телю житія́ вели́ких уго́дников свято́й Русі́.","Ра́дуйся, в смутноі вре́м'я богоборчеськаго шата́нія а́ки адама́нт непоколеби́мий яви́вийся.","Ра́дуйся, неізрече́нних дарова́ній сподо́бивийся.","Ра́дуйся, благода́тний і́ноков путевождю і наста́вниче.","Ра́дуйся, всіх притека́ющих к тебі́ богому́дрий духовниче́ і прозорли́вий учи́телю добротолю́бія.","Ра́дуйся, преподо́бне о́тче наш Ку́кшо, чудотво́рче і іспові́дниче Христо́в."]},{"h":"Кондак 2","ps":["Ви́дящи ма́ти твоя́ небе́сноє ізбранничество, ізмла́да на тебі́ почившеє, ра́довашеся се́рдцем і прославля́ше ди́внаго во святи́х Свої́х Бо́га. Благослови́в же тя о́бразом Каза́нськия Пресвяти́я Богоро́диці на прохожде́ніє ті́снаго і многотру́днаго мона́шеськаго житія́, принесе́ тя плод благоуха́нен Го́споду. С сим же о́бразом ніколи́же расставался єси́, пронеся благослове́ніє ма́терне чрез все по́прище земно́є, со умиле́нієм вопія́ Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум стяжа́в богопросвіще́нний от всеми́лостиваго Спа́са, вся кра́сная ми́ра от ю́ности твоєя́ презрі́л єси́, взем крест і послі́дуя Христу́. Прите́к же на поклоне́ніє во святи́й град Ієрусали́м і лобиза́я мі́сто, іді́же страдаше Госпо́дь, благи́й обі́т доброво́льнаго крестоноше́нія, і́же во і́ночестім чи́ні, прине́сл єси́. Тім таково́є проізволе́ніє твоє́ хва́ляще, вопіє́м ті:","Ра́дуйся, благослове́ніє свята́го гра́да приє́мий.","Ра́дуйся, к Небе́сному Ієрусали́му душе́ю приліпи́вийся.","Ра́дуйся, небе́сних предзнаменованій в паломничестві сем сподо́бивийся.","Ра́дуйся, і́же ба́нею пакибитія́ бисть тебі́ купі́ль Силоа́мськая, в не́йже чуде́сно пе́рвим омове́ніє прия́л єси́.","Ра́дуйся, я́ко та́я зна́менієм твоєго́ духо́внаго благопло́дія і многочадія яви́лася єси́.","Ра́дуйся, на Гро́бі Госпо́днем єле́й от лампа́ди на тя внеза́пу ізліялся єси́.","Ра́дуйся, я́ко от єле́я сего́ мно́зії лю́діє, к тебі́ прикаса́ющеся, пома́заніє прияху.","Ра́дуйся, я́ко чу́до сіє́ зна́менієм бисть неіссякаємия Боже́ственния благода́ті, чрез теб'я́ ві́рним подаваємия.","Ра́дуйся, преподо́бне о́тче наш Ку́кшо, чудотво́рче і іспові́дниче Христо́в."]},{"h":"Кондак 3","ps":["Си́ла Ви́шняго осіни́ тя, преблаже́нне, єгда́ во уді́л Богома́тері, святу́ю го́ру Афо́нськую всели́лся єси́, да і́стинний послу́шник Пресвяти́я Богоро́диці, всечестни́я Ігуме́нії всіх і́ночеських оби́телей бу́деши, поуча́яся в равноа́нгельном по́двизі і восходя́ го́ре по лі́ствице аскетичеськаго доброделанія, непреста́нно взива́я Подвигополо́жнику Христу́: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́яше воі́стину попече́ніє о спасе́нії душі́, отве́ргся разумі́нія своєго́ і во всеці́лоє послуша́ніє старцям святогорським вда́лся єси́, да ум Христо́в приобря́щеши. Сего́ ра́ди посла́ тебі́ Бог а́вву преіскусна і наста́вника неле́стна, пустинножи́теля Мелхиседе́ка, под єго́ же старчеським води́тельством от си́ли в си́лу возраста́л єси́, сподо́бльшеся постриже́нія мона́шеськаго. Сего́ ра́ди толи́кому усе́рдію твоєму́ див'я́щеся, уми́льно восклиця́єм:","Ра́дуйся, похвало́ святи́я Афо́нськия гори́.","Ра́дуйся, люби́миче вседержавния Ігуме́нії і́ночеських оби́телей.","Ра́дуйся, преподо́бних отце́в Афо́нських послу́шниче і послі́дователю.","Ра́дуйся, по́двигов їх усе́рдний рачи́телю.","Ра́дуйся, под'ємий неви́димую брань к духово́м зло́би поднебе́сния.","Ра́дуйся, приє́мий дар у́мния моли́тви Ісу́сови.","Ра́дуйся, первонача́льнику Украї́нськаго мона́шества преподо́бному Анто́нію Кі́єво-Пече́рському уподо́бивийся.","Ра́дуйся, благослове́ніє богоспасаємия гори́ в ма́тер градо́в Ру́ських принеси́й.","Ра́дуйся, преподо́бне о́тче наш Ку́кшо, чудотво́рче і іспові́дниче Христо́в."]},{"h":"Кондак 4","ps":["Бу́рю воздви́гше лю́тих іскуше́ній, враг ро́да челові́ча смуту всі́яти на Святі́й Горі́ потща́лся єси́, да ізжене́ть тя із преді́лов Афо́нських. Ти же, преподо́бне, со смире́нієм сіє́ гоне́ніє претерпі́л єси́, і прише́д в богоізбра́нний град Ки́єв в пещерной ла́вре святи́х Анто́нія і Феодо́сія всели́лся єси́, да ку́пно с преподо́бними отця́ми, зді моща́ми свої́ми нетлі́нно почива́ющими, поє́ши піснь Пресвяті́й Тро́йце: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шаша, о́тче достохва́льне, бра́тія ла́ври Кі́єво-Пече́рськия о богоуго́дном житії́ твоє́м і ви́дяще тве́рдоє во благоче́стії стоя́ніє, дивля́хуся толи́кому к соверше́нству стремле́нію твоєму́, во всем слі́довати тебі́ хотя́ще. Єгда́ же па́губния обновленчеськия пле́вели дия́вол на ни́ві церко́вній всі́ял єси́, непоколеби́мий столп чистоти́ Правосла́вія показа́лся єси́, о́тче, є́же і бра́тію в сем утверди́в, при́сно сли́шиши сія́:","Ра́дуйся, світи́ло ві́ри Правосла́вния.","Ра́дуйся, рачи́телю оте́чеських преда́ній.","Ра́дуйся, сто́лпе о́гненний, среди́ мгли безбо́жия путь спасе́нія показу́ющий.","Ра́дуйся, в па́губноє вре́м'я єрети́чеських поползновеній твої́ми моли́твами бра́тію утверди́вий.","Ра́дуйся, всім лю́дем примі́р і́стиннаго богопочитанія показа́вий.","Ра́дуйся, зі́льні разженную пещ богоборчества росо́ю іспові́данія твоєго́ угаси́вий.","Ра́дуйся, преподо́бному Ку́кше, іспові́днику і му́ченику Кі́єво-Пече́рському уподо́бивийся.","Ра́дуйся, вся по́двиги уго́дников Кі́єво-Пече́рських унаслі́довавий.","Ра́дуйся, преподо́бне о́тче наш Ку́кшо, чудотво́рче і іспові́дниче Христо́в."]},{"h":"Кондак 5","ps":["Боготе́чная звізда́ су́щим во мра́ці гріхо́внім яви́лся єси́, свя́те, осіява́я град і лю́ди ве́лії чуде́с світлостьми́. Та́ко і пророчеського обітова́нія от святи́теля Серафи́ма Полтавськаго сподо́бился єси́, єгда́ ста́рець сей богопросвіще́нний, благослове́ніє архипа́стирськоє подая́ ті, проре́к: “В сих пеще́рах мі́сто тебі́ угото́вано!”, дая́ разумі́ти, я́ко Госпо́дь просла́вить тя обрі́тенієм нетлі́нних моще́й. Зря́ще же ни́ні ісполне́ніє ди́внаго сего́ прорече́нія, со благогові́нієм лобиза́єм святи́я мо́щі твоя́, пою́ще: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дів тя подви́жника ві́ри і благоче́стія побо́рника, задумаша нечести́вії погуби́ти тя, вдавша на муки́ і в темни́цю заключи́ша. Ти же, я́ко му́ченик тверд, ні во что же вміни́л єси́ вра́жия уме́ти, взира́я на Боже́ственнаго Страстоте́рпця і слі́дуя Єго́ долготерпі́нію. Сего́ ра́ди ублажа́єм тя си́це:","Ра́дуйся, ше́ствовавий за Господом да́же до Голгофських мук.","Ра́дуйся, ісповедничеством просія́вий.","Ра́дуйся, многоразли́чния страда́нія от богобо́рцев приє́мий.","Ра́дуйся, ті́ї я́ко к тате́м і разбо́йником, а́ки о́вцю к лю́тим волкам, вверго́ша тя.","Ра́дуйся, сих я́ко звіре́й ди́віїх смире́нієм твої́м укроти́л єси́.","Ра́дуйся, мраз нестерпи́мий і жесто́коє ізнуре́ніє в сиби́рстій тайге му́жественно претерпі́л єси́.","Ра́дуйся, утіше́ніє ті Госпо́дь я́ко Ілії́ чрез вра́на небе́снаго пода́вий і гла́дом му́чима напита́вий.","Ра́дуйся, от лю́тия болі́зні, от нея́же імі́яше умре́ти, тя чуде́сно ізба́вивий.","Ра́дуйся, преподо́бне о́тче наш Ку́кшо, чудотво́рче і іспові́дниче Христо́в."]},{"h":"Кондак 6","ps":["Пропові́дник богоно́сний Бо́жия благода́ті яви́лся єси́, па́стирю благи́й, єгда́ от єпи́скопа Ки́євськаго Анто́нія Боже́ственния Да́ри прия́л єси́, та́йно во узи́лищі по́сланния, і не то́кмо сам благогові́йно сих приобщи́вийся, но і та́їнство і́сповіді устро́їв, содержи́мих во у́зах і́ночествующих бра́тій і сесте́р прича́стники Животворя́щих Та́їн сотвори́. Бисть же сія́ Свята́я Трапе́за я́ко Ве́черя Та́йная ученико́в Христа́ Бо́га, я́ко Па́сха сві́тлая среди́ юдо́лі ско́рбния, я́ко П'ятидеся́тниця, ізлія́вшая нань струї́ огневи́днаго Ду́ха. Получи́вшії же такову́ю ми́лость, возсилаху те́плоє благодаре́ніє Бо́гу і уго́днику Єго́, пою́ще: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ тебі́ світ ми́лости Своєя́ Христо́с Ізба́витель, єгда́ в день церко́вния па́м'яті великому́ченика Гео́ргия Побідоно́сця із мра́чния темни́ці ізведе́н бисть, страда́льче, ніка́коже побіжде́н от врага́, хотя́ща низложи́ти тя. Оба́че нов по́двиг предстоя́ще ті, о́тче пра́ведний, я́ко сослан бисть дале́че на поселеніє, і претерпіва́ше та́мо ну́жду ве́лію, не іми́й гді глави́ подклони́ти. Сего́ ра́ди вопіє́м ті:","Ра́дуйся, библейським праведникам подража́вий.","Ра́дуйся, я́ко тіх, і́же пройдо́ша в ми́лотіх і ко́зіїх ко́жах, житію́ поревнова́вий.","Ра́дуйся, в лише́ніїх, озлобле́ніїх і ско́рбіх тече́ніє твоє́ безро́потно соверша́л єси́.","Ра́дуйся, подо́бно тім, ї́хже не бі досто́їн весь мир, скита́ніє по пусти́ням, вертепам і про́пастем земни́м под'ял єси́.","Ра́дуйся, я́коже і о́нім, і́же послуше́ствовани би́вше ві́рою, тебі́ обітова́ніє дарова́ся.","Ра́дуйся, дар неізрече́нних чудотворе́ній в награ́ду ті от Го́спода низпослася.","Ра́дуйся, я́ко Бог утіша́ше тя, і до́брих люде́й, я́коже Ілії́ вдови́цю, тебі́ ниспосилаше.","Ра́дуйся, я́коже чрез Ілію́, ве́ліє благослове́ніє чрез тя на до́ми, тебі́ прия́вшая, нисхождаше.","Ра́дуйся, преподо́бне о́тче наш Ку́кшо, чудотво́рче і іспові́дниче Христо́в."]},{"h":"Кондак 7","ps":["Хотя́ Всеви́дець Госпо́дь яви́ти тя світи́льника держа́ви на́шея, і не под спу́дом, а на сві́щниці висо́ком поста́вити, па́ки в ла́вру Кі́єво-Пече́рськую возврати́, да явле́н бу́деши ми́рові. Лю́діє же правосла́внії а́ки би́сер многоці́нний обрі́тшії тя, ра́довахуся неізрече́нно і возсилаху благода́рственноє пі́ніє Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вая чудеса́ показа́ нам тобо́ю, преподо́бне, всіх чуде́с Творе́ць і Влади́ка, отовсю́ду бо притекающия к тебі́ от неду́гов душе́вних і тіле́сних врачева́л єси́, бі́сния от злих духо́в свобожда́л єси́, гряду́щая я́ко настоя́щая прорицял єси́, гріхо́вния я́зви облича́л єси́, всім подава́я потре́бная ко спасе́нію. Лю́діє же, от толи́ких бід ізба́вленнії тобо́ю, с весе́лієм взива́ху ті:","Ра́дуйся, я́ко преди́вна чудотво́рця Це́рков свята́я в тебі́ обріла́ єси́.","Ра́дуйся, я́ко сла́во чуде́с твої́х всю зе́млю на́шу осіява́ше.","Ра́дуйся, врачу́ душ і тіле́с благода́тний.","Ра́дуйся, покая́нія учи́телю духоно́сний.","Ра́дуйся, схимниче прозорли́вий і святи́й.","Ра́дуйся, ста́рче бла́гостний і кро́ткий.","Ра́дуйся, духо́в зло́би прогони́телю дерзнове́нний.","Ра́дуйся, я́ко бі́си, не терп'я́ще сві́тлости зра́ка твоєго́, дале́че от тебе́ отбіга́ху.","Ра́дуйся, преподо́бне о́тче наш Ку́кшо, чудотво́рче і іспові́дниче Христо́в."]},{"h":"Кондак 8","ps":["Стра́нник многоскорбний яви́лся єси́, о́тче блаже́нне, іспо́лнив на себі́ сло́ва апо́стола, я́ко всі, хотя́щії жи́ти благоче́стно, гони́ми бу́дуть. Власть бо іму́щия богобо́рці ізгна́ша тя із ла́ври пещерния, і в Почаєв ізведо́ша. Оба́че Бо́жиїм проізволе́нієм ісхо́д твой із Ки́євськия оби́телі в Поча́євськую соверши́ся, да і та́мо просія́єши житіє́м твої́м, поя́ Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Всі і́ноці святи́я гори́ Поча́євськия в ра́достний тре́петь прийдо́ша, ви́дящи, какова́ пречестна́ отця́ обріта́ють, доброді́тельми мона́шеськими презі́льні укра́шена і ув'язена вінці́ му́ченичеськими. Сего́ ра́ди почита́ху тя си́ми словеси́:","Ра́дуйся, я́ко Сама́ Пречи́стая Богома́ти, чудотво́рною іко́ною зді пребива́ющая і слід стопи́ Своєя́ на горі́ сей оставившая, во оби́тель прия́т тя.","Ра́дуйся, я́ко гора́ сія́ для теб'я́ втори́й Афо́н бя́ше.","Ра́дуйся, свято́му ігу́мену ла́ври І́ову Поча́євському во всем уподо́бивийся.","Ра́дуйся, неви́димаго сослуже́нія с преподо́бним І́овом мно́гажди сподо́бивийся.","Ра́дуйся, я́коже і он, богопротивним теченіям уніятським і раскольничеським тве́рдо противостоя́л єси́.","Ра́дуйся, осліпле́нних поги́бельними єресьми́ в ло́но Єди́ния І́стинния Святи́я Собо́рния і Апо́стольськія це́ркве направля́л єси́.","Ра́дуйся, на Боже́ственной Євхари́стії ангелоподо́бно в сія́нії сві́тлом Бо́гу предстоя́л єси́.","Ра́дуйся, і ча́дам твої́м духо́вним благода́ть моли́твеннаго обще́нія с Бо́гом дарова́л єси́.","Ра́дуйся, по сле́зним моли́твам чад твої́х духо́вних от тя́жкаго неду́га і преждевременния кончи́ни ізба́влен бил єси́.","Ра́дуйся, преподо́бне о́тче наш Ку́кшо, чудотво́рче і іспові́дниче Христо́в."]},{"h":"Кондак 9","ps":["Вся́коє єстество́ челові́чеськоє удиви́ся превели́кому на тебі́ Бо́жию благоволе́нію, моли́твенниче блаже́нне, непристу́пнаго бо Го́спода Сла́ви, Єго́же і а́нгели зрі́ти не мо́гуть, непреста́нно зрел єси́ вну́тренними духо́вними очеси́, вперя́я ум ко го́рняя і ви́ну поя́ Созда́телю своєму́: Аллилу́я."]},{"h":"Ікос 9","ps":["Вити́йствовати не іску́сен бил єси́, ста́рче смире́нний, оба́че я́коже Марі́ю Єги́петськую Бог Ду́хом Свої́м просвіща́ше тя, Єва́нгеліє бо і псалми́ Дави́дови ізу́стно вся ві́дий, слу́жбу церко́вную нікогда́ же претикаяся на па́м'ять соверши́л єси́, і не імі́яше богосло́вськаго позна́нія, Писа́ніє я́коже богодухнове́нний богосло́в ізря́дно толковал єси́, открива́я свяще́нния глубини́ та́їн Бо́жиїх. Сему́ див'я́щеся, вопіє́м ті: ра́дуйся, му́дростію сви́ше озаре́нний.","Ра́дуйся, Ду́хом Святи́м осіне́нний.","Ра́дуйся, я́ко в не́мощі твоє́й си́ла Бо́жия всемо́щно соверши́ся.","Ра́дуйся, я́ко от бога́тства слове́с твої́х ни́щії ду́хом обогаща́ються.","Ра́дуйся, я́ко от оте́чеських наставле́ній твої́х а́лчущії і жа́ждущії пра́вди насища́ються.","Ра́дуйся, ді́я учи́вий презира́ти у́бо плоть, прехо́дить бо.","Ра́дуйся, приме́ром свої́м мно́гих подви́гнувий приліжа́ти душі́, ве́щі безсме́ртній.","Ра́дуйся, ті́мже со а́нгели сра́дується, преподо́бне, дух твой.","Ра́дуйся, преподо́бне о́тче наш Ку́кшо, чудотво́рче і іспові́дниче Христо́в."]},{"h":"Кондак 10","ps":["Спасе́ніє і от ві́чния поги́белі ізбавле́ніє всім, с ві́рою і наде́ждею приходящим к тебі́ бил єси́, о́тче свяще́нне, ізима́я от ро́ва гріхо́вних страсте́й і па́губних вожделі́ній, і возводя́ к Небе́сному Ца́рствію, іді́же ти ни́ні с ли́ки святи́х предстої́ши престо́лу Го́спода Сил, моля́ся о нас, ча́діх твої́х, і Бо́гу воспіва́я: Аллилу́я."]},{"h":"Ікос 10","ps":["Весь бил єси́ во ви́шніх, а́вво досточу́дне, совлеки́йся ве́тхаго челові́ка с дія́ньми єго́ і облеки́йся во Христа́, Єго́ же всім се́рдцем возлюби́л єси́. Ті́мже дарова́ся тебі́ благода́ть ве́лія от Го́спода, да всі моли́твенно взива́ють ті:","Ра́дуйся, ді́лателю неуси́пний, мног плод сотвори́вий.","Ра́дуйся, дре́вніх отце́в мона́шества Анто́нія, Пахо́мія і Мака́рія учениче́ і наслі́дниче.","Ра́дуйся, я́коже преподо́бний Се́ргій Радонежський, всеусе́рдний служи́тель Пресвяти́я Тро́йці би́вий.","Ра́дуйся, подо́бні Серафи́му Саро́вському, пасхальним приветствієм “Христо́с воскре́се!” ка́ждаго приходя́щаго к тебі́ лобизавий.","Ра́дуйся, преподо́бному Амвро́сію Оптинському уподобля́яся, всіх дітьми́ свої́ми нарицявий.","Ра́дуйся, преподо́бному Силуа́ну Афо́нському в созерца́нії і богоми́слії следовавий.","Ра́дуйся, я́ко стяжа́л єси́ дух ми́рен, і о́крест тебі́ ти́сячі спасе́ніє обріто́ша.","Ра́дуйся, тобо́ю бо Госпо́дь показа́, я́ко не оскуді́ преподо́бния в Русі́ Правосла́вній.","Ра́дуйся, преподо́бне о́тче наш Ку́кшо, чудотво́рче і іспові́дниче Христо́в."]},{"h":"Кондак 11","ps":["Пі́ніє всеумиле́нноє приноша́ху ті жи́теліє богоспаса́ємаго гра́да Одесси, преподо́бне Ку́кшо, і́мже Госпо́дь я́ко зла́то неветшающеє, в горни́лі бід іскушенноє і очище́нноє седьмери́цею, дарова́ тя, да бу́деши мі́сту сему́ всемогущний засту́пник і покрови́тель, сохраня́я єго́ от стихийних бід і многоразли́чних обстоя́ній. Ті́мже і оби́тель Успе́нія Пресвяти́я Богоро́диці, в ней же ни́ні мо́щі твоя́ святи́я почива́ють, і́менем твої́м красу́яся, Бо́гу прино́сить піснь хвале́бно-благода́рственную: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоза́рная лампада, єле́й цільбоно́сния благода́ті істоча́ющая, яви́шася честни́я мо́щі твоя́, преподо́бне, от них бо то́ки чуде́с ізлива́ються, неду́ги отгоня́я, от одра́ сме́ртнаго возставля́я, душі́ возвеселя́я, ко́зні дия́вольськия побіжда́я. Ті́мже отці́ і бра́тія Свя́то-Успе́нськия оби́телі, каждодневно моле́бен пред ра́кою моще́й твої́х соверша́юще, с любо́вію возглаша́ють ті:","Ра́дуйся, хра́мино преукраше́нная Ду́ха всесвята́го.","Ра́дуйся, кади́льниця благово́нная, фимія́м благи́х діл воскуряющая.","Ра́дуйся, честни́й ковче́же сокро́вищ неоскудеваємих.","Ра́дуйся, сосу́де драгоці́нний даро́в неісчерпа́ємих.","Ра́дуйся, нетлі́нієм моще́й зіло́ от Бо́га просла́вленний.","Ра́дуйся, ізлія́нієм чуде́с от Го́спода возвеличенний.","Ра́дуйся, я́ко ні єди́н тощ іли́ неусли́шан от моще́й твої́х ісхо́дить.","Ра́дуйся, я́ко многоціле́бния твоя́ мо́щі гра́да сего́ бисть всемо́щноє защище́ніє і оби́телі на́шея благолі́пноє украше́ніє.","Ра́дуйся, преподо́бне о́тче наш Ку́кшо, чудотво́рче і іспові́дниче Христо́в."]},{"h":"Кондак 12","ps":["Благода́ть пода́ждь нам, а́вво богому́дре, і по́мощ Бо́жию іспроси́, да возмо́жем, поуча́яся твої́м ісправленіям, твори́ти во́лю Спаси́теля благу́ю, благоуго́дную і соверше́нную, і пожи́вше в преподо́бії і пра́вді, сподо́бимся с тобо́ю во ві́ці гряду́щем пі́ти Созда́телю піснь несконча́ємую: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще твоє́ богобоязненноє і чи́стоє житіє́, похваля́єм многоболезния ісповедничеськия труди́ твоя́, почита́єм схимничеськия по́двиги, превозно́сим в моли́тві пла́менноє горе́ніє і к Бо́гу дерзнове́ніє, чтим многопопечительноє ві́рних окормле́ніє і па́стирськоє вразумле́ніє, сла́вим пло́ті умерщвле́ніє і безропотноє скорбе́й понесеніє, я́же любве́ ра́ди Бо́жия благоду́шне под'ял єси́, о́тче святи́й і превели́кий. Яви́лся бо єси́ нам, в послі́дняя лі́та живу́щим, світи́льник горя́й і согреваяй, да ма́ло пора́дуємся при сві́ті єго́. Не оста́ви же си́рими чад твої́х, сподо́би оте́чеськаго попече́нія твоєго́, да ві́домії тобо́ю к духо́вному соверше́нству, ви́ну тебі́ воспіва́єм і зове́м:","Ра́дуйся, к ли́ку святи́х і преподо́бних сопричтенний.","Ра́дуйся, в го́рній Ієрусали́м досточестне прия́тий.","Ра́дуйся, в кни́зі жи́зні злати́ми буквами начерта́нний.","Ра́дуйся, со всі́ми, Бо́гу угоди́вшими, на брак А́гнчий возше́дий.","Ра́дуйся, ри́зу твою́ бра́чную па́че сні́га убеливий.","Ра́дуйся, я́ко побіжда́ющий віне́ць пра́вди унаслі́довавий.","Ра́дуйся, престо́лу Влади́ки предстоя́й, те́плі о нас хода́тайствуєши.","Ра́дуйся, о всіх, і́м'я твоє́ свято́є призива́ющих, дерзнове́нно предста́тельствуєши.","Ра́дуйся, преподо́бне о́тче наш Ку́кшо, чудотво́рче і іспові́дниче Христо́в."]},{"h":"Кондак 13","ps":["О преподо́бне і богоно́сне о́тче наш Ку́кшо, превели́кий уго́дниче і преди́вний чудотво́рче! При́зри на нас, во обстоя́нії гріхо́внім су́щих і во тьмі неві́дінія претикающихся, і богоприя́тним твої́м хода́тайством страх Бо́жий всели́ в се́рдця на́ша, плотсько́є мудрова́ніє умертви́, от іскуше́ній сохрани́, правосла́віє утверди́, да во благоче́стії і правові́рії іждиве́м ма́лоє число́ дній на́ших, і ізба́вльшеся от ві́чних мук а́дських, сподо́бимся в бесконечном ві́ці совокупно с тобо́ю славосло́вити Бо́га, в Тро́йці покланя́ємаго, воспіва́я Єму́: Аллилу́я, аллилу́я, аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгела во пло́ті, распе́ншася ми́ру лука́вому зрим тя, блаже́нне о́тче. Святи́м бо преподобномученикам подража́л єси́, і́же ві́рою соді́яша пра́вду, угаси́ша си́лу о́гненную, загради́ша уста́ львов, обрати́ша в бі́гство полки́ чужди́х. Ті́мже со благогові́нієм вопіє́м ті такова́я:","Ра́дуйся, ізбра́нний би́ти світи́льником Оте́чества на́шего.","Ра́дуйся, свої́ми по́двиги і чудеси́ утверди́вий в нем ві́ру правосла́вную.","Ра́дуйся, сію́ іспові́давий да́же до кро́ве і уз.","Ра́дуйся, благи́й подража́телю житія́ вели́ких уго́дников свято́й Русі́.","Ра́дуйся, в смутноі вре́м'я богоборчеськаго шата́нія а́ки адама́нт непоколеби́мий яви́вийся.","Ра́дуйся, неізрече́нних дарова́ній сподо́бивийся.","Ра́дуйся, благода́тний і́ноков путевождю і наста́вниче.","Ра́дуйся, всіх притека́ющих к тебі́ богому́дрий духовниче́ і прозорли́вий учи́телю добротолю́бія.","Ра́дуйся, преподо́бне о́тче наш Ку́кшо, чудотво́рче і іспові́дниче Христо́в."]},{"h":"Кондак 1","ps":["Ізбра́нний чудотво́рче і пресла́вний уго́дниче Христо́в, преди́вний іспові́дниче і неуси́пний о нас моли́твенниче, преподо́бне о́тче Ку́кшо, прославля́юще просла́вльшаго тя Го́спода, хвале́бноє пі́ніє воспису́єм ті, недосто́йнії. Ти же, я́ко імі́яй ве́ліє дерзнове́ніє ко Го́споду, от вся́ких нас іскуше́ній і бід свободи́, зову́щих ті:","Ра́дуйся, преподо́бне о́тче наш Ку́кшо, чудотво́рче і іспові́дниче Христо́в."]},{"h":"Молитва","ps":["О, преподо́бне і богоно́сне о́тче наш Ку́кшо, оби́телі Успе́нія Бо́жієй Ма́тері похвало́, богоспаса́ємаго гра́да Оде́сси неув'яда́ємий цві́те, кро́ткий па́стирю Христо́в і вели́кий за нас моли́твенниче. Усе́рдно к тебі́ прибіга́єм і с сокруше́нним се́рдцем про́сим: не отими́ покро́в твой от оби́телі на́шей, в не́йже по́двигом до́брим подвиза́лся єси́. Бу́ди помо́щник благи́й всім благоче́стно живу́щим і до́брі тружда́ющимся в ней. О, до́брий наш па́стирю і богому́дрий наста́вниче, преподо́бне о́тче Ку́кшо, при́зри ми́лостивно на предстоя́щия лю́ди, умиле́нно моля́щіяся і прося́щия от тебе́ по́мощі і заступле́нія. Пом'яни́ всіх, ві́ру і любо́в к тебі́ іму́щих, і́м'я твоє́ моли́твенно призива́ющих і на поклоне́ніє моще́м твої́м святи́м приходя́щих, і вся во благи́х проше́нія їх ми́лостивно іспо́лни, осіня́я їх святооте́чеським твої́м благослове́нієм. Ізба́ви, святи́й о́тче, от вся́каго наві́та вра́жия Це́рков на́шу святу́ю, град сей,' оби́тель і зе́млю на́шу, і не оста́ви заступле́нієм твої́м нас немощни́х, гріха́ми і скорб'я́ми мно́гими обремене́нних. Озари́, преблаже́нне, ум наш сві́том лиця́ Бо́жия, укріпи́ благода́тію Госпо́дней жизнь на́шу, да в зако́ні Христо́ві утверди́вшеся, нелі́ностно по путі́ за́повідей святи́х потеце́м. Осіни́ твої́м благослове́нієм нас, і всіх в ско́рбіх су́щих, болі́зньми душе́вними і тіле́сними одержи́мих, ісціле́ніє, утіше́ніє і ізбавле́ніє да́руя. Над всі́ми же си́ми іспроси́ нам сви́ше дух кро́тости і смиренному́дрія, дух терпі́нія і покая́нія, отступи́вшим от правосла́вния ві́ри і поги́бельними єресьми́ і раско́лами ослепле́нним вразумле́ніє, во тьмі неві́рія блужда́ющим сві́том і́стиннаго богопозна́нія просвіще́ніє, раздо́ров і нестроє́ній утоле́ніє. Умоли́ Го́спода Бо́га і Пресвяту́ю Богоро́дицю дарова́ти нам ти́хоє і безгрі́шноє житіє́. Помина́й нас недосто́йних у престо́ла Вседержи́теля, і іспроси́ ми́рную христия́нськую кончи́ну, і сподо́би нас по́мощію твоє́ю спасе́ніє ві́чноє улучи́ти і Ца́рствіє Небе́сноє унаслі́довати, да славосло́вим ве́лія щедро́ти і неізрече́нния ми́лости Отця́ і Си́на і Свята́го Ду́ха, в Тро́йці покланя́ємаго Бо́га, і твоє́ оте́чеськоє заступле́ніє во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["От ю́ности мир суєму́дренний і лука́вий оста́вил єси́, / Боже́ственною сви́ше просвіти́вся благода́тію, преподо́бне, / мно́гим терпі́нієм во вре́менній жи́зні по́двиг соверши́л єси́, / ті́мже істоча́єши чуде́с благода́ть всім с ві́рою приходя́щим к ра́ці моще́й твої́х, // Ку́кшо, преблаже́нне о́тче наш."]},{"h":"Кондак, глас 8","ps":["Подви́жника благоче́стія іску́сна, / но́ваго іспові́дника ві́ри оте́чеськия / преподо́бнаго Ку́кшу ві́рно всі ублажи́м, / я́ко па́стиря і́стиннаго, / ста́рця бла́гостнаго, і́ноков наста́вника, / уті́шителя малоду́шних, ціли́теля неду́жних, / і по кончи́ні показу́ющаго сві́тлость житія́ своєго́. / І днесь в па́м'ять єго́ прите́кше, ра́достно возопіє́м: / я́ко імі́я дерзнове́ніє к Бо́гу, / многообра́зних нас ізба́ви обстоя́ній, да зове́м ті: // ра́дуйся, утвержде́ніє лю́дем правосла́вним."]},{"h":"Величання","ps":["Ублажа́єм тя, / преподо́бне о́тче Ку́кшо, / і чтим святу́ю па́м'ять твою́, / наста́вниче мона́хов // і собесі́дниче А́нгелов."]}],"notes":[]},{"u":"Акафіст преподобному Феофілу Київському","e":"Akathist to our Venerable Father Theophilus of Kyiv","secs":[{"h":"Кондак 1","ps":["Ізбра́нний Бо́гом от чре́ва ма́тері своєя́ на по́двиг юро́дства при́зван бил єси́, си́лою Бо́жієй от водна́го потопле́нія мно́гажди храни́мий, по́двигом поста́ і моли́тви врага́ ро́да челові́чеськаго посрами́вий. Сего́ ра́ди, соверша́я па́м'ять твою́, мо́лим тя, преди́вний о́тче Фео́филе, ізба́ви нас от враг ви́димих і неви́димих, с любо́вію зову́щих ті:","Ра́дуйся, преподо́бне о́тче наш Фео́филе, по́двигом юро́дства твоєго́ на путь спасе́нія нас наставля́ющий."]},{"h":"Ікос 1","ps":["А́нгели небе́снії і челові́ци земні́ї богоізбра́нному житію́ твоєму́ удивля́шеся, о́тче Фео́филе, ка́ко ті младе́нцю су́щу от млека́ ма́тері своєя́ лице́ своє́ отвраща́л єси́, принима́я пи́щу то́кмо по́стную. Сим зна́менієм Госпо́дь показа́ лю́дем, я́ко ти єси́ ізбра́нник Бо́жий, не от ми́ра сего́ бисть. Див'я́щеся таково́му по́стничеському воздержа́нію твоєму́, со умиле́нієм зове́м ті си́це:","Ра́дуйся, ізбра́нниче Бо́жий от чре́ва ма́тері;","Ра́дуйся, пречестна́я о́трасль ієре́я Бо́жия.","Ра́дуйся, по́стничеським по́двигом твої́м Крести́телю Госпо́дню уподо́бивийся.","Ра́дуйся, воздержа́нієм такови́м роди́телей і сро́дников свої́х удиви́вий.","Ра́дуйся, ізмла́да Бо́га возлюби́вий.","Ра́дуйся, за́повіді Єго́ ві́рно сохрани́вий.","Ра́дуйся, преподо́бне о́тче наш Фео́филе, по́двигом юро́дства твоєго́ на путь спасе́нія нас наставля́ющий."]},{"h":"Кондак 2","ps":["Ви́дяще тя сосу́д Ду́ха Свята́го, Бо́гом ізбра́нний, враг ро́да челові́чеськаго не моги́й терпі́ти тя, возжелі́ погуби́ти тя, младе́нче святи́й, подви́гнувий на сіє́ дітоуби́йство ма́тер твою́. Бог же, хранящий младе́нці Своя́, не попусти́ злодеянію сему́ соверши́тися. За такову́ю ми́лость Єго́ к тебі́, поє́м Єму́: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум ма́тері твоєя́ по науще́нію дия́вольському помрачи́ся, і возненавидяше тя, непоро́чна младе́нця. Сего́ ра́ди повелі́ служащей в до́мі діви́це утопити тя в ріці́. А́нгел же Бо́жий сохрани́ тя невреди́ма. Ми же, див'я́щеся чу́ду сему́, с ра́достію вопіє́м ті:","Ра́дуйся, сосу́де, Бо́гом ізбра́нний і Їм же храни́мий.","Ра́дуйся, младе́нче святи́й, дия́вола устраши́вий.","Ра́дуйся, от пеле́н младенчеських гоне́ніє от ма́тері своєя́ претерпі́вий.","Ра́дуйся, от потопле́нія си́лою Бо́жієй сохраненний.","Ра́дуйся, от чре́ва ма́тері на служе́ніє Бо́гу предизбранний.","Ра́дуйся, Про́мислом Бо́жиїм в жи́зні твоє́й всегда́ води́мий.","Ра́дуйся, преподо́бне о́тче наш Фео́филе, по́двигом юро́дства твоєго́ на путь спасе́нія нас наставля́ющий."]},{"h":"Кондак 3","ps":["Чу́до пресла́вноє тобо́ю сотвори́ Госпо́дь, єгда́ ти бисть вве́ржений в ріці́, си́лою Бо́жієй держи́мий на версі́ води́ невредимий і, а́ки в колибелі м'ягцей, на волна́х безм'яте́жно спал єси́. Діви́ця же, вве́ргшая тя, іспо́лнися стра́ха і умиле́нія, возопи́ ди́вному Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Боя́щеся принести́ тя в дом к жесто́кой ма́тері твоє́й, діви́ця со слеза́ми жа́лости к тебі́, осіни́ тя крестним зна́менієм і па́ки вве́рже тя спя́щаго во во́ду. І па́ки чу́до проізи́де: во́лни річни́я а́ки крила а́нгельськия понесоша тя к бре́гу землі́. І діви́ця, а́ки Мойсе́я, взя із води́ тя і понесе́ в дом твой, трепе́ща і ужаса́шеся. Ми же, див'я́щеся таково́му промишле́нію Бо́жию о тебі́, глаго́лем:","Ра́дуйся, я́ко тобо́ю ди́вен Бог во святи́х Свої́х прославля́ється.","Ра́дуйся, я́ко а́нгел твой храни́тель пі́стуном бисть тебі́.","Ра́дуйся, я́ко ти Мойсе́ю, волна́ми рі́чними носи́мому, уподо́бивийся.","Ра́дуйся, я́ко і тебі́, а́ки Но́я, от потопле́нія Бог сохрани́вий.","Ра́дуйся, сим чу́дом в страх і тре́петь о́крест живу́щих приведи́й.","Ра́дуйся, я́ко тобо́ю і ми упова́ти на Бо́га науча́ємся.","Ра́дуйся, преподо́бне о́тче наш Фео́филе, по́двигом юро́дства твоєго́ на путь спасе́нія нас наставля́ющий."]},{"h":"Кондак 4","ps":["Бу́рю я́рости і зло́би воздви́же на тя ма́ти твоя́, єгда́ ви́дя тя жива́ і здра́ва после потопле́нія, і сама́ свої́ма рука́ма возжелі́ погуби́ти тя, святи́й младе́нче; побіже́, окая́нная, к ріці́ і вве́рже тя во во́ду под са́моє колесо́ мельничноє. Оба́че і на сей раз Госпо́дь ди́вно сохрани́ тя жива́, даби́ всі, видящиє чу́до сіє́, воспіва́ли Єму́ благода́рственно-хвале́бную піснь: Аллилу́я."]},{"h":"Ікос 4","ps":["Рече́ псалмопі́вець, я́ко «Госпо́дь сохрани́ть тя от всякого зла. Госпо́дь сохрани́ть вхожде́ніє твоє́ і ісхожде́ніє от ни́ні і до ві́ка», і «не убою́ся, что сотвори́ть мні челові́к» - сі́ї словеса́ сби́шася воочію на тебі́, преди́вний о́тче Фео́филе. Си́лою Бо́жієй колесо́ водно́є остановися, а вода́ воспенишася. Мельник же в ізумленії побіже́ і, ви́дя тя лежа́ща под колесом, взя́ша тя, а́ки драгоці́нний дар Бо́жий, взива́я к тебі́ та́ко:","Ра́дуйся, сокро́вище многоці́нноє, мні Бо́гом да́нноє.","Ра́дуйся, Бо́гом храни́мий младе́нче святи́й.","Ра́дуйся, я́ко си́ла Бо́жия тобо́ю нам явля́ється.","Ра́дуйся, я́ко і́м'я Бо́жиє тобо́ю прославля́ється.","Ра́дуйся, сосу́де ізбра́нний, во є́же служи́ти Бо́гові і наставля́ти лю́ди ко спасе́нію нам дарова́нний.","Ра́дуйся, я́ко крест долготерпі́нія і злострада́нія угото́вася тебі́.","Ра́дуйся, преподо́бне о́тче наш Фео́филе, по́двигом юро́дства твоєго́ на путь спасе́нія нас наставля́ющий."]},{"h":"Кондак 5","ps":["Страх і тре́петь об'ят всіх о́крест живу́щих, ви́дящих ди́вноє чу́до сіє́. Ма́ти же твоя́, не уразумі́ си́лу Бо́жию, на тебі́ явля́ємую, па́че озло́бися лю́тостію зіло́ вели́кою і даде́ кля́тву погуби́ти тя. Тогда́ оте́ць твой, ієре́й Бо́жий, даби́ сохрани́ти тя жива́, скри тя у сро́дников свої́х. Ми же див'я́щеся кова́рству ма́тері-уби́йці, і, сла́в'я прему́дрость Бо́жию, поє́м: Аллилу́я."]},{"h":"Ікос 5","ps":["«Не при́йдеть к тебі́ зло і ра́на не прибли́житься тілесі́ твоєму́, я́ко а́нгелом Свої́м запові́сть о тебі́, сохрани́ти тя на всіх путеіх твої́х». Сі́ї словеса́ із Псалти́ри, с не́ю же ти не разлучавийся во вся дні житія́ твоєго́, пресла́вно сби́шася на тебі́, о преди́вний о́тче Фео́филе. І в па́м'ять трикра́тнаго спасе́нія от сме́рти ти желі́зний обруч с іко́ною Богоявле́нія на ті́лі своє́м всегда́ носи́вий. Ми же, ра́дующеся таково́му о тебі́ Бо́жию промишле́нію, со умиле́нієм зове́м тебі́:","Ра́дуйся, я́ко от потопле́нія водна́го три́жди си́лою Бо́жиєю сохраненний.","Ра́дуйся, я́ко сим чу́дом Бо́жию Прему́дрость нам яви́вий і кова́рство дия́вола посрами́вий.","Ра́дуйся, трикра́тним погруже́нієм во во́ду Святу́ю Тро́йцю просла́вивий.","Ра́дуйся, я́ко і ни́ні со всі́ми святи́ми предстої́ши у Престо́ла Святи́я Тро́йці.","Ра́дуйся, я́ко непреста́нним чте́нієм Псалти́ри ти ду́шу свою́ услаждавий і лю́дем образець моли́тви показа́вий.","Ра́дуйся, о́тче Фео́филе, преди́вний чудотво́рче і моли́твенниче о душа́х на́ших.","Ра́дуйся, преподо́бне о́тче наш Фео́филе, по́двигом юро́дства твоєго́ на путь спасе́нія нас наставля́ющий."]},{"h":"Кондак 6","ps":["Чужди́й ми́ра і всего́ я́же в нем, ти всегда́ презираємий бисть све́рстники твої́ми. Глумле́нія над тобо́ю і же́стокия біє́нія от них претерпіва́я, ти безро́потно тя́жкий крест житія́ своєго́ понеси́й. С во́плем і оби́льними слеза́ми, убіга́я в де́бри лесния, ти младенчеськими усти́ свої́ми безгрі́шно, яки а́нгел Бо́жий, взива́л к Отцю́ Небе́сному: Аллилу́я."]},{"h":"Ікос 6","ps":["Стра́нником і прише́льцем яви́лся єси́ на землі́ сей, многострада́льне о́тче Фео́филе. Єще́ живу́ би́ти роди́телем твої́м, ти бил ізгна́н із до́ма оте́чеськаго. А роди́вшая тя єще́ под'я і ру́ці своя́, даби́ сіки́рою умертви́ти тя. До́брий же ктитор, об'я тя окровавленнаго, спа́се тя от ма́тері-уби́йці. І ти, не імі́я гді глави́ преклони́ти і чем препитатися, води́мий Ду́хом Святи́м, устреми́лся єси́ во храм Бо́жий, іді́же ізлія́л Бо́гу скорб младе́нчеськия душі́ твоєя́.","За таково́є страда́льчеськоє житіє́ твоє́ ми ублажа́єм тя си́це:","Ра́дуйся, я́ко і ни́ні Госпо́дь сохрани́ тя от рук ма́тері-уби́йці.","Ра́дуйся і ти, я́ко Бори́с і Гліб, непови́нно пролія́вий кров свою́ святу́ю от сро́дников свої́х.","Ра́дуйся, я́ко приско́рбним житіє́м свої́м ти Христу́, странствующему на землі́, уподо́бивийся.","Ра́дуйся, я́ко с Ним і во оби́теліх Отця́ Небе́снаго всели́вийся.","Ра́дуйся, я́ко во вся дні живота́ твоєго́ гоне́нія, зауше́нія і вся́коє злострада́ніє претерпі́вий.","Ра́дуйся, я́ко нікому́же злом за зло возда́вий і, по глаго́лу Христо́ву, за враго́в свої́х моли́вийся.","Ра́дуйся, преподо́бне о́тче наш Фео́филе, по́двигом юро́дства твоєго́ на путь спасе́нія нас наставля́ющий."]},{"h":"Кондак 7","ps":["Хотя́й человіколю́бець Госпо́дь яви́ти тя стра́ждущим лю́дем но́ваго моли́твенника і обличи́теля їх поро́ков, приведе́ тя в Кі́єво-Братський монасти́р, даби́ в моли́твенних по́двизіх угото́вати ду́шу твою́ для прия́тія Боже́ственний благода́ті. Ти же, а́ки єле́нь на пото́ки водни́я, устреми́ся ізуча́ти Боже́ственноє Писа́ніє в духо́внім учи́лище, там би́вшем. Ісполня́я послуша́ніє звонаря, ти зіло́ ра́но, взийдя на колокольню, созерца́я с висоти́ творе́ніє Бо́жиє, предавался та́мо богоми́слію і та́йной моли́тві, в ликованії духо́внім воспіва́я Созда́телю всея́ ви́димая і неви́димая тва́рі: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́воє житіє́ твоє́ во оби́телі святі́й бисть в сла́дость се́рдцю твоєму́. А́ки после бу́ри жите́йськаго мо́ря ти прите́кл єси́ к ти́хому приста́нищу, с черноризцями проводя́ Богоуго́дноє житіє́ твоє́ в послуша́нії, бді́нії, колінопреклоне́нії і чте́нії Псалти́ри. Чиноначаліє же оби́телі, ви́дя твоє́ усе́рдноє рве́ніє к духо́вним по́двигом, удосто́ї тя і́ночеськаго пострига і са́на ієродия́кона. Предстоя́ у Свята́го Престо́ла, ти с в'ящим рве́нієм устреми́ся подо́битися равноангельському житію́. Ми же, ублажа́я твої́ по́двиги і любо́в к Сладча́йшему Ісу́су, глаго́лем си́це:","Ра́дуйся, я́ко Госпо́дь умилосе́рдися над тобо́ю і призва́ тя во оби́тель святу́ю.","Ра́дуйся, я́ко ти ста́рцем-подви́жникам в послуша́нії і моли́твенних по́двизіх подража́вий.","Ра́дуйся, ду́шу твою́ соблюди́й страстьми́ непорабоще́нну.","Ра́дуйся, прельще́нія ю́наго во́зраста побіди́вий.","Ра́дуйся, о́браз терпі́нія і послуша́нія нам показа́вий.","Ра́дуйся, Христу́ рабо́тати і і́скренні єму́ служи́ти всіх люде́й науча́вий.","Ра́дуйся, преподо́бне о́тче наш Фео́филе, по́двигом юро́дства твоєго́ на путь спасе́нія нас наставля́ющий."]},{"h":"Кондак 8","ps":["Не хотя́й сме́рти грі́шников, Госпо́дь і ма́тер твою́ призва́ к покая́нію. Пораженная неісці́льною болі́знію, уві́де на себі́ гнів Бо́жий за жесто́коє на тя гоне́ніє, раска́яся в своє́м злодеянії і с во́плем ве́ліїм і риданіями взива́ла к Бо́гу о проще́нії. Ти же, незло́бив сий, прости́в єй вся би́вшая і погре́бше ті́ло єя́, возврати́ся в оби́тель свою́, в ра́дості духо́вній поя́ Промисли́телю Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь доброді́телей і незло́бія іспо́лненний, воі́стину бил єси́ во пло́ті А́нгел, досточу́дне Фео́филе, явля́я для бра́тії о́браз кро́тости і послуша́нія, смире́нія і цілому́дрія. Служа́ у Престо́ла Бо́жия в свяще́нном са́ні, ти, а́ки преподобниє Се́ргій Радонежський і Серафи́м Саро́вський, сподо́бивийся ви́діти А́нгелов небе́сних, сослужа́щих тебі́ в Боже́ственной литургі́ї і благода́ть Бо́жию, сходя́щую на Святи́є Да́ри. Благоговея пред твоє́ю свя́тостію, со стра́хом і умиле́нієм вопіє́м ті:","Ра́дуйся, челові́че небе́сний і а́нгеле земни́й.","Ра́дуйся, сосу́де, Бо́жієй благода́ті іспо́лненний.","Ра́дуйся, в се́рдці твоє́м о́браз Христа́ непреста́нно носи́вий.","Ра́дуйся, Єго́ же ра́ди плоть свою́ расп'явий со страстьми́ і похотьми́.","Ра́дуйся, усе́рдний моли́твенниче о всіх, притека́ющих к тебі́.","Ра́дуйся, ско́рий помо́щниче всім стра́ждущим і заблудшим.","Ра́дуйся, преподо́бне о́тче наш Фео́филе, по́двигом юро́дства твоєго́ на путь спасе́нія нас наставля́ющий."]},{"h":"Кондак 9","ps":["Все житіє́ твоє́ бисть іспо́лненно скорбе́й і печа́лей, досажденій і укоре́ній. Ти же во і́м'я любві́ к Бо́гу прия́л єси́ на себ'я́ по́двиг юро́дства Христа́ ра́ди. І бисть мно́гими гони́мий, оскорбля́ємий і презираємий, ти, смире́нний се́рдцем і кро́ткий ду́хом, а́ки Христо́с на Кресті́, моли́вийся за враго́в свої́х і хули́телей, глаго́ля: «Го́споди, прости́ їм, не ві́дять бо, что творя́ть», і во весе́лії се́рдця всегда́ піл Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Ви́дя Госпо́дь по́двиги твоя́, любо́в і милосе́рдіє твоє́ к стра́ждущим лю́дем, даде́ тебі́ дар прозорливости і врачева́нія. І ти, облича́я їх та́йния і я́вния гріхопаде́нія, наставля́л єси́ на путь спасе́нія, врачу́я і душе́вния, і тіле́сния їх я́зви. Сам же, усугубляя по́двиги своя́, денно і но́щно в де́бріх лісни́х, а́ки преподо́бний Серафи́м, моли́лся колінопреклоне́нно на пні дре́ва. За такови́я по́двиги твоя́ прийми́ от нас похвали́ сія́:","Ра́дуйся, я́ко свої́ми по́двигами ти преподо́бним отце́м Кі́єво-Пече́рським уподо́бивийся.","Ра́дуйся, чистоти́ душе́вния і тіле́сния усе́рдний храни́телю.","Ра́дуйся, свої́ми по́двигами іскуше́нія от пло́ті, ми́ра і дия́вола побіди́вий.","Ра́дуйся, я́ко за твою́ ре́вность і любо́в ко Христу́, дар прозорливости і чудотворе́нія от Него́ прия́вий.","Ра́дуйся, я́ко душе́вния і тіле́сния неду́ги ти єди́ним сло́вом врачевавий.","Ра́дуйся, оби́димим і су́щим в напа́стіх ско́рий помо́щниче.","Ра́дуйся, преподо́бне о́тче наш Фео́филе, по́двигом юро́дства твоєго́ на путь спасе́нія нас наставля́ющий."]},{"h":"Кондак 10","ps":["Помо́щник ско́рий і уті́шитель бил єси́, о́тче Фео́филе, не то́кмо к тебі́ приходящим, но і сам, с чте́нієм Псалти́ри, ї́здяй на тельці по гра́ду Ки́єву, утіша́л єси́ скорб'я́щих і оби́димих; одіва́я і пита́я ни́щих, гро́зно облича́я вино́вних і, предсказу́я гряду́щеє я́ко настоя́щеє, мно́гих обрати́л єси́ на путь покая́нія. Ми же, див'я́щеся твоєму́ таково́му милосе́рдію і человіколю́бію к лю́дем, поє́м Всемилостивому́ Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Царе́м тва́рей бисть Ада́м в раю́ до гріхопаде́нія, всі бо зві́ріє єму́ повинова́хуся. І тебі́, безгрі́шному і освяще́нному Ду́хом Святи́м, та́кожде повинова́хуся і ско́ти, і ри́би, і пти́ці. По твоєму́ рече́нію безслове́сния живо́тния послушно ісполняли во́лю твою́. На удивле́ніє всім твой теле́ць, управля́ємий си́лою Бо́жієй, привозих тя, іді́же душа́ твоя́ свята́я возжела́ла помоли́тися іли́ сотвори́ти по́мощ нуждающимся. Див'я́щеся таково́му о тебі́ Бо́жию промишле́нію, со умиле́нієм глаго́лем сицева́я:","Ра́дуйся, обличи́телю та́йних і я́вних грехолюбцев.","Ра́дуйся, заблудших наста́вниче і скорб'я́щих уті́шителю.","Ра́дуйся, прося́щих твоєя́ по́мощі ско́рий ісполни́телю.","Ра́дуйся, повинова́тися во́лі Бо́жієй всіх науча́вий.","Ра́дуйся, я́ко і ско́ти злонравнії по словесі́ твоєму́ послушни бисть, а́ки о́вці.","Ра́дуйся, я́ко і ладья чрез Днепр по сло́ву твоєму́ сама́ по воді́ дви́жима бисть.","Ра́дуйся, преподо́бне о́тче наш Фео́филе, по́двигом юро́дства твоєго́ на путь спасе́нія нас наставля́ющий."]},{"h":"Кондак 11","ps":["Пі́ніє всеумиле́нноє трієди́ному Бо́гу приноси́л єси́ во вся дні страда́льчеськаго житія́ твоєго́, достохва́льне о́тче Фео́филе. Днем і но́щію, в келії і в де́бріх лісни́х творя́ у́мную моли́тву, не оставля́л єси́ без утіше́нія і ісціле́нія всіх к тебі́ приходя́щих, назида́я їх сло́вом Бо́жиїм і свої́м юро́дством. Ни́ні же предстоя́ у Престо́ла Царя́ Сла́ви, моли́ся о нас, чту́щих святу́ю па́м'ять твою́, да і ми с тобо́ю ку́пно во ві́ки поє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Прови́дя бу́дущеє я́ко настоя́щеє, ти мно́гим лю́дем, предсказу́я внеза́пную смерть іли́ болі́зні, приводи́л їх от гріхо́вния жи́зні к покая́нію. Іщущим мона́шеськаго житія́ ти іногда́ благословля́л супру́жество, а жа́ждущим мирська́го житія́ - монашество, даби́ житіє́ їх би́ло богоуго́дним і спаси́тельним для душі́. І царю́ Никола́ю, лежа́ в муравейникі окровавленним, предре́кл єси́ печа́льний ісхо́д на по́лі бра́ні в Криму і єго́ смерть от печа́лі. За таково́є твоє́ о лю́діх попече́ніє глаго́лем тебі́ благода́рними усти́ сицева́я:","Ра́дуйся, тайнозрителю суде́б челові́чеських.","Ра́дуйся, я́ко ти предуказал на Глубочиці мі́сто для устроє́нія монастиря́ Покро́вськаго.","Ра́дуйся, я́ко ти указа́вий мі́сто в лесу́, іді́же і́мать би́ти устро́єна пусти́нь Преображенськая.","Ра́дуйся, я́ко і крест та́мо водрузи́вий, а́ки апо́стол Андре́й на гора́х Ки́євських.","Ра́дуйся, я́ко і для монастиря́ Іоновськаго на гора́х Зверинецьких свої́м трикра́тним благослове́нієм мі́сто освяти́вий.","Ра́дуйся, я́ко ти митрополи́ту Филарету вели́коє о́гненноє запале́ніє в Кі́єво-Пече́рстій Ла́вре предре́кл єси́.","Ра́дуйся, преподо́бне о́тче наш Фео́филе, по́двигом юро́дства твоєго́ на путь спасе́нія нас наставля́ющий."]},{"h":"Кондак 12","ps":["Благода́ть от Бо́га даде́ся тебі́, уго́дниче Бо́жий, твори́ти чудеса́ для прославле́нія Всемогу́щаго Творця́ не́ба і землі́. Подо́бно Христу́, чуде́сно напита́вшему в пусти́ні лю́ди а́лчущия, ти утружденних путников, гряду́щих на поклоне́ніє уго́дником Пече́рським, напита́л єси́ чудоді́йственною кашею, сваренною в лесу́ із камушков і трави́, зажегши древеса́ огне́м, низведшим с не́ба моли́твою твоє́ю. І отрокови́цю умирающую моли́твою своє́ю, во утіше́ніє плачущей вдови́ці, оживи́л єси́. Ми же со стра́хом і тре́петом, благода́рними усти́ вопіє́м ди́вному во святи́х Свої́х Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Блаже́нния кончи́ни своєя́ день і час предуказавий і ті́ло своє́ для погребе́нія сам предуготовивий, о преди́вний чудотво́рче Фео́филе. Келію же свою́ свіща́ми і ладаном для срі́тенія А́нгела облагоуха́л єси́ і послу́шника своєго́ посла́л єси́ ударя́ти в звон колокольний, даби́ ізвісти́ти бра́тію оби́телі, я́ко Фео́фил к Бо́гу преселя́ється. І рида́ху лю́діє всі, єгда́ погребаше пречестно́є ті́ло твоє́, я́ко лиша́ються уті́шителя своєго́ і наста́вника. По ста сорока лі́тіх же, яви́ нам Госпо́дь во утіше́ніє мо́щі твоя́. Чту́щії же па́м'ять твою́, списаху для ра́ки твоєя́ лик твой. І ми, со умиле́нієм взира́я на о́браз твой, с ра́достію зове́м ті:","Ра́дуйся, вели́кий чудотво́рче, Бо́гом на утіше́ніє нам дарова́нний.","Ра́дуйся, скорб'я́щих уті́шителю, вдов і сиро́т защи́тниче, боля́щих і стра́ждущих ціли́телю.","Ра́дуйся, я́ко і по преставле́нії твоє́м чудеса́ твори́ти не преставий.","Ра́дуйся, я́ко молящимся у гро́ба твоєго́ ско́рую по́мощ подава́вий.","Ра́дуйся, я́ко отнині і́м'я твоє́ со святи́ми прославля́ється.","Ра́дуйся, гра́да Ки́єва украше́ніє і Китаєвой пусти́ні сла́во.","Ра́дуйся, преподо́бне о́тче наш Фео́филе, по́двигом юро́дства твоєго́ на путь спасе́нія нас наставля́ющий."]},{"h":"Кондак 13","ps":["О, пресла́вний уго́дниче Христо́в і преди́вний чудотво́рче, о́тче наш Фео́филе! Прийми́ сіє́ ма́лоє моле́ніє на́ше, в похвалу́ тебі́ приноси́моє от нас, недосто́йних і грі́шних, оба́че с любо́вію чту́щих тя. Умоли́ Го́спода Бо́га ізба́витися нам от вся́ких бід, скорбе́й і напа́стей, найпа́че же от гріхопаде́ній і внеза́пния сме́рти і ві́чних мук. Не попусти́ нам без покая́нія умре́ти. Бу́ди нам путеводи́тель в Ца́рствіє Небе́сноє, да та́мо, с тобо́ю вку́пі, во ві́ки поє́м Бо́гу: Аллилу́я, Аллилу́я, Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгели небе́снії і челові́ци земні́ї богоізбра́нному житію́ твоєму́ удивля́шеся, о́тче Фео́филе, ка́ко ті младе́нцю су́щу от млека́ ма́тері своєя́ лице́ своє́ отвраща́л єси́, принима́я пи́щу то́кмо по́стную. Сим зна́менієм Госпо́дь показа́ лю́дем, я́ко ти єси́ ізбра́нник Бо́жий, не от ми́ра сего́ бисть. Див'я́щеся таково́му по́стничеському воздержа́нію твоєму́, со умиле́нієм зове́м ті си́це:","Ра́дуйся, ізбра́нниче Бо́жий от чре́ва ма́тері;","Ра́дуйся, пречестна́я о́трасль ієре́я Бо́жия.","Ра́дуйся, по́стничеським по́двигом твої́м Крести́телю Госпо́дню уподо́бивийся.","Ра́дуйся, воздержа́нієм такови́м роди́телей і сро́дников свої́х удиви́вий.","Ра́дуйся, ізмла́да Бо́га возлюби́вий.","Ра́дуйся, за́повіді Єго́ ві́рно сохрани́вий.","Ра́дуйся, преподо́бне о́тче наш Фео́филе, по́двигом юро́дства твоєго́ на путь спасе́нія нас наставля́ющий."]},{"h":"Кондак 1","ps":["Ізбра́нний Бо́гом от чре́ва ма́тері своєя́ на по́двиг юро́дства при́зван бил єси́, си́лою Бо́жієй от водна́го потопле́нія мно́гажди храни́мий, по́двигом поста́ і моли́тви врага́ ро́да челові́чеськаго посрами́вий. Сего́ ра́ди, соверша́я па́м'ять твою́, мо́лим тя, преди́вний о́тче Фео́филе, ізба́ви нас от враг ви́димих і неви́димих, с любо́вію зову́щих ті:","Ра́дуйся, преподо́бне о́тче наш Фео́филе, по́двигом юро́дства твоєго́ на путь спасе́нія нас наставля́ющий."]},{"h":"Молитва","ps":["О, преди́вний уго́дниче Христо́в, крі́пкий моли́твенниче і засту́пниче, о́тче наш Фео́филе! Ти от чре́ва ма́тері ізбра́нний Бо́гом на служе́ніє єму́ і ди́вно їм храни́мий от вся́каго зла. За твоя́ по́двиги юро́дства Госпо́дь дарова́ тебі́ дар проро́чества і чудотворе́ній. По за́повіді пастиренача́льника Христа́ ти ду́шу свою́ полага́вий за о́вці ста́да Христо́ва. Ти грі́шников та́йних і я́вних гро́зно облича́вий і свої́ми му́дрими словеси́ к покая́нію і ісправле́нію їх приводи́вий. Ти приходя́щих к тебі́ больни́х і ско́рбних не отверга́л єси́. Ти бил всім я́ко оте́ць чадолюби́вий і па́стир до́брий. І ни́ні усли́ши нас, с ві́рою призива́ющих тя і усе́рдно припа́дающих к ра́ці моще́й твої́х, о́тче наш Фео́филе. Іспроси́ у Всеми́лостиваго Бо́га мир Це́ркві на́шей правосла́вній во оте́чествії твоє́м. Вразуми́ і обрати́ єретико́в і раско́льников в ло́но Ма́тері Це́ркві. Па́стирям на́шим ре́вность о спасе́нії люде́й, лю́дем же послуша́ніє Святі́й Це́ркві і ре́вность защища́ти ві́ру правосла́вную іспроси́. Умоли́ Небе́снаго Отця́ всім нам пода́ти коєму́ждо по проше́нію єго́: ю́ним в правосла́вній ві́рі возраста́ніє, ста́рим і немощни́м подкріпле́ніє і утіше́ніє, боля́щим ісціле́ніє, сирота́м і безпомо́щним заступле́ніє і неча́янную ра́дость, заблу́ждшим і согреша́ющим ісправле́ніє. І всім нам іспроси́ тіле́сноє здра́віє і душе́вноє спасе́ніє. Согрі́й огне́м Боже́ственной любві́ охладевшия сердця́ на́ша. Помози́ нам іспра́вити жизнь на́шу гріхо́вную, даби́ безбі́дно прейти́ мита́рства де́монов лю́тих і водвори́тися во оби́теліх Отця́ Небе́снаго, даби́ вку́пі с тобо́ю і со всі́ми святи́ми воспіва́ти всесвято́є і великолі́поє і́м'я Пресвяти́я Тро́йці: Отця́ і Си́на і Свята́го Ду́ха во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["От ю́ности Христа́ возлюби́л єси́, блаже́нне Фео́филе, / і Тому́ єди́ному рабо́тати пла́менні возжелі́л, / непреста́нною моли́твою і юро́дством в пусти́ні Кита́євой подвиза́лся єси́, / уго́дником пече́рським подража́я. / Сего́ ра́ди вопіє́м ті: / спаса́й нас моли́твами твої́ми, // преподо́бне о́тче наш."]},{"h":"Кондак, глас 8","ps":["От ми́ра су́єтнаго ізше́л єси́ / і в де́бріх Кита́єва всели́лся єси́, / преподо́бне о́тче наш Фео́филе. / Непреста́нним псалмопі́нієм і юро́дством свої́м / мно́гих на путь спасе́нія наста́вил єси́. / Сего́ ра́ди вопіє́м ті: // моли́ Христа́ Бо́га, да спасе́ть ду́ші на́ша."]},{"h":"Величання","ps":["Ублажа́єм тя, / преподо́бне о́тче Фео́филе, / і чтим святу́ю па́м'ять твою́, / наста́вниче мона́хов // і собесі́дниче А́нгелов."]}],"notes":[]},{"u":"Акафіст благовірному князю Ігорю Чернігівському і Київському","e":"Akathist to the Right-Believing Prince Igor of Chernihiv and Kyiv","secs":[{"h":"Кондак 1","ps":["Ізбра́нний страстоте́рпче Христо́в, благові́рний кня́же І́горе, возсія́вий лю́дем твої́м, я́ко звізда́ пресві́тлая: ти бо сла́ву земна́го княже́нія оста́вил єси́ і во і́ночестві Го́сподеві рабо́тати вожделі́л єси́, страда́льчеськи земно́є житіє́ сконча́в, і ни́ні, ра́дуяся, предстої́ши престо́лу Святи́я Тро́йці. Моли́твами твої́ми от вся́ких зол і напа́стей охраня́й нас, да благода́рственно со умиле́нієм зове́м ті:","Ра́дуйся, святи́й благові́рний кня́же І́горе, во смире́нії за і́стину терп'я́щим ско́рий помо́щниче."]},{"h":"Ікос 1","ps":["А́нгельськи пожи́вши на землі́, от ю́ности возлюби́л єси́ Боже́ственноє уче́ніє і сему́ послі́довав до́брим житіє́м, немо́лчно прославля́л єси́ і́м'я Госпо́днє чте́нієм книг свяще́нних і пі́нієм церко́вним. Сего́ ра́ди тебе́, на небесі́ і на землі́ просла́вленному, вопіє́м си́це:","Ра́дуйся, от рожде́нія твоєго́ Бо́гом ізбра́нний.","Ра́дуйся, сі́м'я сло́ва Бо́жия от ю́ности восприя́вий.","Ра́дуйся, вели́кий уго́дниче Бо́жий, благочести́вую жизнь на землі́ возлюби́вий.","Ра́дуйся, путе́м тру́дним і ті́сним житіє́ земно́є проше́дий.","Ра́дуйся, пра́вди ра́ди ду́шу твою́ положи́вий.","Ра́дуйся, от Царя́ Небе́снаго, віне́ць му́ченичеський приє́мий.","Ра́дуйся, святи́й благові́рний кня́же І́горе, во смире́нії за і́стину терп'я́щим ско́рий помо́щниче."]},{"h":"Кондак 2","ps":["Ви́дя Госпо́дь чистоту́ се́рдця твоєго́, блаже́нне кня́же І́горе, ізбра́ тя зрі́ти сла́ву небе́сную, ти бо па́че всего́ возлюби́л єси́ чистоту́ душе́вную і тіле́сную, і ра́ди страда́ній вре́менних, упова́я ізбіжа́ти муче́ній ві́чних, вели́кий уго́дник Бо́жий бил єси́, і лице́м к лицю́ зрі́ти Го́спода удосто́їлся єси́. Ті́мже притека́юще к ти́хому приста́нищу моли́тв твої́х, вопіє́м Христу́ Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум озаре́нний благода́тію Бо́жиєю із мла́да імі́л єси́, кня́же І́горе, от ю́ности бо храни́л єси́ в се́рдці твоє́м зако́н Христо́в, вели́ким уго́дником Бо́жиїм, прошедшим тернистим путе́м во Ца́рствіє Небе́сноє, подража́я. Ті́мже і ми, упова́я на твоє́ предста́тельство, мо́лимся: бу́ди нам ско́рий помо́щник і покрови́тель в земно́м житії́ на́шем, да благода́рно вопіє́м ті:","Ра́дуйся, ізбра́нний і ві́рний ра́бе Христо́в.","Ра́дуйся, от ю́ности чистоту́ житія́ возлюби́вий.","Ра́дуйся, із мла́да єди́ному Христу́ угождавий.","Ра́дуйся, Ісу́са ра́ди вся напа́сти безро́потно претерпі́вий.","Ра́дуйся, Тому́ єди́ному все́ю душе́ю приліпи́вийся.","Ра́дуйся, всего́ себе́ на страда́нія пра́вди ра́ди преда́вий.","Ра́дуйся, святи́й благові́рний кня́же І́горе, во смире́нії за і́стину терп'я́щим ско́рий помо́щниче."]},{"h":"Кондак 3","ps":["Си́лою Ви́шняго, дарова́нною тебі́, і долготерпі́нієм твої́м укріпле́н бил єси́, блаже́нне, єгда́ враг ро́да челові́чеськаго наведе́ на тя лю́ди зли, во є́же лиши́ти тя сла́ви кня́жеськия. Ті́мже, див'я́щеся бога́тству терпі́нія твоєго́, воспіва́єм укріпи́вшему тя Го́споду піснь: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я жела́ніє в душі́ своє́й вся кра́сная і сла́дкая ми́ра сего́ оста́вити і Христу́ послі́довати, єще́ млад сий, ізбра́л єси́ себе́ путь служе́нія Го́сподеві. Ми же, подража́я житію́ твоєму́ і почита́юще честна́я страда́нія твоя́, пра́вди ра́ди претерпі́нная, велича́єм тя си́це:","Ра́дуйся, в душі́ своє́й імі́вий жела́ніє мир оста́вити і Го́сподеві послужи́ти.","Ра́дуйся, вся кра́сная і сла́дкая ми́ра сего́ презрі́вий.","Ра́дуйся, соверше́нную любо́в ко Го́споду стяжа́вий.","Ра́дуйся, за кро́тость душі́ твоєя́ наслі́діє жи́зні ві́чния получи́вий.","Ра́дуйся, ум твой, се́рдце і во́лю в Бо́зі утверди́вий.","Ра́дуйся, ди́вную кро́тость ду́ха в ско́рбі показа́вий.","Ра́дуйся, святи́й благові́рний кня́же І́горе, во смире́нії за і́стину терп'я́щим ско́рий помо́щниче."]},{"h":"Кондак 4","ps":["Бу́ри жите́йських бід і напа́стей не возмого́ша поколеба́ти крі́пости душі́ твоєя́, благові́рний кня́же І́горе, основана́ бо бі на тве́рдем ві́ри Христо́ви ка́мені. Ми же, див'я́щеся вели́кому терпі́нію твоєму́, со умиле́нієм взива́єм Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́ша і ви́дя, кня́же блаже́нне, ра́спри і раздо́ри, враго́м ро́да челові́чеськаго воздвиза́ємия, єгда́ вступи́ на престо́л Ки́євський, а́біє восхоті́л єси́ вразуми́ти лю́ди своя́ і привести́ їх к ми́ру і благоразу́мію. Сего́ ра́ди с любо́вію взива́єм ті:","Ра́дуйся, я́ко тобо́ю вся́кая вражда́ і зло́ба побіжда́ються.","Ра́дуйся, чистоти́ ві́ри і незло́бія ди́вноє воплоще́ніє.","Ра́дуйся, о́бразе кро́тости і терпі́нія.","Ра́дуйся, зерца́ло соверше́ннаго незло́бія.","Ра́дуйся, мно́гими скорбми́ в ра́дость Го́спода твоєго́ вше́дий.","Ра́дуйся, помога́яй і нам терпі́ти ско́рби і поноше́нія.","Ра́дуйся, святи́й благові́рний кня́же І́горе, во смире́нії за і́стину терп'я́щим ско́рий помо́щниче."]},{"h":"Кондак 5","ps":["Боготе́чную звізду́ зрим тя, уго́дниче Бо́жий, тя бо, восприї́мшаго вели́кия страда́нія, просла́ви Госпо́дь, я́ко ві́рнаго раба́ Своєго́, неви́нно убіє́ннаго зли́ми челові́ки по науще́нію дия́вольському. Ми же, взира́юще с любо́вію на честни́й о́браз твой, приклоня́єм колі́на, со умиле́нієм поя́: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше вели́кий князь Ки́євський Все́волод, я́ко преклони́лся єсть к ве́черу день житія́ єго́, призва́ тя, І́горе блаже́нне, і завіща́ ті престо́л княжеський. Ти же во́лі бра́та твоєго́, я́ко во́лі Бо́жієй повину́яся, все упова́ніє на Го́спода возложи́л єси́. Ми же, похваля́я таково́є смире́ніє твоє́, воспіва́єм ті:","Ра́дуйся, я́ко до конця́ крест житія́ твоєго́ безро́потно поне́сл єси́.","Ра́дуйся, благоче́стієм Бо́гові і лю́дем послужи́вий.","Ра́дуйся, велі́нію бра́та своєго́ покори́вийся.","Ра́дуйся, в народоправленії ве́лію доброді́тель показа́вий.","Ра́дуйся, всім братолюбцем при́сноє ободре́ніє.","Ра́дуйся, от люде́й свої́х ве́лію любо́в стяжа́вий.","Ра́дуйся, святи́й благові́рний кня́же І́горе, во смире́нії за і́стину терп'я́щим ско́рий помо́щниче."]},{"h":"Кондак 6","ps":["Пропові́дником доброді́телей христия́нських бил єси́, кня́же І́горе, поуча́я люби́ти бра́тію і наро́д свой. Ми же ублажа́єм тя, я́ко до́браго і і́стиннаго послі́дователя Христо́ва, живо́т свой за лю́ди твоя́ положи́вшаго, воспіва́я Го́сподеві піснь: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́л єси́ богоуго́дним житіє́м твої́м, благові́рний кня́же І́горе, все упова́ніє своє́ на Го́спода, вся во бла́го устрояющаго, возлага́я. Ми же, восхваля́я по́двиги твоя́, глаго́лем си́це:","Ра́дуйся, я́ко в житії́ твоє́м доброді́тельми просія́вий.","Ра́дуйся, чистото́ю се́рдця твоєго́ Го́спода созерца́вий.","Ра́дуйся, в несенії трудо́во вели́каго княже́нія по́мощ от Го́спода получи́вий.","Ра́дуйся, я́ко вмі́сто кня́жеських по́честей - муче́нія і ско́рби му́жественно претерпі́вий.","Ра́дуйся, і́го Христо́во, благо́є і ле́гкоє, на ра́мена своя́ восприя́вий.","Ра́дуйся, терпі́нію Христо́ву ві́рно подража́вий.","Ра́дуйся, святи́й благові́рний кня́же І́горе, во смире́нії за і́стину терп'я́щим ско́рий помо́щниче."]},{"h":"Кондак 7","ps":["Хотя́щу ті, блаже́нне, во́лі Бо́жієй покори́тися, не воспротивился єси́ во́їном кня́зя Ізясла́ва, єгда́ ті́ї тя, є́ле жива́ су́ща, в хладном порубе заключи́ша, іді́же ти, подо́бно Данії́лу проро́ку, заточенному в ро́ві львином, непреста́нно взива́л єси́ Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́ваго ви́дим тя ізбра́нника Бо́жия, благові́рний кня́же І́горе, єгда́ преміни́л єси́ княже́нія сла́ву во і́ночества о́браз смире́нний. Ти бо, вся блага́я презрі́в, жела́нієм восхоті́л єси́ єди́ному Бо́гу порабо́тати. Ті́мже, таково́му твоєму́ смире́нію і кро́тости див'я́щеся, вопіє́м ті:","Ра́дуйся, страда́нія лю́тая неви́нно претерпі́вий.","Ра́дуйся, о́браз любве́ і незло́бія нам показа́вий.","Ра́дуйся, вся блага́я ми́ра сего́ ні во что же вміни́вий.","Ра́дуйся, зло́бу і кова́рство дия́вола смире́нієм побіди́вий.","Ра́дуйся, послуша́нію і́ночеському всеці́ло преда́вийся.","Ра́дуйся, усе́рдним моли́твенником за лю́ди твоя́ яви́вийся.","Ра́дуйся, святи́й благові́рний кня́же І́горе, во смире́нії за і́стину терп'я́щим ско́рий помо́щниче."]},{"h":"Кондак 8","ps":["Стра́нник і пришле́ць, по апо́столу, яви́лся єси́ на землі́, боголюбе́зне кня́же, до́льняя бо вся презрі́в, го́рняя взиска́л єси́, все помишле́ніє твоє́ ко Го́споду імі́яй. Ті́мже помози́ і нам, моли́твами твої́ми, доброді́тельноє житіє́ возлюби́ти, да ку́пно с тобо́ю вопіє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Все́ю душе́ю от ю́ности Бо́гу послужи́вий, блаже́нне кня́же І́горе, сего́ ра́ди Госпо́дь просла́ви тя, Своєго́ уго́дника, кро́тости ра́ди і смире́нія твоєго́. Ми же, сим доброді́телем послі́довати тща́щіїся, вопіє́м ті ра́достно:","Ра́дуйся, от ю́ности Го́спода все́ю душе́ю возлюби́вий.","Ра́дуйся, ді́ли благи́ми Христу́ благоугоди́вий.","Ра́дуйся, всім житіє́м твої́м Бо́га просла́вивий.","Ра́дуйся, ті́сний путь спасе́нія от ю́ности ізбра́вий.","Ра́дуйся, благода́ть Бо́жию в се́рдці своє́м стяжа́вий.","Ра́дуйся, житіє́ своє́ іночеством украси́вий.","Ра́дуйся, святи́й благові́рний кня́же І́горе, во смире́нії за і́стину терп'я́щим ско́рий помо́щниче."]},{"h":"Кондак 9","ps":["Всего́ себе́ покори́л єси́ во́лі Госпо́дні, я́ко раб благи́й і ві́рний, єгда́ постриже́ніє і́ночеськоє восприї́м, во оби́тель свята́го Фео́дора всели́лся єси́, іді́же всеці́ло посту́ і моли́тві преда́лся єси́. Сего́ ра́ди сподо́бился вни́ти в ра́дость Го́спода своєго́, Єму́же предстої́ши ни́ні со А́нгели, поя́: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́ї многовіща́нния не возмо́гуть по достоя́нію восхвали́ти страда́нія твоя́, страстоте́рпче Христо́в, кня́же І́горе, ніже́ уразумі́ти глубини́ упова́нія твоєго́, приї́мши бо вість о убіє́нії твоє́м, потща́лся єси́ в це́рков Госпо́дню, со слеза́ми пред о́бразом Цари́ці Небе́сния моля́ся. Уби́йці же твої́, я́ко зві́ри ди́вії, є́мше тя моля́щагося, бив, повлекоша тя із хра́ма. Ти же, благода́тію Бо́жиєю укріпля́єм, страда́нія кро́тко претерпі́л єси́, за убива́ющих тя Го́спода умоля́я. Сего́ ра́ди велича́єм тя си́це:","Ра́дуйся, все упова́ніє на Го́спода і Єго́ Пречи́стую Ма́тер возложи́вий.","Ра́дуйся, на муче́ніє безро́потно преда́вийся.","Ра́дуйся, благода́тію Бо́жиєю укріпля́єм, страда́нія му́жественно претерпі́вий.","Ра́дуйся, я́ко сего́ ра́ди вінце́м му́ченичеським украше́нний.","Ра́дуйся, за убива́ющих тя кро́тко моли́вийся.","Ра́дуйся, ду́шу свою́ в ру́ці Бо́жії ра́достно преда́вий.","Ра́дуйся, святи́й благові́рний кня́же І́горе, во смире́нії за і́стину терп'я́щим ско́рий помо́щниче."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ ду́шу свою́, вся земна́я і вре́менная во уме́ти вміни́л єси́, неукло́нно стопа́м Спаси́телевим послі́дствовав. І ни́ні с ли́ки а́нгельськими веселя́ся, немо́лчно вопіє́ши Просла́вльшему тя Го́сподеві: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіно́ю терпі́нія огради́вся, ві́рний раб Царя́ Небе́снаго бил єси́: вра́жиїх бо устрашеній не убоя́вся, всего́ себе́ в ру́ці Бо́жії пре́дал єси́ і страда́нія му́жественні претерпі́л єси́. Ми же, чту́ще святу́ю па́м'ять твою́, ублажа́єм тя, вопію́ще:","Ра́дуйся, вели́кий кня́же І́горе, престо́лу Небе́снаго Влади́ки предстоя́й.","Ра́дуйся, віне́ць твой княжеський кро́вними ка́плями, я́ко драги́ми камнями украси́л єси́.","Ра́дуйся, о́браз ві́рнаго служе́нія Бо́гу терпі́нієм свої́м показа́вий.","Ра́дуйся, житіє́ своє́ ті́сною стезе́ю муче́ній і страда́ній проше́дий.","Ра́дуйся, я́ко пред вели́ким му́жеством твої́м, ві́рнії преклоня́ються.","Ра́дуйся, я́ко і ни́ні не престає́ши благодеяти призива́ющим тя.","Ра́дуйся, святи́й благові́рний кня́же І́горе, во смире́нії за і́стину терп'я́щим ско́рий помо́щниче."]},{"h":"Кондак 11","ps":["Пі́ніє хвале́бноє прино́сим ди́вному во святи́х Свої́х Бо́гу на́шему, дарова́вшаго Це́ркві Своє́й і страні́ на́шей ди́внаго чудотво́рця і усе́рднаго моли́твенника - благові́рнаго кня́зя І́горя, і́же і понине не престає́ть моли́тися за ни і науча́я пі́ти всіх: Аллилу́я."]},{"h":"Ікос 11","ps":["Світ сла́ви небе́сния осія́ свято́є і многострада́льноє ті́ло твоє́, страстоте́рпче Христо́в, єгда́ о́ноє положе́но бисть в це́ркві свята́го Михаї́ла. Лю́діє же, о́крест гро́ба твоєго́ стоя́щії, і возжегаємия неви́димою руко́ю свіщи́ і лампа́ди зря́ще, прийдо́ша в тре́петь і у́жас, познава́я, я́ко та́ко просла́ви Бог уго́дника Своєго́; тебі́ же, богому́дре кня́же, воспі́ша та́ко:","Ра́дуйся, усе́рдний наш пред Бо́гом моли́твенниче і предста́телю.","Ра́дуйся, я́ко Госпо́дь просла́ви тя зна́меньми і чудеси́.","Ра́дуйся, сія́нієм небе́снаго сві́та озаре́нний.","Ра́дуйся, непоро́чную ду́шу твою́ в ру́ці Бо́жії преда́вий.","Ра́дуйся, нетлі́нноє ті́ло твоє́ в по́мощ нам оста́вивий.","Ра́дуйся, я́ко за смиренному́дріє твоє́ вінце́м сла́ви от Бо́га увінча́нний.","Ра́дуйся, святи́й благові́рний кня́же І́горе, во смире́нії за і́стину терп'я́щим ско́рий помо́щниче."]},{"h":"Кондак 12","ps":["Благода́ть єдине́нія і братолю́бія іспроси́ нам у Всеще́драго Бо́га, уго́дниче Христо́в, да всі лю́діє возлю́б'ять друг дру́га і єдиноду́шно іспові́дять ві́ру Правосла́вную, воспіва́я Спаси́телю на́шему: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще доброді́тельноє житіє́ твоє́, ублажа́єм му́ченичеськую кончи́ну твою́, восхваля́єм і пренесе́ніє честни́х і многоціле́бних моще́й твої́х із сто́льнаго гра́да Ки́єва во град Чернигов, воспіва́єм сла́ву твою́, і́же на небесі́х, і усе́рдно мо́лим тя, страстоте́рпче кня́же І́горе: не возгнуша́йся нас, грі́шних і недосто́йних, зову́щих ті:","Ра́дуйся, я́ко вели́кия благода́ті от Бо́га сподо́бивийся.","Ра́дуйся, я́ко те́плий моли́твенник і засту́пник от Бо́га нам дарова́нний.","Ра́дуйся, я́ко всім призива́ющим тя ско́рий помо́щник бива́єши.","Ра́дуйся, духо́внаго весе́лія се́рдця на́ша ісполня́ющий.","Ра́дуйся, в ли́ці Ру́ських святи́х сла́вою мно́гою от Бо́га превознесе́нний.","Ра́дуйся, я́ко благочести́вих мно́жества любо́вію пра́зднують святу́ю па́м'ять твою́.","Ра́дуйся, святи́й благові́рний кня́же І́горе, во смире́нії за і́стину терп'я́щим ско́рий помо́щниче."]},{"h":"Кондак 13","ps":["О, многострада́льний страстоте́рпче Христо́в, благові́рний вели́кий кня́же І́горе! Прийми́ сіє́ ма́лоє, оба́че от лю́б'ящих серде́ць приноси́моє тебі́ сіє́ моле́ніє на́ше, защити́ всіх нас, за і́стину оби́ди і поноше́нія терп'я́щих, уврачу́й душе́вния і тіле́сния неду́ги, і от всіх бід і скорбе́й ізба́ви ни да, благода́рні су́ще, вопіє́м Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгельськи пожи́вши на землі́, от ю́ности возлюби́л єси́ Боже́ственноє уче́ніє і сему́ послі́довав до́брим житіє́м, немо́лчно прославля́л єси́ і́м'я Госпо́днє чте́нієм книг свяще́нних і пі́нієм церко́вним. Сего́ ра́ди тебе́, на небесі́ і на землі́ просла́вленному, вопіє́м си́це:","Ра́дуйся, от рожде́нія твоєго́ Бо́гом ізбра́нний.","Ра́дуйся, сі́м'я сло́ва Бо́жия от ю́ности восприя́вий.","Ра́дуйся, вели́кий уго́дниче Бо́жий, благочести́вую жизнь на землі́ возлюби́вий.","Ра́дуйся, путе́м тру́дним і ті́сним житіє́ земно́є проше́дий.","Ра́дуйся, пра́вди ра́ди ду́шу твою́ положи́вий.","Ра́дуйся, от Царя́ Небе́снаго, віне́ць му́ченичеський приє́мий.","Ра́дуйся, святи́й благові́рний кня́же І́горе, во смире́нії за і́стину терп'я́щим ско́рий помо́щниче."]},{"h":"Кондак 1","ps":["Ізбра́нний страстоте́рпче Христо́в, благові́рний кня́же І́горе, возсія́вий лю́дем твої́м, я́ко звізда́ пресві́тлая: ти бо сла́ву земна́го княже́нія оста́вил єси́ і во і́ночестві Го́сподеві рабо́тати вожделі́л єси́, страда́льчеськи земно́є житіє́ сконча́в, і ни́ні, ра́дуяся, предстої́ши престо́лу Святи́я Тро́йці. Моли́твами твої́ми от вся́ких зол і напа́стей охраня́й нас, да благода́рственно со умиле́нієм зове́м ті:","Ра́дуйся, святи́й благові́рний кня́же І́горе, во смире́нії за і́стину терп'я́щим ско́рий помо́щниче."]},{"h":"Молитва","ps":["О, святи́й уго́дниче Бо́жий, страстоте́рпче благові́рний, кня́же І́горе! Ти із мла́да Бо́га возлюби́л єси́, мудрова́нія плотська́я, честь і сла́ву кня́жеськую ні во что же вміни́л єси́ і мона́шеськаго о́браза, єще́ ю́ний лі́ти, дости́гл єси́, к Бо́гу єди́ному все́ю душе́ю твоє́ю приліпи́лся єси́, і благо́є і́го Христо́во на ся взем, путе́м спаси́тельним неукло́нно ше́ствовал єси́ да́же до сме́рти му́ченичеськия. Сего́ ра́ди вінча́ тя Госпо́дь, блаже́нне І́горе, вінце́м сла́ви і прия́т в Своя́ Небе́сния селе́нія, іді́же ти ни́ні, неізрече́нния сла́ви і ра́дости наслажда́ющеся в невече́рнім дні Ца́рствія Христо́ва, с ли́ки святи́х страстоте́рпцев і всіх святи́х Бо́га о нас умоля́єши. Мо́лимся тебі́, свя́тче Бо́жий, припа́дая к честно́му о́бразу твоєму́: моли́ся о нас грі́шних і непотре́бних, іспроси́ моли́твами твої́ми ми́ра держа́ві на́шей, гра́ду сему́ (і свято́му хра́му сему́) благода́ті і ми́лости. Це́рков святу́ю огради́ моли́твами твої́ми от єресе́й і раско́лов, па́стирем єя́ іспроси́ ре́вность і благоче́стіє, всім же нам любо́в нелицемі́рную і терпі́ніє да́руй, гріхо́в на́ших проще́ніє, болі́зней і вся́ких неду́гов ісціле́ніє. Покри́й і сохрани́ всіх нас от вся́ких бід, скорбе́й і напа́стей, да, благодаря́ще, просла́вим Святу́ю Живонача́льную Тро́йцю, Отця́ і Си́на і Свята́го Ду́ха, во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Наста́ днесь всечестна́я па́м'ять страстоте́рпця благові́рнаго кня́зя І́горя, / созива́ющая лю́ди в пречестни́й храм Спа́сов, / іді́же ра́достно соше́дшеся благочести́вих мно́жество / моли́твенно пра́зднують святу́ю па́м'ять твою́, / і с ві́рою взива́ють ті: / моли́ся, свя́те, страні́ Украї́нській, гра́ду Черні́гову і всім правосла́вним христия́ном // в ми́рі і благоде́нствії спасти́ся."]},{"h":"Кондак, глас 6","ps":["Ізміни́л єси́ земна́го княже́нія сла́ву / во і́ночества о́браз смире́нний / і страда́льчеськи земно́є житіє́ сконча́в, / ни́ні на Небесі́х ра́дуєшися, / усе́рдні моля́ся // о чту́щих тя, І́горе, страда́льцев похвало́."]},{"h":"Величання","ps":["Велича́єм тя, страстоте́рпче святи́й благові́рний вели́кий кня́же Іго́ре, і чтим святу́ю па́м'ять твою́, ти бо мо́лиши за нас Христа́ Бо́га на́шего."]}],"notes":[]},{"u":"Акафіст преподобному Агапіту Печерському, лікарю безмездному","e":"Akathist to our Venerable Father Agapitus of the Caves, the Unmercenary Physician","secs":[{"h":"Кондак 1","ps":["Ізбра́нний учениче́ вели́каго учи́теля, преподо́бнаго і богоно́снаго отця́ на́шего Анто́нія, і ди́вний подража́телю житія́ єго́ свята́го, свя́те о́тче Ага́пите, пі́снію восхва́лим тя с любо́вію, засту́пника на́шего; ти же, я́ко імі́яй дерзнове́ніє ко Го́споду, моли́ся ви́ну о спасе́нії нас, грі́шних, от вся́ких бід избавля́я зову́щих ті:","Ра́дуйся, Ага́пите, душе́вних і тіле́сних неду́гов ско́рий ціли́телю."]},{"h":"Ікос 1","ps":["А́нгелов любе́зную чистоту́ от ю́ности твоєя́ возлюби́в, блаже́нне Ага́пите, к доброді́телей подви́жнику, преподо́бному Анто́нію прите́кл єси́ і, от него́ во і́ночество облече́нний, подража́тель ре́вностний по́двигов єго́ бил єси́; ті́мже сла́вим тя воззва́нії си́ми:","Ра́дуйся, богоно́снаго Анто́нія доброді́телей і даро́в наслі́дниче;","ра́дуйся, на висоту́ соверше́нства духо́внаго возше́дий.","Ра́дуйся, моли́твами усе́рдними дар врачева́нія і чудотворе́нія от Го́спода получи́вий;","ра́дуйся, із глубини́ душі́ воздиха́ньми чистоту́ душе́вную стяжа́вий.","Ра́дуйся, Ага́пите, душе́вних і тіле́сних неду́гов ско́рий ціли́телю."]},{"h":"Кондак 2","ps":["Ви́дів Всеви́дець Госпо́дь благо́є душі́ твоєя́ ізволе́ніє, блаже́нне Ага́пите, є́же порабо́тати Єму́ безлі́ностно, внуши́ преподо́бному Анто́нію благослови́ти тя на жесто́коє в пеще́рнім затво́рі житіє́. Ти же, благослове́ніє свято́є с ві́рою приє́м, в пеще́рі поко́й ві́чний обрі́л єси́, Єди́ному Бо́гу рабо́тая в пі́ніїх, бді́ніїх і поще́ніїх, немо́лчно воспіва́я Єму́: Аллилу́я."]},{"h":"Ікос 2","ps":["Разумі́в преподо́бний Анто́ній проізволе́ніє Бо́жиє возсія́ти в сем і́ноці вельми́ благоуго́дним начина́нієм і душеспаси́тельним намі́ренієм, ізоби́льно наси́тил духо́вною сла́достію і в доброді́теліх укріпи́л єси́, сего́ ра́ди вопіє́м єму́ такова́я:","Ра́дуйся, преподо́бнаго Анто́нія нра́ви себі́ усво́ївий;","ра́дуйся, того́ житію́ усе́рдно поревнова́вий.","Ра́дуйся, сино́вню любо́в к нему́ стяжа́вий;","ра́дуйся, і от него́ зіло́ возлю́бленний.","Ра́дуйся, самови́дче єго́ по́двигов;","ра́дуйся, во врачева́нії неду́гов єму́ споспешеству́ющий.","Ра́дуйся, Ага́пите, душе́вних і тіле́сних неду́гов ско́рий ціли́телю."]},{"h":"Кондак 3","ps":["Си́лою Бо́жиєю укріпля́ємий, свя́те Ага́пите, вели́кия і́ночеськия труди́ под'я́л єси́; сего́ ра́ди благослови́ся ді́ло руку́ твоє́ю во сла́ву і́мені Госпо́дня на спасе́ніє і врачева́ніє всіх, с ві́рою і наде́ждою к тебі́ притека́ющих і нелі́ностно вознося́щих піснь Пресвяті́й Тро́йце: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я по́мисл чист і непоро́чну со́вість і па́м'ятуя Ре́кшаго: «Бо́лен біх, і посіти́сте Мене́… поне́же сотвори́сте єди́ному сих бра́тій Мої́х ме́нших, Мні сотвори́сте», неду́гующих і́ноков под свой покро́в оте́чеськи приє́мля, я́коже роди́телі ча́да своя́, утіша́л єси́, отра́ду свої́м попече́нієм подаю́ще і оте́чеською ла́ською тя́жесть болі́зні облегча́юще, моли́твою с одра́ болі́зні воздвиза́л єси́. Сего́ ра́ди прийми́ от нас благохвале́нія такова́я:","Ра́дуйся, в доброді́теліх благоїску́сний подви́жниче;","ра́дуйся, во Христі́ всю бра́тію мона́шеськую возлюби́вий.","Ра́дуйся, неду́жних і́ноков смире́нний і неуси́пний служи́телю;","ра́дуйся, за по́двиги вре́меннаго житія́ поко́й ві́чний обрі́тший.","Ра́дуйся, Ага́пите, душе́вних і тіле́сних неду́гов ско́рий ціли́телю."]},{"h":"Кондак 4","ps":["Бу́рю многом'яте́жнаго жите́йськаго мо́ря безбі́дно проше́л єси́, блаже́нне, і в при́стань безстра́стія дости́гл єси́, окормля́єм за́повідьми Христа́ Бо́га, я́же би́ша світи́льник нога́ма твої́ма і світ стезя́м твої́м. Ті́мже ни́ні в го́рніх оби́теліх водворя́єшися, сла́дці поя́ Трієди́ному Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шавше мно́зі о благоуго́днем житії́ твоє́м, блаже́нне Ага́пите, прихожда́ху к тебі́: о́ви послу́шати поуче́ній твої́х, о́ви ісціле́ній от разли́чних неду́гов прия́ти; ї́хже ти, с оте́чеською любо́вію приє́мля, руково́дствовал єси́ ко спасе́нію, отгоня́я всяк неду́г і вся́ку не́мощ. Сего́ ра́ди і ми прибіга́єм к тебі́, вели́кому помо́щнику і ціли́телю, сла́в'яще тя си́це:","Ра́дуйся, безмо́лвія люби́телю, оби́тель Пече́рськую по́двиги свої́ми украси́вий;","ра́дуйся, спасе́нія мно́гих душ челові́чеських вино́вниче.","Ра́дуйся, болі́знующих гріхми́ врачу́ благоїску́сний;","ра́дуйся, во́їне Христо́в, полки́ неви́димих враго́в побіди́вий.","Ра́дуйся, бли́жнія твоя́ і́скренні возлюби́вий;","ра́дуйся, спасе́нію їх душе́вному і ісціле́нію тіле́сному усе́рдно послужи́вий.","Ра́дуйся, Ага́пите, душе́вних і тіле́сних неду́гов ско́рий ціли́телю."]},{"h":"Кондак 5","ps":["Боготе́чноє світи́ло бив, уго́дниче Бо́жий, всіх к Со́лнцю Пра́вди – Христу́ путеводи́л єси́ приме́ром житія́ твоєго́ свята́го, і́же все бисть посвяще́но на служе́ніє Бо́гу і бли́жнім твої́м. Ни́щія і убо́гія ми́лостивно пита́л єси́, ті́мже блаже́нство ми́лостивих унаслі́довал єси́ і со святи́ми поє́ши ві́чно хвале́бную піснь: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дим тя, блаже́нне о́тче Ага́пите, дости́гшаго в мі́ру му́жа соверше́нна о Христі́ і преіспо́лненна дарова́ній Боже́ственних, в Єва́нгелії Христо́ві обітова́нних ві́рним после́дователем Бо́га Сло́ва. Ті́мже, чудя́щеся твої́м подвиго́м, поє́м ті хвале́бно:","Ра́дуйся, в глубині́ се́рдця би́сер драги́й – Го́спода Ісу́са Христа́ – обріти́й;","ра́дуйся, і́м'я Єго́ Боже́ственноє во усті́х і в се́рдці своє́м ви́ну імі́вий.","Ра́дуйся, на землі́ алка́вий і жа́ждавий, ни́ні же нетлі́нния пи́щі на небесі́ насища́яйся;","ра́дуйся, нищету́ храни́вий, ни́щих от гла́да ізбавля́яй.","Ра́дуйся, і́го Христо́во благо́є і ле́гкоє і́скренні возлюби́вий.","Ра́дуйся, Ага́пите, душе́вних і тіле́сних неду́гов ско́рий ціли́телю."]},{"h":"Кондак 6","ps":["Пропові́дник бив житіє́м твої́м Єва́нгельських доброді́телей, о́тче блаже́нне, плоть твою́ посто́м і моли́твою порабо́тил єси́ і во сла́ву Бо́жию пожи́л єси́; луча́ми свої́х по́двигов всезло́бнаго врага́, арм'я́нина нечести́ваго, за́вистію і гні́вом пали́маго і свої́ми зло́стними ухищре́ньми веселя́щася, не то́кмо посрами́л єси́, но і к сві́ту Христо́вой і́стини приве́л єси́, поуча́я за все благодари́ти і славосло́вити Го́спода, поя́ Єму́: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́во в пеще́рі святи́я оби́телі сія́, я́ко богоно́сноє світи́ло, блаже́нне Ага́пите, сві́том до́брих діл і врачева́ній умили́л єси́ ду́ші і сердця́ челові́ков, а нечести́ваго врача́ і зави́стника і єго́ безсту́дноє безу́міє посрами́л єси́. Тім у́бо тебі́, свято́му і блаже́нному уго́днику, уми́льно зове́м:","Ра́дуйся, врачева́ніє нечести́ваго арм'я́нина посрами́вий;","ра́дуйся, обрече́ннаго на смерть тім же арм'я́нином неду́гующаго со одра́ болі́зні воздви́гнувий.","Ра́дуйся, осужде́ннаго на смерть і напоє́ннаго сме́ртним я́дом чуде́сно ісціли́вий і от сме́рти ізба́вивий;","ра́дуйся, іспи́вий сме́ртний яд от врага́ і, по сло́ву Госпо́дню: «А́ще что і сме́ртно іспію́ть, не вреди́ть їх», — живо́т невреди́мий сохрани́вий.","Ра́дуйся, зло́бу і кова́рство враго́в свої́х посрами́вий.","Ра́дуйся, Ага́пите, душе́вних і тіле́сних неду́гов ско́рий ціли́телю."]},{"h":"Кондак 7","ps":["Хоті́ніє єди́ноє імі́л єси́, блаже́нне о́тче, є́же Бо́гу угожда́ти і спасе́нію душе́вному і здра́вію тіле́сному бли́жніх твої́х благоче́стно служи́ти. Ті́мже ке́ллія твоя́ пеще́рная бисть враче́бниця благооти́шная вся́кому челові́ку – ни́щему і бога́тому, кня́зю і убо́гому. Ти же, єди́ноє в се́рдці імі́я: «Всім бих вся», врачева́л єси́, не взира́я на ли́ця, призива́я всіх вку́пі се́рдцем і усти́ немо́лчно возглаша́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́ваго тя чудотво́рця вели́каго позна́ сла́вний князь Влади́мир Монома́х, на одрі́ болі́зні возлежа́, пребива́я при кончи́ні своє́й, сле́зно моли́л єси́ тя притещи́ і ісціли́ти єго́. Но ти, мона́шеський обі́т соблюда́я - ніколи́же стін оби́телі оставля́ти, посла́л єси́ зе́ліє от трапе́зи своєя́, і князь, вкуси́в єго́, здрав воста́ша. Таково́й си́лі твоєго́ чудотворе́нія і нелицеприя́тія див'я́щеся, вопіє́м ті хвале́бно:","Ра́дуйся, кри́не пеще́рнаго прозябе́нія;","ра́дуйся, ми́ра Христо́ва благоуха́ніє.","Ра́дуйся, не скри́вий тала́нт врачева́нія, тебі́ Домовлади́кою вруче́нний;","ра́дуйся, ра́ди си́льних ми́ра сего́ обі́та і́ночеськаго не нару́шивий.","Ра́дуйся, сла́ви ра́ди ви́шняго зва́нія сла́ву челові́чеськую ні во что́же вміни́вий;","ра́дуйся, Вели́каго кня́зя Влади́мира Монома́ха с одра́ сме́ртнаго неду́га би́лієм, тобо́ю благослове́нним, і моли́твою под'я́л єси́.","Ра́дуйся, Ага́пите, душе́вних і тіле́сних неду́гов ско́рий ціли́телю."]},{"h":"Кондак 8","ps":["Стра́нника і прише́льця в ми́рі сем помишля́л єси́ себе́ би́ти, Ага́пите блаже́нне, ті́мже о бога́тстві земні́м вся́коє попече́ніє отложи́л єси́. Вся́коє стяжа́ніє су́єтноє возбраня́я, приходя́щих к тебі́ разділя́ти достоя́ніє своє́ с ни́щею бра́тією і в єя́ лице́ Самому́ Христу́ служи́ти поуча́л єси́, немо́лчно воспіва́я хвале́бную піснь: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь в Бо́зі бив, о́тче блаже́нне, о Бо́зі і угожде́нії Єму́ при́сно поуча́л єси́, умоля́я нічто́же предпочита́ти па́че любве́ Христо́ви і, па́м'ятуя рече́нноє Христо́м: «Не собира́йте себі́ сокро́вища на землі́, іді́же моль і ржа істребля́ють, но собира́йте себі́ сокро́вища на небесі́»,– не пожела́л ра́ди благ вре́менних лиши́тися благ ві́чних, отверга́л єси́ вся да́ри, тебі́ кня́зем приноси́мия, поуча́я раздава́ти їх ни́щей бра́тії і убо́гим. Ті́мже і ми, таково́є твоє́ нищелю́біє восхваля́я, зове́м ті си́це:","Ра́дуйся, блаже́нство ни́щих ду́хом унаслі́довавий;","ра́дуйся, нищету́ па́че бога́тства возлюби́вий.","Ра́дуйся, мзду за своє́ врачева́ніє отве́ргий і разда́ти ю ни́щим і убо́гим повелі́вий;","ра́дуйся, послі́днія укру́хи хлі́ба своєго́ с неіму́щими разділя́ти поуча́вий.","Ра́дуйся, любо́в к Бо́гу любо́вію к бли́жнім свої́м свиде́тельствовавий;","ра́дуйся, похвала́ми моли́твенними до днесь в оби́телі Пече́рськой зіло́ почита́ємий.","Ра́дуйся, Ага́пите, душе́вних і тіле́сних неду́гов ско́рий ціли́телю."]},{"h":"Кондак 9","ps":["Всім приходи́вшим в оби́тель моли́тв і врачева́нія ра́ди, блаже́нне о́тче, ди́вно бисть ви́діти тебе́, ни́щетно в ке́ллії твоє́й пребива́ющаго, оба́че ти, всіх ра́вною любо́вію приє́мля, коєму́ждо сло́во утіше́нія іли́ ісціле́ніє подава́л єси́, науча́я пі́ти вино́внику всіх благи́х Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́я многовіща́нния не возмо́гуть досто́йно воспі́ти по́двиги і чудотворе́нія твоя́, блаже́нне Ага́пите, ми же, таково́му житію́ твоєму́ див'я́щеся, дерза́єм вінча́ти тебі́, а́ще і недосто́йнії, похвала́ми такови́ми:","Ра́дуйся, на скрижа́ліх се́рдця твоєго́ Зако́н Христо́в написа́вий;","ра́дуйся, от глубини́ серде́чния до́брая і душеспаси́тельная наставле́нія челові́ком ізноси́вий.","Ра́дуйся, пеще́рний граждани́не, гра́ди і ве́сі напо́лнивий сла́вою твої́х чудотворе́ній;","ра́дуйся, Бо́гом возлю́бленний і бли́жніми твої́ми благословля́ємий.","Ра́дуйся, о́браз соверше́нства о Христі́ в себі́ яви́вий;","ра́дуйся, і́го Христо́во, благо́є і ле́гкоє, і́скренні возлюби́вий.","Ра́дуйся, Ага́пите, душе́вних і тіле́сних неду́гов ско́рий ціли́телю."]},{"h":"Кондак 10","ps":["Спасе́нія наде́жду стяжа́л єси́ при ісхо́ді твоє́м, блаже́нне о́тче Ага́пите, і я́ко пшени́ця зрі́лая, во вре́м'я пожа́тія, кончи́ною благо́ю пресели́лся єси́ в день, тебі́ пре́жде ука́занний Го́сподом, во оби́телі го́рнія, прия́ти мзду от руки́ пра́веднаго Мздовоздая́теля Христа́, І́же вчини́ ду́шу твою́ со ду́хи святи́х, немо́лчно возглаша́ющих пред Престо́лом сла́ви Єго́ побі́дную піснь: Аллилу́я."]},{"h":"Ікос 10","ps":["Царя́ Небе́снаго Христа́ ві́рний раб і послі́дователь бил єси́, о́тче Ага́пите, ті́мже по нело́жному Єго́ глаго́лу: «Іді́же єсьм Аз, ту і слуга́ Мой бу́деть», ми, чту́ще тя, ві́руєм несумні́нно, я́ко ти со Христо́м во оби́теліх блаже́нства ві́чнаго водворя́єшися і ра́дости нетлі́нния наслажда́єшися, я́ко і́стинний Того́ уго́дник; от нас же сли́шиши благохвале́нія сія́:","Ра́дуйся, предсказа́нія нечести́ваго арм'я́нина о твоє́й сме́рті посрами́вий;","ра́дуйся, о дне твоєя́ блаже́нния кончи́ни от Го́спода ізвеще́нний.","Ра́дуйся, ду́шу твою́ в ру́ці Го́спода ра́достно преда́вий;","ра́дуйся, открове́нним лице́м сла́ву Трисія́ннаго Божества́ созерца́яй.","Ра́дуйся, ті́лом сме́ртним в пеще́рі погребе́нний;","ра́дуйся, душе́ю безсме́ртною к Сіо́ну го́рнему воспари́вий.","Ра́дуйся, Ага́пите, душе́вних і тіле́сних неду́гов ско́рий ціли́телю."]},{"h":"Кондак 11","ps":["Пі́ніє Пресвяті́й Богоро́дице прино́сиши, блаже́нне о́тче наш Ага́пите, о оби́телі твоє́й святі́й і подвиза́ющихся в ней, і о всіх с любо́вію к тебі́ притека́ющих при́сно хода́тайствуєши, прося́ ми́ра сви́ше і благопоспеше́нія всім, вознося́щим достодо́лжная похвали́ Трієди́ному Бо́гу, воспіва́я Єму́: Аллилу́я."]},{"h":"Ікос 11","ps":["Світи́льника тя до́брих діл, блаже́нне о́тче, іспові́дуєм би́ти і прославля́єм просла́вльшаго тя Го́спода, І́же чудеси́ мно́гими мо́щі твоя́ озна́менова: струї́ бо ісціле́ній благода́тних істоча́єши от них неду́жним і подвиза́єши ві́рния вопи́ти тебі́:","Ра́дуйся, земни́й а́нгеле і небе́сний челові́че;","ра́дуйся, безме́зднаго врачева́нія істо́чниче.","Ра́дуйся, ми́ра многоціле́бнаго преіспо́лненний фія́ло;","ра́дуйся, от ра́ки твоєя́ святи́я ісціле́нія оби́льно подава́яй.","Ра́дуйся, скорб'я́щих уті́шителю;","ра́дуйся, унива́ющих ободри́телю.","Ра́дуйся, Ага́пите, душе́вних і тіле́сних неду́гов ско́рий ціли́телю."]},{"h":"Кондак 12","ps":["Благода́ть Госпо́дню іспроси́ нам, о́тче Ага́пите, почита́ющим с любо́вію святу́ю па́м'ять твою́ і усе́рдно притека́ющим к честні́й ра́ці моще́й твої́х, от нея́же чуде́сния ісціле́нія подає́ши неду́жним. Ті́мже тебе́, чудотворе́нія да́ром от Бо́га просла́вленному, прилі́жно мо́лимся: ісціли́ на́ша неду́ги душе́вния і тіле́сния і помози́ нам предста́тельством твої́м спасе́ніє ві́чноє получи́ти, да вку́пі с тобо́ю воспоє́м ди́вному во святи́х Свої́х Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще по́двиги твоя́, блаже́нне о́тче, ублажа́єм равноа́нгельськоє житіє́ твоє́, диві́мся чудотворе́нієм твої́м, моли́твенно почита́єм святу́ю па́м'ять твою́ і, припа́дающе к ра́ці моще́й твої́х, уми́льно взива́єм:","Ра́дуйся, Пресвяти́я Богоро́диці досто́йний моли́твенниче;","ра́дуйся, пещерожи́телей сла́во і похвало́.","Ра́дуйся, святи́я оби́телі Пече́рськия, вку́пі с Анто́нієм і Феодо́сієм, при́сноє охране́ніє;","ра́дуйся, подвиза́ющихся в ней благонаде́жноє заступле́ніє.","Ра́дуйся, приходя́щих в ню на поклоне́ніє благи́й предста́телю;","ра́дуйся, почита́ющих па́м'ять твою́ небе́сний покрови́телю.","Ра́дуйся, Ага́пите, душе́вних і тіле́сних неду́гов ско́рий ціли́телю."]},{"h":"Кондак 13","ps":["О, преблаже́нне о́тче Ага́пите! Ти – го́ре на небесі́, ми же – до́лу на землі́, удале́нния от тебе́ не толи́ко мі́стом, коли́ко гріхо́вною нечистото́ю на́шею, оба́че дерза́єм приноси́ти тебі́ сіє́ ма́лоє похва́льноє пі́ніє, єго́же ми́лостивно приє́м, моли́ Го́спода і Влади́ку на́шего ізба́вити нас поги́белі ві́чния і сподо́бити блаже́нства святи́х, вопію́щих Єму́ ви́ну хвале́бную піснь: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелов любе́зную чистоту́ от ю́ности твоєя́ возлюби́в, блаже́нне Ага́пите, к доброді́телей подви́жнику, преподо́бному Анто́нію прите́кл єси́ і, от него́ во і́ночество облече́нний, подража́тель ре́вностний по́двигов єго́ бил єси́; ті́мже сла́вим тя воззва́нії си́ми:","Ра́дуйся, богоно́снаго Анто́нія доброді́телей і даро́в наслі́дниче;","ра́дуйся, на висоту́ соверше́нства духо́внаго возше́дий.","Ра́дуйся, моли́твами усе́рдними дар врачева́нія і чудотворе́нія от Го́спода получи́вий;","ра́дуйся, із глубини́ душі́ воздиха́ньми чистоту́ душе́вную стяжа́вий.","Ра́дуйся, Ага́пите, душе́вних і тіле́сних неду́гов ско́рий ціли́телю."]},{"h":"Кондак 1","ps":["Ізбра́нний учениче́ вели́каго учи́теля, преподо́бнаго і богоно́снаго отця́ на́шего Анто́нія, і ди́вний подража́телю житія́ єго́ свята́го, свя́те о́тче Ага́пите, пі́снію восхва́лим тя с любо́вію, засту́пника на́шего; ти же, я́ко імі́яй дерзнове́ніє ко Го́споду, моли́ся ви́ну о спасе́нії нас, грі́шних, от вся́ких бід избавля́я зову́щих ті:","Ра́дуйся, Ага́пите, душе́вних і тіле́сних неду́гов ско́рий ціли́телю."]},{"h":"Молитва перша","ps":["О, всеблаже́нне Ага́пите, земни́й а́нгеле і небе́сний челові́че! Припа́даєм к тебі́ с ві́рою і любо́вію і мо́лим ті ся прилі́жно: яви́ нам, смире́нним і грі́шним, свято́є своє́ заступле́ніє; се бо гріх ра́ди на́ших не і́мами свобо́ди чад Бо́жиїх проси́ти о потре́бах на́ших Го́спода і Влади́ку на́шего, но тебі́, моли́твенника благоприя́тна, к Нему́ предлага́єм і про́сим тя со усе́рдієм мно́гим: іспроси́ нам от бла́гости Єго́ благопотре́бния да́ри душа́м і тілесе́м на́шим: ві́ру пра́ву, любо́в ко всім нелицемі́рну, в злострада́ніїх – терпі́ніє, тя́жкими болі́зньми одержи́мим — от неду́гов ісціле́ніє, под бре́менем скорбе́й і напа́стей неудобоноси́мих па́дающим і житія́ своєго́ отча́явшимся твої́ми моли́твами получи́ти ско́роє облегче́ніє і ізбавле́ніє. Не забу́ди, блаже́нне о́тче, і оби́тель твою́ святу́ю, при́сно тя чту́щую, і соблюди́ ю і всіх, живу́щих і подвиза́ющихся в ней і на поклоне́ніє в ню приходя́щих, невреди́мими от іскуше́ній дия́вольських і вся́каго зла. Єгда́ же приспі́єть на́ше от вре́меннаго сего́ житія́ отше́ствіє і к ві́чності преселе́ніє, не лиши́ нас по́мощі твоєя́ небе́сния, но моли́твами твої́ми всіх нас приведи́ в приста́нище спасе́нія і наслі́дники яви́ нас би́ти всесві́тлаго Ца́рствія Христо́ва, да поє́м і сла́вим неізрече́нния щедро́ти Человіколю́бця Бо́га, Отця́ і Си́на і Свята́го Ду́ха, і твоє́ вку́пі с преподо́бними Анто́нієм і Феодо́сієм оте́чеськоє заступле́ніє во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["Преподо́бне о́тче Ага́пите! Воззри́ на нас ми́лостивно і к землі́ приве́рженних возведи́ к висоті́ небе́сній. Ти – го́ре на небесі́, ми – на землі́ ни́зу, удалени́ от тебе́ не толи́ко мі́стом, єли́ко гріха́ми свої́ми і беззако́нії, но к тебі́ прибіга́єм і взива́єм: наста́ви нас ходи́ти путе́м твої́м, вразуми́ і руково́дствуй нас. Вся твоя́ свята́я жизнь бисть зерца́лом вся́кия доброді́телі. Не преста́ни, уго́дниче Бо́жий, о нас вопи́ти ко Го́споду. Іспроси́ предста́тельством свої́м у Всеми́лостиваго Бо́га на́шего мир Це́ркві Єго́, под зна́менієм креста́ во́їнствующей, согла́сіє во ві́рі і єдиному́дріє, суєму́дрія же і раско́лов істребле́ніє, утвержде́ніє во благи́х ді́ліх, больни́м ісціле́ніє, печа́льним утіше́ніє, оби́женним заступле́ніє, бе́дствующим по́мощ. Не посрами́ нас, к тебі́ с ві́рою притека́ющих. Всі правосла́внії христия́не, твої́ми чудеси́ іспо́лненнії і ми́лостьми облагоде́тельствованнії, іспові́дають тя би́ти своєго́ покрови́теля і засту́пника. Яви́ дре́внія ми́лості твоя́, ї́хже отце́м вспомоществова́л єси́, не отри́ни і нас, чад їх, стопа́ми їх к тебі́ ше́ствующих. Предстоя́ще всечестні́й іко́ні твоє́й, я́ко тебі́ жи́ву су́щу, припа́даєм і мо́лимся: прийми́ моле́нія на́ша і вознеси́ їх на же́ртвенник благоутро́бія Бо́жия, да при́ймем тобо́ю благода́ть і благовре́менную в ну́ждіх на́ших по́мощ. Укріпи́ нас, малоду́шних, і утверди́ во ві́рі, да несомні́нно упова́єм получи́ти вся блага́я от благосе́рдія Влади́ки моли́твами твої́ми. О, превели́кий уго́дниче Бо́жий! Всім нам, с ві́рою притека́ющим к тебі́, помози́ предста́тельством твої́м ко Го́споду і всіх нас упра́ви в ми́рі і покая́нії сконча́ти живо́т наш і пресели́тися со упова́нієм в блаже́нния ні́дра Авраа́мова, іді́же ти ра́достно ни́ні почива́єши, прославля́я со всі́ми святи́ми Бо́га, в Тро́йці сла́вимаго, Отця́ і Си́на і Свята́го Ду́ха, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 5","ps":["Богоно́снаго Анто́нія ревну́я смиренному́дрію, / а́ки ні́киїм врачество́м зе́лієм сні́дним / ісціля́л єси́ боля́щия, преподо́бне Агапи́те, / тім і врача́ неві́рна уві́рив, / наста́вил єси́ на путь спасе́нія. / Уврачу́й і на́ша болі́зні // і моли́ся Го́сподеві о воспіва́ющих тя."]},{"h":"Кондак, глас 6","ps":["Врач сий ізря́ден, чу́дне, / явля́я несумне́нную твою́ ві́ру, / облича́я же армени́ново неві́ріє / і приводя́ єго́ к благоче́стію, / себі́, близ сме́рти би́вшу, / іспроси́л єси́ от Бо́га продолже́ніє живота́ / і, сим чу́дом того́ уві́рив, / приве́л єси́ Христо́ві, / Єму́же во весе́лії предстоя́, // моли́ся о нас, преподо́бне."]},{"h":"Величання","ps":["Ублажа́єм тя, / преподо́бне о́тче Агапи́те, / і чтим святу́ю па́м'ять твою́, / наста́вниче мона́хов // і собесі́дниче А́нгелов."]}],"notes":[]},{"u":"Акафіст преподобному Іллі Муромцю, Києво-Печерському чудотворцю","e":"Akathist to our Venerable Father Elijah of Murom, Wonderworker of the Kyiv Caves","secs":[{"h":"Кондак 1","ps":["Воєво́ді сил землі́ Ру́ськия, во́їну Царя́ Христа́ і засту́пнику Русі́ Свято́й, сла́вному во бра́ніх і неодолимому в ра́тіх, ди́вному богатирю Ілії́ Муромцю піснь хвале́бную воспоє́м, да засту́пить і ни́ні нас, зову́щих:","Ра́дуйся, преподо́бне о́тче Іліє́, землі́ Ру́ськия сла́вний засту́пниче."]},{"h":"Ікос 1","ps":["А́нгелов Творе́ць, єгда́ во ра́бії зра́ці на зе́млю снисшел, до тридесятьлетняго во́зраста не явля́л єси́ себ'я́ ми́ру, та́ко і тя, свя́те Іліє́, сподо́би до того́жде во́зрасту нікому́ неведомим би́ти і недвижимим тіле́сні, да по́сліжде послу́жиши Го́споду і лю́дем Єго́ со всім усе́рдієм і ре́вностію, є́же ми восхваля́єм:","Ра́дуйся, промишле́нієм Бо́жиїм три́десять літ прему́дро храни́мий;","Ра́дуйся, от рожде́нія ізбра́нний, да являться на тебі́ діла́ Госпо́дня.","Ра́дуйся, чрез неду́г свой собла́знов ю́ности мно́гих ізбегнувий;","Ра́дуйся, ду́шу чи́сту чрез страда́нія соблюди́й.","Ра́дуйся, си́ми на прия́тіє благода́ті ю угото́вавий;","Ра́дуйся, болі́зні, я́ко дар Бо́жий, с покорностью терпі́вий,","Ра́дуйся, преподо́бне о́тче Іліє́, землі́ Ру́ськия сла́вний засту́пниче."]},{"h":"Кондак 2","ps":["Ви́ді внеза́пу святи́й Іліє́ я́вльшихся єму́ тріє́х муже́й-стра́нников, прося́щих у него́ води́ іспи́ти, отвещая їм: Я́ко напоі́л би вас, да не і́мам хожде́нія нагама мої́ма, і накорми́л би та́коже, да рука́ма мої́ма не і́мам владенія, тім же ста́рці три́щі повелі́ша єму́ на но́зі ста́ти і послужи́ти і́ма, скочи́в же тогда́ Іліє́ на но́зі свої́, возопи́л Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Разумі́в Іліє́, я́ко ісцілі́ внеза́пу от неду́га своєго́, пе́рвіє крест по-пи́санному на себі́ положи́, пото́м же стра́нников напої́, они́ же та́кожде да́ша єму́ ча́шу питія́ медвяна, реко́ша іспи́ти до дна ю, той же повину́ся і́ма, сотвори́ сіє́, ми же, грі́шнії, див'я́щеся зове́м:","Ра́дуйся, я́ко во о́бразі тріє́х стра́нников Госпо́дь при́йде посіти́ти тя;","Ра́дуйся, я́ко Тро́йця Свята́я яви́ся ті.","Ра́дуйся, ісцілі́вий по словесі́ Госпо́дню;","Ра́дуйся, от одра́ воздви́гнутий во́лею Бо́жиєю.","Ра́дуйся, Ча́шу от руки́ Спасителеви іспи́вий;","Ра́дуйся, наполенний благода́тію Христо́вою.","Ра́дуйся, преподо́бне о́тче Іліє́, землі́ Ру́ськия сла́вний засту́пниче."]},{"h":"Кондак 3","ps":["Си́лу вели́кую почуяв в себі́, Іліє́, іспи́в ча́шу чудодейственную, я́ко мо́щі ті гори́ преставля́ти і дре́ва дубра́вная із землі́ історга́ти, рече́ о сем стра́нником, вопрошающим о явле́нії си́ли твоєя́, і в ра́дості воспі́л Спаси́телю: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́єши ни́ні силушку богатирськую, та і жи́ви, Іліє́, да бу́деши во́їном, і в боях смерть ті не бу́де пи́сана, — реко́ша странници і, благослови́вше тя, ісчезо́ша а́біє, я́коже і яви́шася, ми же, позна́вше на тебі́ ру́ку Госпо́дню, поє́м:","Ра́дуйся, хожде́ніє приє́мий нога́ма, да і́деши на стезі́ пра́вия;","Ра́дуйся, владеніє приє́мий рука́ма, да твори́ши діла́ богоуго́дния.","Ра́дуйся, здра́віє приє́мий, да потруди́шися Бо́гу в по́ті лиця́ твоєго́;","Ра́дуйся, ісціле́ніє приє́мий, да порабо́таєши, Ісцелившему тя.","Ра́дуйся, благослове́ніє приє́мий, да соблюде́ши ду́шу свою́ во благоче́стії;","Ра́дуйся, си́лу ве́лію приє́мий, да просла́виши є́ю і́м'я Всеси́льнаго.","Ра́дуйся, преподо́бне о́тче Іліє́, землі́ Ру́ськия сла́вний засту́пниче."]},{"h":"Кондак 4","ps":["Бу́рею недоумі́нія об'яшася роди́теля твоя́ і у́жасом ве́ліїм диви́шася зіло́, ви́дяща тя прише́дша, і нога́ма, і рука́ма ісцілі́вша, возопи́ша ра́дующеся: Сла́ва, сла́ва Го́споду, Всеви́шнему хвала́: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шав благослове́ніє Госпо́днє, не можа́ше долеє до́ма оставатися, я́ко приспі́ час по́двиг твої́х, іспроси́ у отця́ – ма́тері дозволеніє отити в зе́млю да́льнюю, оте́ць же рече́ ті: Я на до́брия діла́ тебі́ благослове́ніє дам, на худи́я же діла́ благословеннія ність ті, ти же покло́нься земно, ісше́д в путь, є́же ми воспіва́єм:","Ра́дуйся, словеса́ Христо́ви жи́знію іспо́лнивий;","Ра́дуйся, Бо́га і бли́жніх па́че отця́ і ма́тері возлюби́вий.","Ра́дуйся, любо́в Бо́жию любві́ родительстей предпочетший;","Ра́дуйся, дом о́тчий оста́вивий, да всему́ Оте́чествію слу́жбу сослужиши.","Ра́дуйся, богатир святоруський, возращенний ду́хом Христо́вим;","Ра́дуйся, це́ркві і Русі́ охранителем от Него́ поста́вленний.","Ра́дуйся, преподо́бне о́тче Іліє́, землі́ Ру́ськия сла́вний засту́пниче."]},{"h":"Кондак 5","ps":["Боготечно бисть стра́нствіє твоє́ ко гра́ду Ки́єву. Я́ко пе́рвіє та́мо хоті́л єси́ в це́рквах Бо́жиїх Го́споду помоли́тися і Богома́тері Пече́рстій в Ла́врі Успестей поклони́тися, за ісціле́ніє благода́рні хвалу́ воспі́ти єму́ пі́снію: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дя ско́рби ве́лія, постигшия зе́млю Ки́євськую от нахожде́нія пога́них, нача́ло положи́ по́двигом свої́м, град Чернигов і стезю́ ко гра́ду Ки́єву свобожда́я і враго́во ві́ри христия́нськия істребля́я, да лю́діє, тобо́ю свобожденнії, вопію́ть:","Ра́дуйся, щит спасе́нія, є́же єсть глаго́л Бо́жий, восприя́вий;","Ра́дуйся, копіє́м ві́ри нечести́вих прободивий.","Ра́дуйся, па́лицею благоче́стія неві́рних одолі́вий;","Ра́дуйся, шеломом цілому́дрія ся от стріл вра́жиїх сохрани́вий.","Ра́дуйся, доспехами доброді́телей ся преодевий;","Ра́дуйся, во всеору́жії духо́внім враго́м ратоборствовавий.","Ра́дуйся, преподо́бне о́тче Іліє́, землі́ Ру́ськия сла́вний засту́пниче."]},{"h":"Кондак 6","ps":["Пропові́дник могущества Бо́га Христия́нськаго яви́лся єси́, Іліє́, ра́ти іноплеме́нния вся возмоги́й побіжда́ти о укріпля́ющем тя Ісу́се, христия́не же, свобожде́нії тобо́ю, не престава́ху зва́ти: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ тогда́ звізда́ світоза́рная во гра́ді Ки́єве – я́сний молодець богатир Ілия Муромець, на устраше́ніє нечести́вих, жестокосе́рдих на попра́ніє, землі́ Ру́ськой на прославле́ніє Бо́гом да́нний, іді́же сро́дниці твої́ досе́лі тя велича́ють:","Ра́дуйся, войська ру́ськаго предводи́телю;","Ра́дуйся, сирота́м і вдови́цям охрани́телю.","Ра́дуйся, кня́зю стольному ві́рноє вспоможе́ніє;","Ра́дуйся, градово́м і ве́сем наде́жноє средості́ніє.","Ра́дуйся, си́ли вра́жия благода́тноє одолі́ніє;","Ра́дуйся, наро́да правосла́внаго возвише́ніє.","Ра́дуйся, преподо́бне о́тче Іліє́, землі́ Ру́ськия сла́вний засту́пниче."]},{"h":"Кондак 7","ps":["Хотя́ще от всея́ душі́ і се́рдця Бо́гу порабо́тати і Русі́ Свято́й, по́мисл тщесла́вний отве́рг, єгда́ тя ні́циї тща́хуся воєводой гра́да Черни́гова поста́вити, со смире́нієм на слу́жбу ко кня́зю ки́євському поступил єси́, да не такмо єди́ному некому гра́ду, но всему́ наро́ду слу́жбу сослужиши, я́ко невозбра́нно пі́ти Бо́гу єму́: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вим Сампсоном на землі́ об'явивийся, но́вому Ізра́їлю – Оте́чествію Ру́ському Правосла́вному послужи́вий ві́рою і пра́вдою, Іліє́ приснопа́м'ятне, соратуй і ни́ні сродницем твої́м, зовущим:","Ра́дуйся, я́ко Дави́д во і́м'я Го́спода Савао́фа сражавийся;","Ра́дуйся, я́ко Галіяфа той, та́ко і ти великана інозе́мнаго порази́вий.","Ра́дуйся, я́ко Сампсо́н, си́лою превеликою от Бо́га наделенний;","Ра́дуйся, ре́вностію о Бо́зі проро́ку Ілії́ тезоіме́нний.","Ра́дуйся, я́ко Данії́л зія́нія львов — неві́рних чужеземцев загради́вий;","Ра́дуйся, А́нгел — храни́тель преді́лам кня́жества ру́ськаго би́вий.","Ра́дуйся, преподо́бне о́тче Іліє́, землі́ Ру́ськия сла́вний засту́пниче."]},{"h":"Кондак 8","ps":["Стра́нствуя по стороне києвстей і оберегая ю от лихих разбо́йник, бога́тства і че́сти не іска́л єси́ себе́, но аз іду́ служи́ти за ві́ру христия́нськую, і за зе́млю Ру́ськую, да і за сто́льний Ки́єв-град, — отвіща́л єси́ челові́ком, сла́ви от них не і́щуше, Бо́гу же сла́ву поя́: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь зако́н Єва́нгельський тща́вся на себі́ іспо́лнити, ду́шу свою́ єжеча́сно за бли́жняя своя́ полага́вий, помишля́я, я́ко Госпо́дь мні помо́щник і аз воззрю́ на враги́ моя́, рубежи Оте́чествія оборонял єси́, украї́нськиє же лю́діє не престава́ху зва́ти ті та́ко:","Ра́дуйся, зов Госпо́день всім се́рдцем свої́м усли́шавий;","Ра́дуйся, за бли́жнія своя́ живота́ не щадивий.","Ра́дуйся, ві́рою пра́вою неві́рния побеждавий;","Ра́дуйся, ру́ським ду́хом іноплеме́нники ізгонявий.","Ра́дуйся, на по́лі бра́ні Го́спода на вспоможе́ніє призива́вий;","Ра́дуйся, ку́пно с Небе́сними си́лами тьму вра́жию посекавий.","Ра́дуйся, преподо́бне о́тче Іліє́, землі́ Ру́ськия сла́вний засту́пниче."]},{"h":"Кондак 9","ps":["Вся́коє єстество́ челові́ков і А́нгелов диви́шася зіло́, єгда́ ти си́на єдинароднаго, Оте́честву Ру́ському ізміни́вшаго, пощади не дая́, копіє́м закла́л єси́, да не чинить зла лю́дем правосла́вним, ми же трепе́щуще си́ли ві́ри твоєя́ і упова́нія твоєго́ на Бо́га, поє́м: Аллилу́я."]},{"h":"Ікос 9","ps":["Ві́тіії мно́жеством слове́с по́двиги твоя́ восхвали́ша, но кто возмо́жеть все промишле́ніє Бо́жиє над тобо́ю ізрещи́, я́ко во і́мені твоє́м вся мощ і си́ла ду́ха ру́ськаго богатирськаго воплотившися, вся препони вра́жия сокруши́, за то́є потомки твої́ досе́лі тя велича́ють:","Ра́дуйся, хра́брий во́їне Це́ркві воїнствующия;","Ра́дуйся, достосла́вний побіди́телю в Це́ркві торжеству́ющия.","Ра́дуйся, безбоя́зненний одолетелю всіх враг ви́димих і неви́димих;","Ра́дуйся, люби́миче, Господом і людьми́ Єго́ возлю́бленний.","Ра́дуйся, пра́ведний челові́че, не скривий тала́нта Господи́на своєго́;","Ра́дуйся, преподо́бний о́тче, преумноживий сла́ву Бо́га на́шего.","Ра́дуйся, преподо́бне о́тче Іліє́, землі́ Ру́ськия сла́вний засту́пниче."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ сторону родимую не то́кмо от враг інозе́мних, но і от неведимих, єще́ же і ду́шу свою́, зла́то і сребро́ от князе́й дарова́нноє, неімущим расточи́в і на созида́ніє хра́мов употреби́в, во оби́тель і́ночеськую удали́лся єси́, та́мо із глубини́ серде́чния Бо́гу поя́: Аллилу́я."]},{"h":"Ікос 10","ps":["Сті́ни оби́телі святи́я укриша тя, преподо́бне о́тче Іліє́, іді́же в затво́рі печерстем слезьми непреста́нними і моле́ньми всено́щними, за гріхи́ своя́ і кров лю́дськую, во́льні і нево́льні пролитую, умилостивлял єси́ Бо́га, Той же, ви́дя смире́ніє і сокруше́ніє твоє́, вско́рі благода́ть пребо́льшую ті подаде́, я́ко диви́тися бра́тії всей, зовущей:","Ра́дуйся, от во́їна тіле́снаго во во́їна духо́внаго преобрази́вийся;","Ра́дуйся, меч і копіє́ веще́ственния отложи́в, духо́вним мече́м вооружи́вийся.","Ра́дуйся, ору́жіє тлі́нноє оста́вивий, моли́твою непреста́нною врага́ посекавий;","Ра́дуйся, і во бра́ні духо́вній побіди́тель яви́вийся.","Ра́дуйся, да́ра прозорливости пре́жде конця́ сподо́бивийся;","Ра́дуйся, благода́ть чудотворе́ній та́кожде восприя́вий.","Ра́дуйся, преподо́бне о́тче Іліє́, землі́ Ру́ськия сла́вний засту́пниче."]},{"h":"Кондак 11","ps":["Пі́ніє прийми́ ску́дних слове́с і помоли́ся за убо́гія сро́дниці твоя́, і хода́тай нам бу́ди у Бо́га, і визволитель на землі́, я́коже і пре́жде, і не преста́й, мо́лим тя, моли́ти Бо́га за Русь Святу́ю пі́снію: Аллилу́я."]},{"h":"Ікос 11","ps":["Світи́льник от єле́я благода́ті возже́нний, о́тче Іліє́, освіти́ ни́ні нас, во тьмі і мра́кі прозяба́ющих, і воєводой войську ру́ському бу́ди, от полона нече́стія Оте́чествіє свобожда́я і во́їнов в ра́тіх укріпля́я, і ра́зум їм і благоче́стіє от Бо́га іспроси́, да зове́м ті:","Ра́дуйся, безм'ятежне упокоївийся со всі́ми от ві́ка пра́ведними;","Ра́дуйся, ми́рні отошедший к Влади́ці живота́ і сме́рті.","Ра́дуйся, возимевий у Него́ дерзнове́ніє мно́гоє;","Ра́дуйся, за соплеменников свої́х непреста́нні хода́тайствующий.","Ра́дуйся, стерегий досе́лі зе́млю Ру́ськую от нахожде́нія лю́тих;","Ра́дуйся, преподо́бне о́тче Іліє́, землі́ Ру́ськия сла́вний засту́пниче."]},{"h":"Кондак 12","ps":["Благода́тію взращая держа́ву Ру́ськую, Госпо́дь при нача́лі сего́ посла́ тя, Іліє́, своєго́ ратобо́рця, наро́д нов – Бо́жиє стяжа́ніє – лю́діє ру́ськия от клевре́ть сатани́нських ненаві́тни соблюсти́, я́ко нави́кнути правосла́вним, на Бо́га упова́я, пі́ти: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще дія́нія житія́ твоєго́, воздає́м хвале́ніє Вседержи́телю Бо́гу, прему́дре мир устрояющему, я́ко Той Сам Трієдин, та́ко і Русь Трієдину сотвори́, наро́д же правосла́вний, сіє́ разуміва́я, тріє́х богатирей о́браз во охрани́тели себі́ ізбра́, я́ко ті́ї Трієдинстство Бо́жиє прообразу́ють, воєво́ду же їх, Ілію́ Му́ромця, сла́в'яще ві́рнії, вопію́ть:","Ра́дуйся, Тро́йці служи́телю в житії́ і по преставле́нії твоє́м яви́вийся;","Ра́дуйся, я́ко тріє́ пе́рсти руки́ твоєя́, для зна́менія кре́стнаго сложе́нния та́ко досе́лі пребива́ють.","Ра́дуйся, я́ко сим ди́вом невиданним мно́зі сумнящіїся ві́ру пра́вую обріта́ють;","Ра́дуйся, і по представле́нії своє́м чудеса́ твори́ти не престающий.","Ра́дуйся, і по кончи́ні, в смертем тілесі́, Го́спода прославля́ющий;","Ра́дуйся, в нетлі́нії моще́й досе́лі почивающий.","Ра́дуйся, преподо́бне о́тче Іліє́, землі́ Ру́ськия сла́вний засту́пниче."]},{"h":"Кондак 13","ps":["О святи́й о́тче Іліє́, во́їне і монаше, богатирю духо́вний і тіле́сний, ратниче на враги́ ви́димия і неви́димия, защити́ ни́ні Оте́чествіє на́ше – Русь Святу́ю, є́же єсть подно́жіє Престо́лу Госпо́дня, і Це́рков Ру́ськую Правосла́вную заступи́, да пою́ть лю́діє па́м'ять твою́, і Го́споду, дарова́вшему Русі́ засту́пника сицева́го, славосло́віє прино́сять пі́снію: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелов Творе́ць, єгда́ во ра́бії зра́ці на зе́млю снисшел, до тридесятьлетняго во́зраста не явля́л єси́ себ'я́ ми́ру, та́ко і тя, свя́те Іліє́, сподо́би до того́жде во́зрасту нікому́ неведомим би́ти і недвижимим тіле́сні, да по́сліжде послу́жиши Го́споду і лю́дем Єго́ со всім усе́рдієм і ре́вностію, є́же ми восхваля́єм:","Ра́дуйся, промишле́нієм Бо́жиїм три́десять літ прему́дро храни́мий;","Ра́дуйся, от рожде́нія ізбра́нний, да являться на тебі́ діла́ Госпо́дня.","Ра́дуйся, чрез неду́г свой собла́знов ю́ности мно́гих ізбегнувий;","Ра́дуйся, ду́шу чи́сту чрез страда́нія соблюди́й.","Ра́дуйся, си́ми на прия́тіє благода́ті ю угото́вавий;","Ра́дуйся, болі́зні, я́ко дар Бо́жий, с покорностью терпі́вий,","Ра́дуйся, преподо́бне о́тче Іліє́, землі́ Ру́ськия сла́вний засту́пниче."]},{"h":"Кондак 1","ps":["Воєво́ді сил землі́ Ру́ськия, во́їну Царя́ Христа́ і засту́пнику Русі́ Свято́й, сла́вному во бра́ніх і неодолимому в ра́тіх, ди́вному богатирю Ілії́ Муромцю піснь хвале́бную воспоє́м, да засту́пить і ни́ні нас, зову́щих:","Ра́дуйся, преподо́бне о́тче Іліє́, землі́ Ру́ськия сла́вний засту́пниче."]},{"h":"Молитва","ps":["О святи́й преподо́бний о́тче Іліє́! Русі́ Свято́й засту́пниче, могучий ратобо́рче, во́їне духо́вний і тіле́сний єй яви́вийся, в житії́ своє́м бла́гу наро́да Ру́ськаго і прославле́нію Бо́га Христия́нськаго ві́рно послужи́вий, і по преставле́нії своє́м престательства своєго́ о нас не оста́вивий, іспроси́, свя́те, у Всеми́лостиваго Го́спода Оте́честву на́шему царя́, мир і благоде́нствіє, це́ркві благоустроє́ніє, лю́дем правосла́вним от нечести́вих ізбавле́ніє, во́їном ру́ським в ра́тіх побі́ду і на враго́в, замишляющих зла́я Це́ркві і Оте́честву правосла́вному, одолі́ніє, всіх же нас заступи́, і єще́ про́сим тя, свя́тче Бо́жий, ра́зум нам от Бо́га ниспосли́, да позна́єм согріше́нія на́ша, і си́лу духо́вную, да покаємся во грехах на́ших, і крі́пость тіле́сную, да возмощи́ нам житіє́ іспра́вити і Русь Святу́ю возродити, і в Ца́рствіє Небе́сноє із нея́ прейти́, да та́мо с тобо́ю і всі́ми святи́ми сподо́битися непреста́нні восхваля́ти в Тро́йці сла́вимаго Бо́га Отця́ і Си́на і Свята́го Ду́ха во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 8","ps":["Посто́м ду́шу твою́ просвіти́л єси́, моли́твами непреста́нними се́рдце твоє́ сосу́д Ду́ха Свята́го соді́лал єси́, преподо́бне о́тче наш Іліє́, тім же вся вра́жія ополче́нія крі́пко посрами́л єси́ і, я́ко побідоно́сець і́стинний, воздая́нія получи́л єси́ от Христа́ Бо́га, тому́ помоли́ся о душа́х на́ших."]},{"h":"Кондак, глас 8","ps":["Христо́вою любо́вію уязви́в ду́шу, преподо́бне о́тче наш Іліє́, в пеще́рнім мра́ці світ спасе́нія обрі́л єси́ і, я́ко ча́до ізбра́нноє вели́ких отце́в Пече́рських Анто́нія і Феодо́сія, вку́пі с ни́ми оби́тель ра́йськую унаслі́довал єси́, отону́дуже призира́й ни́ні на оби́тель земну́ю, в ней же подвиза́лся єси́, і моли́ся о чту́щих па́м'ять твою́, да зове́м ті: ра́дуйся, Іліє́, моли́твенниче о душа́х на́ших."]},{"h":"Величання","ps":["Ублажа́єм тя, / преподо́бне о́тче Іліє́, / і чтим святу́ю па́м'ять твою́, / наста́вниче мона́хов // і собесі́дниче А́нгелов."]}],"notes":[]},{"u":"Акафіст преподобному Іоні Київському","e":"Akathist to our Venerable Father Jonah of Kyiv","secs":[{"h":"Кондак 1","ps":["Ізбра́нний уго́дниче Христо́в і Чудотво́рче, преподо́бне о́тче Іо́но, возсія́вий ми́рові, я́ко звізда́ богосві́тлая, житія́ твоєго́ добро́тою і мно́жеством чудотворе́ній, восхваля́єм тя любо́вію в пі́сніх духо́вних: ти же, я́ко імі́яй дерзнове́ніє ко Го́споду, моли́твами твої́ми от вся́ких нас бід свободи́, да зове́м ті:","Ра́дуйся, преподо́бне о́тче наш Іо́но, гра́да Ки́єва похвало́ і украше́ніє."]},{"h":"Ікос 1","ps":["А́нгельський нрав імі́л єси́, о́тче преподо́бне, і я́ко безпло́тний, непоро́чно житіє́ соверши́л єси́ на землі́, ди́вний о́браз соверше́нства духо́внаго нам оста́вив, да подража́єм доброді́телем твої́м, і зове́м ті си́це:","Ра́дуйся, цві́те благоуха́нний до́браго воспита́нія;","ра́дуйся, сосу́де Боже́ственнаго ізбра́нія.","Ра́дуйся, я́ко любе́зная і кра́сная ми́ра сего́ презрі́л єси́;","ра́дуйся, я́ко Небе́сних і нетлі́нних, жела́нієм вожделі́л єси́.","Ра́дуйся, во́лею тве́рдою во́лі своєя́ отреки́йся;","ра́дуйся, отсіче́нієм страсте́й угоди́вий Бо́гу і спаси́йся.","Ра́дуйся, преподо́бне о́тче наш Іо́но, гра́да Ки́єва похвало́ і украше́ніє."]},{"h":"Кондак 2","ps":["Ви́дя Госпо́дь ду́шу твою́, я́ко ни́ву благовозді́ланную к плодоно́сію духо́вному, от ю́ности к іска́нію єди́наго на потре́бу, напра́ви твой по́мисл, преподо́бне, ті́мже любве́ ра́ди Христо́ви, роди́телей твої́х і дом оте́чеський оста́вил єси́, і вся́каго пристра́стія су́єтнаго свободи́вся, прите́кл єси́ в пу́стинь Саро́вськую под крилі́ Серафи́ма преподо́бнаго, на по́двиги і́ночеськия, зови́й спаса́ющему тя Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зумом богопросвіще́нним пости́гл єси́ суєту́ ми́ра сего́ і непостоя́нство, в нем же ра́дость сміня́ється ско́рбію, благополу́чіє наві́тується неча́янними біда́ми. Ті́мже ві́чних нетлі́нних благ возжелі́л єси́, о́тче преподо́бне, і сія́ взиска́ти потща́лся єси́ отрече́нієм мирськи́х благ, і во́льною нището́ю, подвига́я нас зва́ти тебі́:","Ра́дуйся, ті́сний путь спасе́нія от ю́ности возлюби́вий;","ра́дуйся, яре́м Госпо́день на ви́ю свою́ возложи́вий.","Ра́дуйся, свяще́нними обі́ти во́лю свою́ связа́вий;","ра́дуйся, себе́ і весь живо́т свой Го́сподеві преда́вий.","Ра́дуйся, коєму́ждо во бла́го усе́рдний служи́телю;","ра́дуйся, боля́щих і немощни́х упокої́телю.","Ра́дуйся, преподо́бне о́тче наш Іо́но, гра́да Ки́єва похвало́ і украше́ніє."]},{"h":"Кондак 3","ps":["Си́лою Всеви́шняго осіне́нний і укріпля́ємий, в і́ночестім постриже́нії влас глави́ твоєя́, все плотсько́є мудрова́ніє отложи́л єси́, преподо́бне, і я́ко во́їн благоїску́сний, оде́жду і́ночеськую в броню́ спасе́нія стяжа́в, і непобіди́мим ору́жієм Креста́ Христо́ва вооружи́вся, крі́пко ра́товал єси́ проти́ву врага́ неви́димаго дия́вола, смире́нієм глубо́ким побіжда́я єго́ вознесе́нную горди́ню, і ви́ну вопія́ ко Го́споду: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я слез істо́чник ізоби́льний, уго́дниче Бо́жий, і умиле́нія ве́лію благода́ть, хліб твой слеза́ми ороша́л єси́, і питіє́ пла́чем растворя́л, от преізби́тка жела́нія боже́ственнаго і любве́ ко Го́споду. Ті́мже і ми ублажа́єм тя зва́нії си́ми:","Ра́дуйся, по́мисли плотські́я си́лою моли́тви прогоня́яй;","ра́дуйся, сомня́щихся во ві́рі сло́вом Бо́жиїм утвержда́яй.","Ра́дуйся, лише́нії тіле́сними мно́га бла́га духо́вная собра́вий;","ра́дуйся, нището́ю дарова́нія небе́сная стяжа́вий.","Ра́дуйся, молча́нія ізря́дний храни́телю;","ра́дуйся, стро́гий уста́вов і́ночеських блюсти́телю.","Ра́дуйся, преподо́бне о́тче наш Іо́но, гра́да Ки́єва похвало́ і украше́ніє."]},{"h":"Кондак 4","ps":["Бу́ря іскуше́ній і устремле́ній дия́вольських не возмо́же поколеба́ти хра́мини твоєя́ душе́вния, преподо́бне о́тче, основа́нна бо бі на тве́рдом ка́мені ві́ри во Христа́, і храни́ма трезве́нієм і моли́твами непреста́нними, і́ми же ви́ну противобо́рствовал єси́ врагу́ спасе́нія челові́чеськаго, і непреткнове́нно восходи́л єси́ по стезя́м доброді́телей к соверше́нству духо́вному в мі́ру во́зраста Христо́ва, воспіва́я Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шаша преподо́бне о́тче Іо́но, бли́жнії і да́льнії ангелоподо́бноє твоє́ житіє́, і благода́ті чуде́с струю́ ви́ну теку́щую, я́ко моли́твою твоє́ю прокаже́ннії очища́ються, сліпі́ї прозира́ють, хромі́ї хо́дять і разнообра́зних неду́г с ві́рою притека́ющії, а́ще і інові́рнії, здра́віє улуча́ють, сих ізба́вльшеся вопія́ху к тебі́ такова́я:","Ра́дуйся, боля́щим, я́ко бра́тії Христо́вой, служи́телю;","ра́дуйся, висо́ких по́двигов житія́ христия́нськаго ревни́телю.","Ра́дуйся, новонача́льних іску́сний руководи́телю;","ра́дуйся, неізмі́нноє пра́вило поста́ і смире́нія.","Ра́дуйся, умира́ющия возставля́яй на покая́ніє;","ра́дуйся, всім внуша́яй Жи́зні Ві́чния взиска́ніє.","Ра́дуйся, преподо́бне о́тче наш Іо́но, гра́да Ки́єва похвало́ і украше́ніє."]},{"h":"Кондак 5","ps":["Боготе́чная пресві́тлая звізда́ яви́лся єси́, преподо́бне о́тче наш Іо́но, не́бо церко́вноє украша́яй і всіх блужда́ющих по мо́рю стра́стнаго житія́ сего́ да́нною тебі́ от Со́лнця Пра́вди Христа́ Ісу́са, і́стиннаго Бо́га, благода́тію озаря́яй, мрак печа́лей і мглу вся́ких неду́г і скорбе́й прогоня́яй, наставля́єши всіх к тебі́ с ві́рою притека́ющих на путь спасе́нія, к ві́чному Небе́сному Оте́чествію веду́щий, пою́щих Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше а́нгельстії чи́нове равноа́нгельноє житіє́ твоє́ о́тче богоблаже́нне, смире́нія твоєго́ глубину́, моли́тви неотсту́пность, воздержа́нія тве́рдость і ве́лію ре́вность ду́ха твоєго́ о чистоті́, удиви́шася і просла́виша Человіколю́бця Бо́га, укріпля́ющаго немощно́є єстество́ челові́чеськоє. Ми же ублажа́єм тя і зове́м:","Ра́дуйся, миря́ном наста́вниче жи́зні богоуго́дния;","ра́дуйся, основа́телю оби́телі благопло́дния.","Ра́дуйся, я́ко блага́я начина́нія твоя́ Христо́с благослови́;","ра́дуйся, я́ко сотру́дника тебі́ в лиці́ держа́внаго яви́.","Ра́дуйся, о́бщеє житіє́ мона́шествующих основа́вий;","ра́дуйся, тім всеору́жіє благоче́стія їм пода́вий.","Ра́дуйся, преподо́бне о́тче наш Іо́но, гра́да Ки́єва похвало́ і украше́ніє."]},{"h":"Кондак 6","ps":["Пропові́дуєть мир весь правосла́вний тебі́, преподо́бне о́тче наш Іо́но, де́монов прогони́теля, болі́зней ісціли́теля і іни́х мно́гих чуде́с соверши́теля. Ми же, Бо́га о тебі́ прославля́юще, вопіє́м Єму́: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́л єси́ на гора́х Зверине́цьких богосві́тлоє світи́ло, і на спасе́нія стезю́ наста́вил єси́ мно́гі ду́ші челові́чеськія: яви́ бо тя Христо́с наста́вника і учи́теля і́ноком пустиннолюби́вим, і́же стека́хуся к тебі́, я́ко о́вці к па́стирю, могу́щу упасти́ їх на па́жити живоно́сній. Ті́мже, я́ко сотвори́вшаго і научи́вшаго, честву́єм тя си́ми похва́льними словеси́:","Ра́дуйся, о́бщими труди́ пра́здних по́мислов шата́нія упраздни́вий;","ра́дуйся, ті́ми я́ко броне́ю, страсте́й разжже́нния стрі́ли отрази́вий.","Ра́дуйся, всели́вий во оби́телі дух о́бщаго воздержа́нія;","ра́дуйся, потреби́вий в ней пле́вели любостяжа́нія.","Ра́дуйся, бо́дрствованію духо́вному мно́гі і́ноки научи́вий;","ра́дуйся, до конця́ житія́ пе́рвий в тружда́ющихся би́вий.","Ра́дуйся, преподо́бне о́тче наш Іо́но, гра́да Ки́єва похвало́ і украше́ніє."]},{"h":"Кондак 7","ps":["Хотя́ Человіколюби́вий Госпо́дь просла́вити мі́сто сіє́, я́ко виногра́д по́двигов твої́х, о́тче, посла́ Пресвяту́ю Влади́чицю на́шу Богоро́дицю благовісти́ти тебі́, я́ко бу́деть в сто́льном гра́де Ки́єве оби́тель і́ноком во спасе́ніє, украше́нная хра́мом во і́м'я Святи́я Тро́йці. Ти же явле́нієм Пречи́стия просвіще́н, с ра́достним тре́петом внима́л єси́ благові́стію небе́сному, зови́й во смире́нії ду́ха Влади́ці А́нгелов і челові́ков: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́воє зна́меніє благоволе́нія Бо́жия дарова́ся тебі́, преподо́бне, єгда́ безмо́лвствующу ті во Ви́дубицьком монастирі́, в нощі́ світ ве́лій облиста́ ве́домую ті ке́ллію, і Сама́ Пречи́стая с со́нмом Святи́х предста́ пред тобо́ю, мир тебі́ да́руя і повеліва́я, да устро́їши та́мо оби́тель і́ночеськую, і в ней храм во і́м'я Святи́я Тро́йці. Див'я́ся у́бо сему́ пречу́дному трикра́тному Богома́тернему тро́їчеському явле́нію, зове́м ті:","Ра́дуйся, му́дре предначерта́вий оби́тель но́ву;","ра́дуйся, поревнова́вий нищетолю́бному житію́ Христо́ву.","Ра́дуйся, святи́я хра́ми во оби́телі созда́вий;","ра́дуйся, мног собо́р мона́шествующих собра́вий.","Ра́дуйся, я́ко труд твой Сви́ше благослови́ся;","ра́дуйся, я́ко свято́є жела́ніє се́рдця твоєго́ соверши́ся.","Ра́дуйся, преподо́бне о́тче наш Іо́но, гра́да Ки́єва похвало́ і украше́ніє."]},{"h":"Кондак 8","ps":["Страннолі́пно яви́ся ті на возду́сі Ма́тер Бо́жия со апо́столи і му́ченики і преподо́бними і про́чими святи́ми, указу́яй мі́сто, на не́мже храм во і́м'я Живонача́льния Тро́йці і оби́тель но́ву імі́л єси́ воздви́гнути на горі́ Зверине́цтей, преподо́бне о́тче, єго́же Бо́жиїм поспіше́нієм соверши́в і освяти́в, со ученики́ твої́ми немо́лчния хвали́ возсила́л єси́ в нем Го́сподеві, зови́й: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь єси́ любо́в неоскудіва́ющая і по́двига зерца́ло нетускне́ющеє бил єси́, преподо́бне Іо́но. Ви́дяще же ре́вностноє по Бо́зі і жесто́коє житіє́ твоє́ і бра́тії, непреста́нно в труді́х і поще́нії подвиза́ющихся і ходя́щих в ру́бищних і худи́х оде́ждах, ні́циї от і́нок і вся́каго чи́на мирськи́х люде́й і князе́й людськи́х не то́чію сих не отвраща́хуся, но па́че ре́вностію духо́вною горя́ще і во оби́телі ку́пно с ни́ми подвиза́тися жела́юще, приноша́ху ту імі́нія своя́ на по́льзу о́бщую; ті́мже зда́телю тоя́ возглаша́єм та́ко:","Ра́дуйся, я́ко во оби́телі твоє́й мно́зі ду́ші своя́ спасо́ша;","ра́дуйся, я́ко із нея́ пастиренача́льници ізидо́ша.","Ра́дуйся, благочести́вих отра́до і утіше́ніє;","ра́дуйся, коле́блющихся во ві́рі тве́рдоє огражде́ніє.","Ра́дуйся, отчаява́ющихся утвержда́яй во упова́нії;","ра́дуйся, просвіти́вий мно́гих Святи́ми писа́нії.","Ра́дуйся, преподо́бне о́тче наш Іо́но, гра́да Ки́єва похвало́ і украше́ніє."]},{"h":"Кондак 9","ps":["Вся́коє єстество́ а́нгельськоє і подви́жников мно́жество удиви́шася смире́нію і человіколю́бію твоєму́, о́тче наш Іо́но, єгда́, архимандри́тства Межиго́рськаго послуша́ніє восприя́в, Феодо́сію ігу́мену Пече́рському, я́ко житі́й о́бщих на Русі́ учреди́телю уподо́бился єси́. І о бра́тії святи́я оби́телі сея́, я́ко о ча́діх Бо́жиїх, попече́ніє не оста́вивий. Бо́гу, лю́б'ящему вся́коє Своє́ созда́ніє, о тіх взива́л єси́: Го́споди, посли́ Ду́ха Свята́го Твоєго́ і уті́ши ско́рбния ду́ші рабо́в Твої́х сих. Та́ко бо во вся́ком послуша́нії смиренному́дрія красоту́ показу́я, непреста́нно взива́л єси́ Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Вити́йство челові́чеськоє не довлі́єть ізрещи́ оби́ліє ра́дости духо́вния, є́юже преісполня́лся єси́, о́тче богоно́сне, єгда́ во вре́м'я моли́тви твоєя́ нощни́я, явля́шеся ті Пресвята́я Богоро́диця с ли́ками чино́в подви́жничеських, і обітова́нії непрело́жними ду́шу твою́ возвесели́, я́ко при́сная Засту́пниця оби́телі твоєя́ бу́деть, снабдіва́ющи і покрива́ющи ю по вся дні. Ті́мже і ми сія́ ра́достная тебі́ прино́сим глаго́ли:","Ра́дуйся, ше́ствовавий путе́м тру́дним і ті́сним;","ра́дуйся, возводя́й други́х к Оби́телем Небе́сним.","Ра́дуйся, наде́ждо сві́тлая в ну́жді і обстоя́нії су́щих;","ра́дуйся, покрови́телю си́рих і кро́ва неіму́щих.","Ра́дуйся, гла́дом погиба́ющих пита́телю;","ра́дуйся, жела́ємих благ прише́дшим к тебі́ пода́телю.","Ра́дуйся, преподо́бне о́тче наш Іо́но, гра́да Ки́єва похвало́ і украше́ніє."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ ду́ші учени́к твої́х, оте́чеськи назида́л єси́ їх, богому́дре, о́ваго ді́йственним сло́вом, о́ваго приме́ром житія́ твоєго́, с любо́вію облича́я і увіщава́я їх преуспіва́ти во благоче́стії і чистоті́: найпа́че же пред кончи́ною твоє́ю, вся ко спасе́нію душе́вному благопотре́бная запові́дал єси́ їм, і научи́л єси́ їх в моли́твах бо́дрствовати, і немо́лчно пі́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ заступле́нія би́ша моли́тви твоя́, чудотво́рче святи́й, всім с ві́рою к тебі́ притека́ющим во вся́кой ско́рби, і́бо чистоти́ ра́ди твоєя́ серде́чния, си́ла духо́вная от Бо́га тебе́ дарова́ся боля́щих ісціля́ти, бе́дствующим помога́ти, бу́дущая прориця́ти, я́ко сла́вити бли́жнім і да́льним вели́чія Бо́жія, в тебі́ явле́нная, і зва́ти тебі́ си́це:","Ра́дуйся, ми́лости істо́чниче неістощи́мий;","ра́дуйся, скорб'я́щих уті́шителю незри́мий.","Ра́дуйся, послі́дняя твоя́ взаї́м Бо́гові да́вий;","ра́дуйся, до́брим раче́нієм і расточе́нієм су́щих бога́тая собра́вий.","Ра́дуйся, досточу́дний о́бразе терпі́нія;","ра́дуйся, наста́вниче неле́стнаго благогові́нія.","Ра́дуйся, преподо́бне о́тче наш Іо́но, гра́да Ки́єва похвало́ і украше́ніє."]},{"h":"Кондак 11","ps":["Пі́ніє всеумиле́нноє прине́сл єси́ Пресвяті́й Тро́йце во вре́м'я кончи́ни твоєя́, преподо́бне, і моли́тві су́щей на усті́х твої́х. Преда́л єси́ святу́ю ду́шу твою́ в ру́ці Жива́го Бо́га, Єго́же от ю́ности возлюби́л єси́, і єму́же до ста́рости масти́тия рабо́тал єси́ нелицемі́рно, ті́мже со упова́нієм благи́м ра́достно преше́л єси́ к оби́телем небе́сним, со А́нгельськими ли́ки пі́ти Трийпоста́сному Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Ми́рную кончи́ну твою́ ви́дівше твої́ ученици́, вели́кий уго́дниче Бо́жий, скорб разлуче́нія с тобо́ю утіше́нієм благода́тним раствори́ша. В упова́нії всеси́льнаго предста́тельства твоєго́ го́ре у престо́ла Бо́жия, іді́же сли́шиши с любо́вію тебі́ зову́щих:","Ра́дуйся, благопотре́бне во оте́чествії твоє́м возсія́вий;","ра́дуйся, ві́ру в ді́ліх житія́ твоєго́ показа́вий.","Ра́дуйся, разу́мних і препро́стих благоїску́сний учи́телю;","ра́дуйся, чистоти́ душе́вния і тіле́сния усе́рдний храни́телю.","Ра́дуйся, вну́треннею Креста́ Христо́ва красото́ю восхище́нний;","ра́дуйся, си́лою сви́ше на труд Крестоноше́нія облече́нний.","Ра́дуйся, преподо́бне о́тче наш Іо́но, гра́да Ки́єва похвало́ і украше́ніє."]},{"h":"Кондак 12","ps":["Благода́ті прича́стна яви́ся свяще́нная ра́ка, тобо́ю сами́м сооруже́нная, содержа́щая многоціле́бния мо́щі твоя́, чудотво́рче святи́й, ї́хже по лі́тіх мно́зіх яви́ Госпо́дь во скле́пі церко́внім нетлі́нними, і па́ки по надруга́нію безбо́жник сокри́, і па́ки яви́ в ні́дріх землі́ невреди́ми, ісціле́нія неоску́дно істоча́ющия, і всяк неду́г врачу́ющия си́лою Бо́га, ди́внаго во святи́х Свої́х, ди́вно же просла́вльшаго тя на небесі́ і на землі́, Єму́же воспіва́єм: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще ра́достную піснь хвали́ і благодаре́нія Человіколю́бцю Бо́гу, просла́вльшему тя в землі́ Ру́сстій чудотво́рця ди́внаго і ми́лостиваго, мо́лим тя, преподо́бне о́тче наш Іо́но: бу́ди хода́тай к Нему́, і моли́твенник при́сний о нас, зову́щих ті:","Ра́дуйся, стріла́ми вра́жиїх наві́т неуязви́мий;","ра́дуйся, спаса́ємих вождю́ непобіди́мий.","Ра́дуйся, і по отше́ствії оби́тель твою́ соблюда́яй;","ра́дуйся, моля́щимся благопотре́бная подава́яй.","Ра́дуйся, от Го́спода віне́ць пра́вди восприя́вий;","ра́дуйся, сла́вою чудотворе́ній просія́вий.","Ра́дуйся, преподо́бне о́тче наш Іо́но, гра́да Ки́єва похвало́ і украше́ніє."]},{"h":"Кондак 13","ps":["О вели́кий і пресла́вний чудотво́рче, преподо́бне о́тче наш Іо́но! Ми́лостиво прия́в сіє́ ма́лоє моле́ніє на́ше, моли́твами твої́ми сохрани́ нас от неду́гов душе́вних і тіле́сних в жи́зні сей, і от гряду́щих муче́ній ві́чних ізба́ви, і сподо́би нас вку́пі с тобо́ю во Ца́рствії Небе́снім ви́ну пі́ти Бо́гу: Аллилу́я, Аллилу́я, Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгельський нрав імі́л єси́, о́тче преподо́бне, і я́ко безпло́тний, непоро́чно житіє́ соверши́л єси́ на землі́, ди́вний о́браз соверше́нства духо́внаго нам оста́вив, да подража́єм доброді́телем твої́м, і зове́м ті си́це:","Ра́дуйся, цві́те благоуха́нний до́браго воспита́нія;","ра́дуйся, сосу́де Боже́ственнаго ізбра́нія.","Ра́дуйся, я́ко любе́зная і кра́сная ми́ра сего́ презрі́л єси́;","ра́дуйся, я́ко Небе́сних і нетлі́нних, жела́нієм вожделі́л єси́.","Ра́дуйся, во́лею тве́рдою во́лі своєя́ отреки́йся;","ра́дуйся, отсіче́нієм страсте́й угоди́вий Бо́гу і спаси́йся.","Ра́дуйся, преподо́бне о́тче наш Іо́но, гра́да Ки́єва похвало́ і украше́ніє."]},{"h":"Кондак 1","ps":["Ізбра́нний уго́дниче Христо́в і Чудотво́рче, преподо́бне о́тче Іо́но, возсія́вий ми́рові, я́ко звізда́ богосві́тлая, житія́ твоєго́ добро́тою і мно́жеством чудотворе́ній, восхваля́єм тя любо́вію в пі́сніх духо́вних: ти же, я́ко імі́яй дерзнове́ніє ко Го́споду, моли́твами твої́ми от вся́ких нас бід свободи́, да зове́м ті:","Ра́дуйся, преподо́бне о́тче наш Іо́но, гра́да Ки́єва похвало́ і украше́ніє."]},{"h":"Молитва","ps":["О свяще́нная главо́, а́нгеле земни́й і челові́че небе́сний, преподо́бне і богоно́сне о́тче наш Іо́но, ізря́дний уго́дниче Пресвяти́я і Єдиносу́щния Тро́йці, явля́ющий мно́гія ми́лости живу́щим во святі́й оби́телі твоє́й, і всім, с ві́рою і любо́вію притека́ющим к тебі́. Іспроси́ нам вся благопотре́бная к житію́ сему́ вре́менному, і ну́жная к ві́чному спасе́нію на́шему. Посо́бствуй предста́тельством твої́м, уго́дниче Бо́жий, всім нам, к моще́м твої́м святи́м припа́дающим, на враги́ ви́димия і неви́димия одолі́ніє, да в ми́рі глубо́ці пребу́деть Свята́я Правосла́вная Це́рков Христо́ва, і в благоустроє́нії зи́ждеться оби́тель, ю́же ти основа́, во вся́ком благоче́стії неруши́мо. Бу́ди всім нам, чудотво́рче святи́й, помо́щник ско́рий во вся́кой ско́рби і обстоя́нії. Найпа́че же в час кончи́ни на́шея яви́ся нам засту́пник благосе́рдний, да не пре́дани бу́дем на мита́рствах возду́шних вла́сті зло́бнаго мироде́ржця, но да сподо́бимся непреткнове́ннаго восхо́да в Ца́рствіє Небе́сноє. Єй, о́тче, моли́твенниче наш при́сний. Не посрами́ упова́нія на́шего, не пре́зри смире́нная моле́нія на́ша, і предста́тельствуй за нас пред престо́лом Живонача́льния Тро́йці, да сподо́бимся вку́пі с тобо́ю і со всі́ми святи́ми, ми недосто́йнії, в селе́ніїх ра́йських сла́вити вели́чіє, благода́ть і ми́лость Єди́наго в Тро́йці Бо́га, Отця́ і Си́на і Свята́го Ду́ха, во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Я́ко лучеза́рноє со́лнце / от коне́ць землі́ возсія́вшеє, / яви́лся єси́ напослі́док дній, / тезоімени́тому проро́ку подо́б'яся во є́же воздви́гнути лю́ди к покая́нію. / Ті́мже і Сама́ Пречи́стая с со́нмом святи́х тебі́ мно́гажди яви́шася, / Єя́же повелі́нієм создана́ бисть оби́тель во і́м'я Живонача́льния Тро́йці. / К Не́йже імі́я дерзнове́ніє, / моли́, преподо́бне о́тче наш Іо́но, // пода́ти нам ми́лость і оставле́ніє гріхо́во в день су́дний."]},{"h":"Кондак, глас 2","ps":["Чистото́ю душе́вною боже́ственно вооружи́вся, / і непреста́нния моли́тви я́ко копіє́ вручи́в крі́пко, / пробо́л єси́ бісо́вськая ополче́нія Іо́но о́тче наш. // Моли́ непреста́нно о всіх нас."]},{"h":"Величання","ps":["Ублажа́єм тя, / преподо́бне о́тче Іо́но, / і чтим святу́ю па́м'ять твою́, / наста́вниче мона́хов // і собесі́дниче А́нгелов."]}],"notes":[]},{"u":"Акафіст святій рівноапостольній великій княгині Ользі","e":"Akathist to the Holy Equal-to-the-Apostles Grand Princess Olga","secs":[{"h":"Кондак 1","ps":["Первоізбранней от всего́ украї́нськаго ро́да, сла́вній і равноапо́стольній уго́днице Бо́жієй О́льгі соста́вим похвалу́, я́ко заре́, во тьмі ідолопоклоненія сві́том ві́ри возсія́вшей і путь ко Христу́ всім украї́нцям показавшей. Ти же, я́ко іму́щая дерзнове́ніє к просла́вльшему тя Го́споду, огражда́й нас от вся́ких бід моли́твами твої́ми, да зове́м ті:","Ра́дуйся, свята́я равноапо́стольная княги́не О́льго богому́драя."]},{"h":"Ікос 1","ps":["А́нгелов і челові́ков Творе́ць, времена́ і лі́та во Своє́й вла́сті положи́вий і судьби́ царств і наро́дов по Своє́й во́лі управля́яй, єгда́ восхоті́ род украї́нський Святи́м Креще́нієм просвіти́ти, тогда́, ви́дя благо́є ізволе́ніє се́рдця твоєго́, призва́ тя пе́рвіє в позна́ніє Себі́, да бу́деши всім украї́нцям о́браз і наста́вниця в христия́нстій ві́рі. Сего́ ра́ди восхваля́єм тя си́це:","Ра́дуйся, украї́нськаго небесе́ у́тренняя звіздо́, от Первозва́ннаго Апо́стола на гора́х Ки́євських предвозвіще́нная;","ра́дуйся, заре́, во мра́ці неві́дінія сві́тло возблиставшая.","Ра́дуйся, до́брая лозо́ виногра́да Христо́ва, от ди́вія язи́чеськаго ко́рене прозя́бшая;","ра́дуйся, пречу́дная лі́торасле, із нея́же ве́ліє правові́рія дре́во на землі́ на́шей возрасте́.","Ра́дуйся, первоучительнице і просвіти́тельнице на́ша;","ра́дуйся, я́ко тобо́ю позна́хом поклоня́тися в Тро́йці Творцю́.","Ра́дуйся, я́ко тебе́ ра́ди Пресвято́є І́м'я Госпо́днє от всіх украї́нців прославля́ється;","ра́дуйся, я́ко і твоє́ пресла́вноє і́м'я вку́пі с равноапо́стольним Влади́миром во всіх преді́ліх ми́ра восхваля́ється.","Ра́дуйся, страни́ на́шея Украї́нськия духо́вноє сокро́вище;","ра́дуйся, всея́ Христо́ви Це́ркве пресла́вноє украше́ніє.","Ра́дуйся, градо́в Ки́єва і Пско́ва ізря́дная добро́то;","ра́дуйся, лю́дем на́шим на враги́ блага́я помо́щнице.","Ра́дуйся, свята́я равноапо́стольная княги́не О́льго богому́драя."]},{"h":"Кондак 2","ps":["Ви́дяще тя, свята́я О́льго, я́ко крин в те́рнії прозя́бший: ти бо а́ще і в ро́ді язи́честім рожде́на єси́, оба́че зако́н Бо́жий в се́рдці твоє́м напи́сан всегда́ імі́ла єси́ і целому́дріє твоє́ я́ко зі́ницю о́ка блюла єси́; благода́рно поє́м ди́вному во святи́х Свої́х Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зумом твої́м вся до́брі ві́дящи, позна́ла єси́, богому́драя О́льго, я́ко і́доли, рука́ма человечеськима сотвореннії, не суть бо́зі; ті́мже, отве́ргши ти́я, потща́лася єси́ позна́ти Бо́га і́стиннаго. Сего́ ра́ди, похваля́юще сицево́є твоє́ благоразу́міє, вопіє́м ті си́це:","Ра́дуйся, до́брая же́но, пе́рвіє всіх заблужде́ніє украї́нців позна́вшая і тщету́ ідолопоклоненія разумевшая;","ра́дуйся, і́стиннаго богопозна́нія і пра́вия ві́ри усе́рдно іска́вшая.","Ра́дуйся, єще́ не ві́дущи і́стиннаго Бо́га, я́коже Корни́лій со́тник, до́брими ді́ли Тому́ угождавшая;","ра́дуйся, пре́жде разумі́нія зако́на Бо́жия по зако́ну со́вісти пра́ведно жившая.","Ра́дуйся, пре́жде прия́тія христия́нськия ві́ри діла́, христия́ном подоба́ющая, творившая;","ра́дуйся, прему́дростію от Бо́га одаренная.","Ра́дуйся, держа́ву твою́ от наше́ствія супоста́ть му́жественно защити́вшая;","ра́дуйся, в подчине́нних ті лю́діх суди́ пра́ведния творившая.","Ра́дуйся, царственною сла́вою на землі́ і на Небесі́ почтенная;","ра́дуйся, я́ко равноапо́стольная от Бо́га просла́вленная.","Ра́дуйся, свята́я равноапо́стольная княги́не О́льго богому́драя."]},{"h":"Кондак 3","ps":["Си́лою благода́ті Бо́жієй дви́жима, потща́лася єси́, богому́драя О́льго, дости́гнути Царграда, іді́же зря́щи красоту́ церко́внаго благолі́пія і послушающи уче́нія слове́с Боже́ственних, распалалася єси́ всім се́рдцем твої́м в любо́в Христо́ву, благода́рственно вопію́щи Єму́: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́щи се́рдце я́ко до́брую зе́млю, удо́б восприя́ла єси́, О́льго, сі́м'я святи́я ві́ри, позна́вши Христа́ Бо́га і́стиннаго. Ті́мже і креще́ніє свято́є прия́ла єси́ от ру́ку патріа́рха Царграда, і́же і предрече́ ті, я́ко отнині блажи́ти тя і́муть украї́нськії си́нове. Іспо́лнити у́бо хотя́ще прорече́ніє сіє́, взива́єм ті си́це:","Ра́дуйся, тьму ідолослуже́нія оста́вльшая;","ра́дуйся, світ богопозна́нія взискавшая.","Ра́дуйся, безконе́чния па́губи ві́рою ізбежавшая;","ра́дуйся, жизнь ві́чную во Христі́ стяжа́вшая.","Ра́дуйся, в купі́лі свята́го креще́нія от скве́рни гріхо́вния омившаяся;","ра́дуйся, благода́тію Свята́го Ду́ха духо́вно роди́вшаяся.","Ра́дуйся, разу́мная го́рлице, от когтей душепа́губнаго вра́на ізлетевшая;","ра́дуйся, под крилі́ Орла́ Небе́снаго прилетевшая.","Ра́дуйся, мно́жество душ креще́нієм с собо́ю ко Христу́ приве́дшая;","ра́дуйся, сего́ ра́ди сугу́боє воздая́ніє от Бо́га получившая.","Ра́дуйся, с ві́рою несумні́нною приходя́щих сві́том от честни́х твої́х моще́й осіява́ющая;","ра́дуйся, душа́м і тілесе́м тіх, я́же на по́льзу, подава́ющая.","Ра́дуйся, свята́я равноапо́стольная княги́не О́льго богому́драя."]},{"h":"Кондак 4","ps":["Ка́ко не диві́мся благоразу́мію твоєму́, О́льго преблаже́нная, і́бо ти предложе́ніє царя́ е́ллинов о бра́ці с ним разу́мно отве́ргла єси́, ре́кши тому́: не бра́ка ра́ди прийдо́х сі́мо і не соцарствованія ра́ди с тобо́ю, но да уневещуся Креще́нієм Безсме́ртному Жениху́ Христу́ Бо́гу: Єго́же па́че всего́ возлюби́ душа́ моя́ і Єму́же отнині во ві́ки не преста́ну воспіва́ти: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шавши от крести́вшаго тя патріа́рха напутственноє сло́во о чистоті́, по́сте, моли́тві і о всіх доброді́теліх, христия́ном подоба́ющих, слага́ла єси́ сія́ в се́рдці твоє́м, ді́ли вся та ісполня́ти обіщава́ющи. Ті́мже у́бо по до́лгу воспіва́єм ті си́це:","Ра́дуйся, усе́рдная слишательнице слове́с Боже́ственних;","ра́дуйся, ревностная ісполнительнице зако́на христия́нськаго.","Ра́дуйся, ни́ву се́рдця твоєго́ очи́стившая от те́рнія душевре́дних страсте́й;","ра́дуйся, слеза́ми покая́нія оросившая ю.","Ра́дуйся, я́ко сі́м'я сло́ва Бо́жия в се́рдці твоє́м, я́ко на землі́ до́брій, укорени́ся;","ра́дуйся, я́ко сі́м'я сіє́ прозябе́ і стори́чний плод благи́х діл принесе́.","Ра́дуйся, вдовственную твою́ чистоту́ непоро́чно сохранившая;","ра́дуйся, воздержа́нієм і моли́твою Бо́гу угоди́вшая.","Ра́дуйся, ми́лостинею Творця́ умилостивившая;","ра́дуйся, нищія і убо́гая потре́бами снабдившая.","Ра́дуйся, просвіще́ніє землі́ Украї́нськия сві́том Христо́ва уче́нія прови́дівшая.","Ра́дуйся, свята́я равноапо́стольная княги́не О́льго богому́драя."]},{"h":"Кондак 5","ps":["Боготка́нною оде́ждою свята́го креще́нія обле́кшися і нетлі́нною пи́щею Пречи́стаго Ті́ла і Кро́ве Христо́ви духо́вно укрі́пльшися, О́льго преблаже́нная, не убоя́лася єси́ потещи́ к неві́рним соотечественником твої́м, предком на́шим, пропові́дати їм Єди́наго І́стиннаго Бо́га, Єму́же ни́ні вся Украї́на, я́ко єди́німи усти́, воспіва́єть: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівши, свята́я О́льго, вся лю́ди землі́ Украї́нськия во тьмі ідолослуже́нія погруже́нния, усе́рдно потща́лася єси́ просвіти́ти ти́я сві́том Христо́ви ві́ри і сотвори́ти я си́ни дне і наслі́дники Ца́рствія Небе́снаго. Помина́юще у́бо сицево́є твоє́ попече́ніє о них, благода́рственно зове́м ті:","Ра́дуйся, прему́драя властительнице наро́да украї́нськаго;","ра́дуйся, до́брая наста́вниця вві́реннаго ті стада́.","Ра́дуйся, пе́рвій христия́нстій цари́це Єле́ні в ре́вности Боже́ственній подража́вшая;","ра́дуйся, і і́м'я тоя́ во святі́м креще́нії прия́вшая.","Ра́дуйся, честни́й крест Христо́в і святи́я іко́ни із Царграда во град Ки́єв прине́сшая;","ра́дуйся, ієре́ї і кли́рики с собо́ю в Украї́ну приве́дшая.","Ра́дуйся, му́дрими твої́ми глаго́ли поучавшая лю́ди оста́вити тьму язи́чеськаго нече́стія і восприя́ти світ христия́нськаго благоче́стія;","ра́дуйся, мно́гія украї́нці сві́том ві́ри Христо́ви просвіти́вшая.","Ра́дуйся, нача́ло просвіще́нія всея́ землі́ Украї́нськия положившая;","ра́дуйся, гра́ди украї́нськия пропові́данієм Христо́ва уче́нія огласи́вшая.","Ра́дуйся, пе́рвая от землі́ Украї́нськия ли́ку святи́х причтенная.","Ра́дуйся, свята́я равноапо́стольная княги́не О́льго богому́драя."]},{"h":"Кондак 6","ps":["Пропові́дником духоно́сним, Апо́столом, подража́вши, О́льго богому́драя, обходила єси́ гра́ди і ве́сі держа́ви твоєя́, приводя́щи, єли́ко мо́щно бі, лю́ди к ві́рі Христо́вій і науча́ющи їх воспіва́ти Єди́ному в Тро́йці сла́вимому Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Утвержда́я в держа́ві твоє́й нача́ток ві́ри христия́нськия, создала́ єси́ хра́ми Бо́жії во гра́ді Ки́єве і в страні́ рожде́нія твоєго́, при ріці́ Вели́цій у гра́да Пско́ва. І та́ко начата украї́нці прославля́ти повсю́ду Христа́ Бо́га на́шего, тебі́ же, просвіти́тельнице своє́й, похва́льная воспіва́ти:","Ра́дуйся, я́ко от чи́стаго істо́чника Святи́я Собо́рния і Апо́стольськія Це́ркве чи́стоє уче́ніє прия́ла єси́;","ра́дуйся, я́ко тім нас научи́ла єси́ позна́ти Єди́наго і́стиннаго Бо́га.","Ра́дуйся, і́дольських тре́бищ і куми́ров низложительнице;","ра́дуйся, святи́х Бо́жиїх хра́мов создательнице.","Ра́дуйся, я́ко же і Первозва́нний Апо́стол, с про́повідію Єва́нгелія зе́млю Ру́ськую обходившая;","ра́дуйся, Вели́кому Нову́граду і про́чим украї́нським градо́м Христо́во в мир прише́ствіє благовествовавшая.","Ра́дуйся, на мі́стіх про́повіді твоєя́ честни́я крести́ водрузившая, от ни́хже мно́гая зна́менія і чудеса́, увіре́нія ра́ди неві́рних, си́лою Бо́жиєю содевахуся.","Ра́дуйся, я́ко тобо́ю Всеблаги́й Госпо́дь синово́м украї́нським позна́ніє Своє́ яви́л єсть;","ра́дуйся, я́ко чрез них і про́чія мно́гія наро́ди сві́том ві́ри просвіти́л єсть.","Ра́дуйся, я́ко от ко́рене твоєго́ честна́го Госпо́дь свята́го равноапо́стольнаго кня́зя Влади́мира показа́л нам єсть;","ра́дуйся, я́ко о́бразом житія́ твоєго́ святи́й князь Влади́мир подви́гся прия́ти христия́нськую ві́ру.","Ра́дуйся, свята́я равноапо́стольная княги́не О́льго богому́драя."]},{"h":"Кондак 7","ps":["Хотя́щи ізба́вити си́на твоєго́ Святосла́ва от па́губи ві́чния, прилі́жно увещевала єси́ єго́ оста́вити почита́ніє і́долов і ві́ровати в Бо́га і́стиннаго. Но той не внят ма́тернему наказа́нію твоєму́ і не восхоті́ нече́стіє своє́ преміни́ти на благоче́стіє. Ті́мже, я́ко неві́рний, отчужди́ся жи́зні ві́чния і не сподо́бися с тобо́ю в Го́рнем Ца́рствії воспіва́ти: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́воє зна́меніє благоволе́нія Своєго́ яви́ тебі́ Госпо́дь, єгда́, во о́браз Пресвяти́я Тро́йці, три пресві́тлия луча́ с небесе́ облиста́ на мі́сті дубравне, ї́хже не то́чію єди́на ти зріла́ єси́, но і всі су́щії та́мо лю́діє ви́діша, і вку́пі с тобо́ю просла́виша Трієди́наго Бо́га. Ми же, ві́дуще сбитіє́ прорече́нія твоєго́ о созда́нії на мі́сті о́ном хра́ма Живонача́льния Тро́йці і гра́да, ублажа́єм тя си́це:","Ра́дуйся, вели́кая Бо́жия уго́днице, да́ра проро́чествія сподо́бльшаяся.","Ра́дуйся, Трисія́ннаго Небе́снаго сві́та зрительнице;","ра́дуйся, всеблагия во́лі Бо́жієй о просвіще́ніі наро́да ру́ськаго по Апо́столе Андре́є пе́рвая ісполнительнице.","Ра́дуйся, гра́да Пско́ва нача́льная основательнице;","ра́дуйся, всея́ Украї́нськия держа́ви засту́пнице і покрови́тельнице.","Ра́дуйся, я́ко ізволе́нієм Бо́жиїм держа́ва Украї́нськая ни́ні от мо́ря до мо́ря распространи́ся;","ра́дуйся, я́ко вся гра́ди і ве́сі єя́ мно́жеством хра́мов Бо́жиїх украси́шася.","Ра́дуйся, я́ко в хра́міх сих святи́телі і ієре́ї Безкро́вную Же́ртву о лю́діх Бо́гу прино́сять;","ра́дуйся, я́ко со́нми і́ночествующих по всему́ лицю́ землі́ Украї́нськия єдиноду́шно хвалу́ Святі́й Тро́йці воспіва́ють.","Ра́дуйся, я́ко обита́теліє гра́да Ки́єва і Пско́ва сугу́бо тя превозно́сять і ублажа́ють;","ра́дуйся, я́ко і всі правосла́внії украї́нці с літ дре́вніх тя почита́ють і прославля́ють.","Ра́дуйся, свята́я равноапо́стольная княги́не О́льго богому́драя."]},{"h":"Кондак 8","ps":["Стра́нствія земна́го тече́ніє скончава́я, те́плі Го́спода молила єси́, О́льго блаже́нная, да не оста́вить Он зе́млю Украї́нськую по преставле́нії твоє́м во тьмі неві́дінія пребива́ти, но да просвіти́ть ю сві́том святи́я ві́ри і вся си́ни украї́нськия да научи́ть воспіва́ти: Аллилу́я."]},{"h":"Ікос 8","ps":["Вся об'ята би́вши благода́тію Боже́ственною, достохва́льная О́льго, ми́сленними очеси́ зріла́ єси́ просвіще́ніє всего́ наро́да твоєго́ і проро́чеськи предрекла́ єси́, я́ко мно́зі вели́ції уго́дниці Бо́жий, я́ко зві́зди сві́тлия, в землі́ Украї́нській возсія́ють, є́же і сби́стся ізволе́нієм і благода́тію всемогу́щаго Бо́га. Сего́ ра́ди по до́лгу воспіва́єм ті си́це:","Ра́дуйся, духо́вная на́ша ма́ти, іспросившая у Бо́га просвіще́ніє пра́отцем на́шим;","ра́дуйся, я́ко Всеблаги́й Госпо́дь, зря добро́ту душі́ твоєя́, тебе́ ра́ди вся лю́ди ру́ськия возлюби́.","Ра́дуйся, я́ко тя обрі́те Христо́с досто́їн сосу́д, чрез него́же нача́ ізлива́ти благода́ть Свою́ землі́ Украї́нській;","ра́дуйся, я́ко ти предуготовала єси́ лю́ди твоя́ к прия́тію ві́ри і благода́ті Христо́ви.","Ра́дуйся, я́ко прозорли́во предзрела єси́ вели́чіє і сла́ву держа́ви твоєя́;","ра́дуйся, я́ко весели́лася єси́ о предвиденном тобо́ю благоче́стії сино́в украї́нських.","Ра́дуйся, я́ко по прорече́нію твоєму́, мно́зі святі́ї от ро́да на́шего возсія́ша;","ра́дуйся, до́ма Живонача́льния Тро́йці, устроїтельнице.","Ра́дуйся, моли́твами твої́ми в ско́рбіх і напа́стіх нас заступа́ющая;","ра́дуйся, во обстоя́ніїх злих Оте́чество на́ше сохраня́ющая і от враго́в ізбавля́ющая.","Ра́дуйся, свята́я равноапо́стольная княги́не О́льго богому́драя."]},{"h":"Кондак 9","ps":["Вся́ких доброді́телей іспо́лнена би́вши, О́льго блаже́нная, с моли́твою во усті́х предала́ єси́ дух твой в ру́ці Бо́жії, І́же всели́ тя в Небе́сния оби́телі і пе́рвую от украї́нців сопричте ли́ку равноапо́стольних уго́дник Свої́х. Ті́мже іспроси́ і нам у Го́спода ми́рную христия́нськую кончи́ну, да предади́м душі́ на́ша в ру́ці Христа́ Бо́га на́шего, пою́ще Тому́ хвале́бную піснь: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́ї многовіща́ннії не мо́гуть досто́йно восхвали́ти тя, О́льго богому́драя: ка́ко ти, ники́їм же от челові́к учима і увещеваєма, позна́ла єси́ тщету́ ідолослуже́нія, пра́вия же ві́ри взиска́ла єси́ і, я́коже равноапо́стольная Єле́на, обріла́ єси́ безці́нний би́сер, Христа́, Єго́же лицезрі́нія на Небесі́ наслажда́яся ни́ні, не забу́ди нас, пре́лестьми ми́ра сего́ омрача́ємих і о благах ві́чних забива́ющих, да, тобо́ю на путь пра́вий наставля́ємі, взива́єм ті ра́достно:","Ра́дуйся, до́брими твої́ми ді́ли і пра́вим ума́ і се́рдця ізволе́нієм приуготовившая себі́ в жили́ще Боже́ственния благода́ті;","ра́дуйся, я́ко Сам Дух Святи́й учи́тель тебі́ бисть к позна́нію Христа́ Си́на Бо́жия.","Ра́дуйся, никиїхже зна́меній і чуде́с ви́дівшая і во Христа́ ві́ровавшая;","ра́дуйся, таково́ю ві́рою твоє́ю мно́гих гони́телей і мучи́телей, ви́дівших зна́менія і чудеса́ і не ві́ровавших, посрами́вшая.","Ра́дуйся, води́тельству Свята́го Ду́ха себі́ преда́вшая;","ра́дуйся, соверше́нную поко́рность во́лі Бо́жієй показа́вшая.","Ра́дуйся, зва́вшему тя гла́су благода́ті послу́шна яви́вшаяся;","ра́дуйся, с єдинонадеся́таго часа́ во вертогра́ді Госпо́днем потрудившаяся і мзду с пе́рвими получившая.","Ра́дуйся, я́ко умудри́ тя Госпо́дь честь ца́рськую, бога́тство і сла́ву сочета́ти со смире́нієм христия́нським;","ра́дуйся, я́ко сим о́бразом я́ві нам показа́вшая, я́ко бла́га земни́я не суть преп'я́тіє душі́ боголюби́вій к достиже́нію благ Небе́сних.","Ра́дуйся, добро́тою цілому́дрія і сві́тлостію разумі́нія прославившаяся;","ра́дуйся, крі́постію ві́ри і цілому́дренною чистото́ю житія́ твоєго́ проро́чества дар от Бо́га восприя́вшая.","Ра́дуйся, свята́я равноапо́стольная княги́не О́льго богому́драя."]},{"h":"Кондак 10","ps":["Путь спасе́нія синово́м украї́нським устроя́я і предсмертноє проше́ніє твоє́ ісполня́я, Всеблаги́й Госпо́дь возрасти́ во внуці твоє́м Влади́мире всі́янноє тобо́ю сі́м'я ві́ри і чрез него́ всю зе́млю Украї́нськую просвіти́ Святи́м Креще́нієм. Ті́мже у́бо прославля́єм тя, О́льго блаже́нная, я́ко пе́рвую вино́вницю просвіще́нія на́шего сві́том святи́я ві́ри, і уми́льно поє́м Христу́ Спаси́телю на́шему: Аллилу́я."]},{"h":"Ікос 10","ps":["Прия́в Свято́є Креще́ніє, внук твой Влади́мир, потща́ся із'яти із землі́ нетлі́нния мо́щі твоя́, чу́днаго благоуха́нія іспо́лненния, і со святи́телем Леонтієм і всім мно́жеством наро́да поста́ви я в це́ркве Пречи́стия Богома́тері, і отто́лі нача́ша істочатися от них цільби́ вся́ким неду́гом, притекающим с ві́рою. Сего́ ра́ди восхваля́єм тя си́це:","Ра́дуйся, я́ко благода́ть Свята́го Ду́ха, в тя все́льшаяся, подаде́ нетлі́ніє моще́м твої́м і сотвори́ в мощеіх твої́х цільбопода́тельний істо́чник на вся́кия неду́ги;","ра́дуйся, с малові́рієм к ним приходящия ви́діти я не попускавшая.","Ра́дуйся, явле́нієм моще́й твої́х младенствовавшую Це́рков Украї́нськую возвесели́вшая;","ра́дуйся, прославле́нієм їх вну́ка твоєго́ Влади́мира зіло́ обра́довавшая.","Ра́дуйся, я́ко і до ни́ні благочести́вії лю́діє землі́ Украї́нськия сла́вною па́м'ятію твоє́ю услаждаються;","ра́дуйся, я́ко твої́м к Бо́гу хода́тайством ві́рнії украї́нці мно́гих благ от Го́спода сподобля́ються.","Ра́дуйся, моли́твами твої́ми о просвіще́ніі землі́ Украї́нськия Бо́га умолившая;","ра́дуйся, вско́рі мно́гим вели́ким святи́м яви́тися на землі́ Украї́нській прорекшая.","Ра́дуйся, свята́я равноапо́стольная княги́не О́льго богому́драя."]},{"h":"Кондак 11","ps":["Пі́ніє умиле́нноє прино́сим ті, уго́днице Бо́жия, і смире́нно тя мо́лим: моли́ о нас Єди́наго Человіколю́бця Бо́га, да не отврати́ть лиця́ Своєго́ от нас, недосто́йних, при́сно согріша́ющих і преогорчева́ющих бла́гость Єго́, но да нака́жеть нас зді, я́ко Оте́ць чадолюби́вий, онаможе, в бу́дущем ві́ці, да спасе́ть і поми́луєть, я́ко Судія́ і Мздовоздая́тель пра́ведний, да та́ко, ізба́вльшеся ві́чнаго муче́нія, сподо́бимся с тобо́ю в ра́йських оби́теліх воспіва́ти Єму́: Аллилу́я."]},{"h":"Ікос 11","ps":["Трисія́нним сві́том осіява́єма, со всі́ми святи́ми предстої́ши ни́ні на Небесі́ Престо́лу Царя́ ца́рствующих, О́льго всеблаже́нная, і отту́ду, я́ко світоза́рноє світи́ло, просвіща́єши всю страну́ Украї́нськую, разгоня́я мрак заблужде́ній і показу́я путь к і́стинному просвіще́нію к Небе́сному блаже́нству. Сего́ ра́ди, прославля́юще тя, глаго́лем:","Ра́дуйся, луно́ просвіще́нная от незаходи́маго Со́лнця Пра́вди;","ра́дуйся, путеводи́тельнице, пра́вую стезю́ к ві́чному спасе́нію нам показу́ющая.","Ра́дуйся, мощная споспі́шнице і укрепительнице пропові́дников правосла́вния ві́ри;","ра́дуйся, при́сная покрови́тельнице благи́х наста́вников ю́ношества і всіх, благотрудящихся на по́льзу о́бщую.","Ра́дуйся, законодателей страни́ Украї́нськия наста́внице і покрови́тельнице;","ра́дуйся, народоправителей і нача́льников страни́ сея́ му́драя і до́брая советоподательнице.","Ра́дуйся, крамо́л і раздо́ров потребительнице;","ра́дуйся, всіх оби́димих і непра́ведно гони́мих засту́пнице.","Ра́дуйся, скорб'я́щих ско́рая уті́шительнице;","ра́дуйся, боля́щих ми́лостивая ісціли́тельнице.","Ра́дуйся, лю́дем на́шим по́мощ моли́твами твої́ми от Бо́га подава́ющая;","ра́дуйся, всея́ страни́ Украї́нськия предста́тельнице і засту́пнице.","Ра́дуйся, свята́я равноапо́стольная княги́не О́льго богому́драя."]},{"h":"Кондак 12","ps":["Благода́ть Пресвята́го Ду́ха іспроси́ нам, наста́внице на́ша, от Всеще́драго Бо́га і Спа́са на́шего, вразумля́ющую і укріпля́ющую нас в ді́лі спасе́нія, да не безпло́дно бу́деть в нас всі́янноє тобо́ю сі́м'я святи́я ві́ри, но да прозя́бнеть і плод сотвори́ть, і́мже би возмощи́ нам пита́ти душі́ на́ша в бу́дущей ві́чній жи́зні, іді́же всі святі́ї воспіва́ють Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще твоя́ мно́гая і пресла́вная благодія́нія, явле́нная страні́ Украї́нській в просвіще́ніі той сві́том ві́ри Христо́вой, благода́рственная прино́сим ті, с любо́вію зову́ще сицева́я:","Ра́дуйся, богоізбра́нная і богопросла́вленная самодержице землі́ Ру́ськия, несокрушимоє огражде́ніє єя́, покро́в і защище́ніє.","Ра́дуйся, ді́вам украї́нським о́бразе цілому́дреннаго житія́;","ра́дуйся, ма́терем наста́внице зако́ннаго супру́жества і до́браго чад воспита́нія.","Ра́дуйся, вдови́цям пра́вило богоуго́днаго житія́;","ра́дуйся, всім украї́нцям учи́тельнице і о́бразе всіх доброді́телей.","Ра́дуйся, соучастнице на Небесі́ жре́бія пропові́дников ві́ри Христо́ви;","ра́дуйся, соприча́стнице ві́чнаго блаже́нства пра́ведних.","Ра́дуйся, те́плая о нас пред Бо́гом моли́твеннице;","ра́дуйся, усе́рдная о спасе́нії на́шем хода́тайце.","Ра́дуйся, в час сме́рти на́шея о нас к Бо́гу хода́тайце;","ра́дуйся, по ісхо́ді на́шем от сме́ртнаго сего́ тілесе́ по́мощ і утіше́ніє подаю́щая.","Ра́дуйся, свята́я равноапо́стольная княги́не О́льго богому́драя."]},{"h":"Кондак 13","ps":["О свята́я равноапо́стольная вели́кая княги́не О́льга, прийми́ ми́лостивно от нас хвале́бноє благодаре́ніє сіє́ о всіх, я́же тобо́ю воздаде́ Госпо́дь нам, отце́м і пра́отцем на́шим і всей держа́ві Украї́нській, і моли́ Всеблага́го Бо́га умно́жити ми́лость Свою́ на ни і на ро́ди родо́в на́ших, утверди́ти ни в правові́рії і благоче́стії, храни́ти же от всіх напа́стей, бід і зол, да сподо́бимся с тобо́ю, я́ко ча́да с ма́терію, во ві́ки воспіва́ти Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелов і челові́ков Творе́ць, времена́ і лі́та во Своє́й вла́сті положи́вий і судьби́ царств і наро́дов по Своє́й во́лі управля́яй, єгда́ восхоті́ род украї́нський Святи́м Креще́нієм просвіти́ти, тогда́, ви́дя благо́є ізволе́ніє се́рдця твоєго́, призва́ тя пе́рвіє в позна́ніє Себі́, да бу́деши всім украї́нцям о́браз і наста́вниця в христия́нстій ві́рі. Сего́ ра́ди восхваля́єм тя си́це:","Ра́дуйся, украї́нськаго небесе́ у́тренняя звіздо́, от Первозва́ннаго Апо́стола на гора́х Ки́євських предвозвіще́нная;","ра́дуйся, заре́, во мра́ці неві́дінія сві́тло возблиставшая.","Ра́дуйся, до́брая лозо́ виногра́да Христо́ва, от ди́вія* язи́чеськаго ко́рене прозя́бшая;","ра́дуйся, пречу́дная лі́торасле, із нея́же ве́ліє правові́рія дре́во на землі́ на́шей возрасте́.","Ра́дуйся, первоучительнице і просвіти́тельнице на́ша;","ра́дуйся, я́ко тобо́ю позна́хом поклоня́тися в Тро́йці Творцю́.","Ра́дуйся, я́ко тебе́ ра́ди Пресвято́є І́м'я Госпо́днє от всіх украї́нців прославля́ється;","ра́дуйся, я́ко і твоє́ пресла́вноє і́м'я вку́пі с равноапо́стольним Влади́миром во всіх преді́ліх ми́ра восхваля́ється.","Ра́дуйся, страни́ на́шея Украї́нськия духо́вноє сокро́вище;","ра́дуйся, всея́ Христо́ви Це́ркве пресла́вноє украше́ніє.","Ра́дуйся, градо́в Ки́єва і Пско́ва ізря́дная добро́то;","ра́дуйся, лю́дем на́шим на враги́ блага́я помо́щнице.","Ра́дуйся, свята́я равноапо́стольная княги́не О́льго богому́драя."]},{"h":"Кондак 1","ps":["Первоізбранней от всего́ украї́нськаго ро́да, сла́вній і равноапо́стольній уго́днице Бо́жієй О́льгі соста́вим похвалу́, я́ко заре́, во тьмі ідолопоклоненія сві́том ві́ри возсія́вшей і путь ко Христу́ всім украї́нцям показавшей. Ти же, я́ко іму́щая дерзнове́ніє к просла́вльшему тя Го́споду, огражда́й нас от вся́ких бід моли́твами твої́ми, да зове́м ті:","Ра́дуйся, свята́я равноапо́стольная княги́не О́льго богому́драя."]},{"h":"Молитва","ps":["О свята́я равноапо́стольная вели́кая княги́не О́льго, первоуго́днице украї́нськая, те́плая о нас пред Бо́гом хода́тайце і моли́твеннице. К тебі́ прибіга́єм с ві́рою і мо́лимся с любо́вію: бу́ди нам во всем ко бла́гу помо́щниця і споспі́шниця і, я́коже во вре́менной жи́зні тща́лася єси́ просвіти́ти пра́отці на́ша сві́том святи́я ві́ри і наста́вити я твори́ти во́лю Госпо́дню, та́ко і ни́ні, в небе́сній пребива́я сві́тлости, благоприя́тними твої́ми к Бо́гу моли́твами вспомоществу́й нам в просвіще́ніі ума́ і се́рдця на́шего сві́том Єва́нгелія Христо́ва, да преспіва́єм во ві́рі, благоче́стії і любві́ Христо́ві. В нищеті́ і ско́рби су́щия уті́ши, бедствующим пода́ждь ру́ку по́мощі, оби́димия і напа́ствуємия заступи́, заблудшия от пра́вия ві́ри і єресьми́ осліпле́нния вразуми́, і іспроси́ нам у Всеще́драго Бо́га вся блага́я і поле́зная в жи́зні вре́менной і ві́чній, да та́ко благоуго́дні зді пожи́вше, сподо́бимся наслі́дія благ ві́чних в безконе́чнім Ца́рствії Христа́ Бо́га на́шего, Єму́же со Отце́м і Святи́м Ду́хом подоба́єть вся́кая сла́ва, честь і поклоне́ніє всегда́, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва","ps":["О вели́кая уго́днице Бо́жия, богоізбра́нная і богопросла́вленная, равноапо́стольная вели́кая княги́не О́льго! Ти отри́нула єси́ злові́ріє і нече́стіє язи́чеськоє, уві́ровала єси́ во Єди́наго І́стиннаго Триіпоста́снаго Бо́га, і восприя́ла єси́ свято́є Креще́ніє, і положи́ла єси́ нача́ло просвіще́нію землі́ Украї́нськия сві́том ві́ри і благоче́стія. Ти єси́ духо́вная родонача́льниця на́ша, ти по Христе́ Спаси́телі на́шем пе́рвая вино́вниця просвіще́нія і спасе́нія ро́да на́шего. Ти єси́ те́плая моли́твенниця і хода́тайця о оте́честві Всеукраї́нськім, во́їнстві і всіх лю́діх. Сего́ ра́ди смире́нно мо́лим тя: при́зри на не́мощі на́ша і умоли́ Премилосе́рдаго Царя́ небе́снаго, да не прогні́вається на ни зіло́, я́ко по не́мощем на́шим по вся дні согріша́єм, да не погуби́ть нас со беззако́ньми на́шими, но да поми́луєть і спасе́ть нас по ми́лості Своє́й, да всади́ть в се́рдця на́ша спаси́тельний страх Свой, да просвіти́ть Своє́ю благода́тію ум наш, вуо є́же разумі́ти нам путі́ Госпо́дні, оста́вити стезі́ нече́стія і заблужде́ній, татися же во путях спасе́нія і і́стини, неукло́ннаго ісполне́нія за́повідей Бо́жиїх і усавов святи́я Це́ркве. Моли́, блаже́нная О́льго, Человіколю́бця Го́спода, да проба́вить нам вели́кую ми́лость Свою́, да ізба́вить нас от наше́ствія іноплеме́нних, от вну́тренних нестроє́ній, м'яте́жей і раздо́ров, от гла́да, смеротоносних болі́зней і от вся́каго зла, да пода́сть нам благорастворе́ніє возду́ха і плодоно́сіє землі́, да сохрани́ть страну́ на́шу от всіх ко́зней і наві́т вра́жиїх, да соблюде́ть в судеях і прави́теліх пра́вду і ми́лость, да дасть па́стирем ре́вность о спасе́нії пасо́мих, всім же лю́дем споспіше́ніє, о є́же усе́рдно слу́жби своя́ ісполня́ти, любо́в между́ собо́ю і єдиноми́сліє імі́ти, на бла́го оте́чества і Святи́я Це́ркве ві́рне подвиза́тися, да возсія́єть світ спаси́тельния ві́ри в страні́ на́шей во всіх конці́х єя́, да обратя́ться к ві́рі неві́рующіі, да упраздня́ться вся є́ресі і раско́ли. Да, та́ко пожи́вше в ми́рі на землі́, сподо́бимся с тобо́ю ві́чнаго блаже́нства на Небесі́, хва́ляще і превознося́ще Бо́га во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 1","ps":["Крила́ми богоразу́мія впери́вши твой ум, / возлеті́ла єси́ преви́ше ви́димая тва́рі, / взиска́вши Бо́га і Творця́ вся́чеських, / і, Того́ обрі́тши, па́ки рожде́ніє Креще́нієм прия́ла єси́, / дре́ва живо́тнаго наслажда́ющися, нетлі́нна во ві́ки пребива́єши, // О́льго присносла́вная."]},{"h":"Інший тропар, глас 8","ps":["В тебі́, Богому́драя Єле́но, ізві́стен спасе́нія о́браз бисть в Ру́сстій страні́, / я́ко, приї́мши ба́ню свята́го Креще́нія, послі́довала єси́ Христу́, / творя́щи же і уча́щи, є́же оста́вити і́дольськую пре́лесть, / восприя́ти же попече́ніє о душі́, ве́щі безсме́ртній, // ті́мже і со А́нгели ра́дується, равноапо́стольная, дух твой."]},{"h":"Кондак, глас 4","ps":["Воспоє́м днесь Благоді́теля всіх Бо́га, / просла́вльшаго в Украї́ні О́льгу Богому́друю: / да моли́твами єя́ / пода́сть душа́м на́шим // гріхо́в оставле́ніє."]},{"h":"Інший кондак, глас 4","ps":["Яви́ся днесь благода́ть всіх Бо́га, / просла́вльши в Русі́ О́льгу Богому́друю, / моли́твами єя́, Го́споди, / лю́дем пода́ждь // гріхо́в оставле́ніє."]},{"h":"Величання","ps":["Велича́єм тя, / блаже́нная і равноапо́стольная княги́не О́льго, / і чтим святу́ю па́м'ять твою́, / і́доли попра́вшую // і мно́гия лю́ди украї́нськия святи́м Креще́нієм просвіти́вшую."]},{"h":"Інше величання","ps":["Велича́єм тя, / свята́я равноапо́стольная княги́не О́льго, / я́ко зарю́ у́треннюю в землі́ на́шей возсія́вшую / і світ ві́ри Правосла́вния // наро́ду своєму́ предвозвести́вшую."]}],"notes":[]},{"u":"Акафіст священномученику Іларіону, архієпископу Верейському","e":"Akathist to the Hieromartyr Hilarion, Archbishop of Vereya","secs":[{"h":"Кондак 1","ps":["Ізбра́нний во́їне Христо́в і свиді́телю ві́рний, єди́ну Святу́ю, Собо́рную і Апо́стольськую Це́рков во спасе́ніє всіх іспові́давий, за ню́же пострада́ти да́же до сме́рти ізво́лил єси́, і ни́ні в Це́ркві торжеству́ющей прославля́ємий, помина́й нас, любо́вію ті взива́ющих:","Ра́дуйся, Іларіо́не, Це́ркве Ру́ськия сла́во і украше́ніє."]},{"h":"Ікос 1","ps":["А́нгела земна́го і челові́ка Небе́снаго зрим тя, святи́телю Іларіо́не, чистоту́ душе́вную ізмла́да соблю́дшаго і по́двигом духо́вним дар благода́ті стяжа́вшаго, ті́мже ни́ні ско́рую по́мощ всім подає́ши, в моли́твах та́ко тя призива́ющим:","Ра́дуйся, благоче́стія роди́телева наслі́дниче;","ра́дуйся, Це́ркве Христо́ви ізбра́нноє ча́до.","Ра́дуйся, от младе́нства уче́нію прилежа́вий;","ра́дуйся, і́стини Боже́ственния умо́м і се́рдцем взиска́вий.","Ра́дуйся, шко́лу духо́вную я́ко ма́тер і пита́тельницю возлюби́вий;","ра́дуйся, тве́рдою пи́щею богосло́вія воспита́нний.","Ра́дуйся, под кро́вом моли́тв преподо́бнаго Се́ргия ві́рою укріпи́вийся;","ра́дуйся, на брань духо́вную с миродержи́телем тьми ві́ка сего́ ізше́дий.","Ра́дуйся, Іларіо́не, Це́ркве Ру́ськия сла́во і украше́ніє."]},{"h":"Кондак 2","ps":["Ви́дя мі́сто патріа́ршеє пра́здно су́ще во вели́цій це́ркві Успе́нськой, рида́л єси́ се́рдцем го́рці, Іларіо́не, і к лю́дем ру́ським взива́л єси́: доко́лі пла́кати і́мать земля́? Ізбра́нну же би́вшу Патріа́рху Освяще́нним Собо́ром, лику́я воспі́л єси́ Бо́гу побі́дную піснь: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зумом богопросвіще́нним проре́кл єси́ Патріа́рху не ца́рський віне́ць восхи́тити, но му́ченичеським вінце́м украси́тися, по вся бо дні умира́ти і́мать за Це́рков Христо́ву. Сим кре́стним путе́м і ти, Іларіо́не, первосвяти́телю сше́ствовал єси́, ті́мже всі восхваля́єм тя си́це:","Ра́дуйся, догма́тов і кано́нов церко́вних ревни́телю;","ра́дуйся, о Це́ркві Ру́ськой те́плий моли́твенниче.","Ра́дуйся, поруга́нія сла́ви церко́вния ви́діти не терпі́вий;","ра́дуйся, сло́вом огнено́сним сердца́ ві́рних воспламени́вий.","Ра́дуйся, во ізбра́нії Патріа́рха ісполне́ніє ча́яній церко́вних узрі́вий;","ра́дуйся, первосвяти́телю в труді́х і попече́ніїх о Це́ркві сподвиза́вийся.","Ра́дуйся, крест служе́нія архієре́йськаго во дні гоне́ній восприє́мий;","ра́дуйся, на ка́мені ві́ри стопи́ твоя́ утверди́вий.","Ра́дуйся, Іларіо́не, Це́ркве Ру́ськия сла́во і украше́ніє."]},{"h":"Кондак 3","ps":["Си́лою Ви́шняго укріпля́єм, Іларіо́не, под'я́л єси́ по́двиг служе́нія архієре́йськаго, всім бив вся, і всім себі́ порабо́тив, утіша́я, наставля́я і облича́я, Бо́гу же ви́ну поя́: Аллилу́я."]},{"h":"Ікос 3","ps":["Іми́й ре́вность по Бо́зі і ве́ліє дерзнове́ніє, святи́телю Іларіо́не, отсту́пники отгна́л єси́ от оби́телі Сре́тенськия, к покая́нію тіх призива́я і ча́да церко́вная во благоче́стії утвержда́я, ті́мже прийми́ от нас похвали́ сія́:","Ра́дуйся, враги́ твоя́ і гони́телі любо́вію покрива́яй;","ра́дуйся, враги́ церко́вния о́гненними словеси́ опаля́яй.","Ра́дуйся, хитросплете́нія лжепа́стирей расторга́яй;","ра́дуйся, во ві́рности Патріа́рху коле́блемих утвержда́яй.","Ра́дуйся, мно́гі отсту́пники к покая́нію обрати́вий;","ра́дуйся, любо́вію к Це́ркві ві́рних сердця́ іспо́лнивий.","Ра́дуйся, лука́вия совопро́сники ві́ка сего́ посрами́вий;","ра́дуйся, за і́стину церко́вную страда́ти ізво́ливий.","Ра́дуйся, Іларіо́не, Це́ркве Ру́ськия сла́во і украше́ніє."]},{"h":"Кондак 4","ps":["Бу́рею зло́би смуща́ємі гони́телі Це́ркве, у́зи і темни́ці ті угото́ваша, тща́щеся світ іспові́данія твоєго́ сокри́ти, Іларіо́не, ти же, і власть богобо́рную я́ко попуще́ніє за гріхи́ от Бо́га приє́мля, о всем прославля́л єси́ Промисли́теля всіх, поя́: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́ша стра́шния ві́сти о гоне́ніїх лю́тих, не поколеба́лся єси́ душе́ю, Іларіо́не сла́вне, но па́че укріпи́лся єси́ ві́рою в Це́рков Христо́ву, я́ко багряни́цею і ви́ссом, кровми́ но́вих му́ченик украша́єму. Тя же, я́ко єди́наго от них, священному́чениче, ублажа́єм, воспіва́юще ті сицева́я:","Ра́дуйся, омофо́р святи́тельський в день священному́ченика Єрмоге́на приє́мий;","ра́дуйся, служе́ніє архипа́стирськоє страда́нієм запечатлі́вий.","Ра́дуйся, у́зи, темни́ці і го́ркия рабо́ти за Христа́ претерпі́вий;","ра́дуйся, благоду́шієм і терпі́нієм в ско́рбіх сих украше́нний.","Ра́дуйся, нестяжа́нія і кро́тости о́бразе;","ра́дуйся, о гоня́щих і оби́дящих тя моли́твенниче.","Ра́дуйся, богосло́ве, ри́барськія мре́жі не возгнуша́вийся;","ра́дуйся, уму́ преізя́щному апо́стольськую простоту́ сочета́вий.","Ра́дуйся, Іларіо́не, Це́ркве Ру́ськия сла́во і украше́ніє."]},{"h":"Кондак 5","ps":["Боготе́чная звізда́ яви́лся єси́, Іларіо́не, во у́зах солове́цьких стра́ждущим лю́ті, і́мже смерть предстоя́ше на всяк час, тьму бо зло́би сатани́нськия сві́том любве́ просвіти́л єси́, уни́ніє і страх отгоня́я, соу́зники же твоя́ научи́л єси́ во ско́рбіх хвали́ти Бо́га: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дяще нача́льници і приста́вници во узи́лищі му́жество і добро́ту душі́ твоєя́, Іларіо́не чу́дне, де́рзость оби́чную отлага́ху і я́ко архієре́я Бо́жия тя почита́ху, ми же тя я́ко святи́теля і му́ченика си́це восхваля́єм:","Ра́дуйся, простото́ю і кро́тостію вся к себі́ привлека́яй;","ра́дуйся, любо́вію твоє́ю вся́кую ду́шу возвеселя́яй.","Ра́дуйся, тщесла́внаго ду́ха фарисе́йськаго обличи́телю;","ра́дуйся, лицемі́рія і лжі іскорени́телю.","Ра́дуйся, о́браз Бо́жий нетлі́нний в челові́ціх прозрева́яй;","ра́дуйся, і са́мих отча́янних грі́шников не отмета́яй.","Ра́дуйся, благоду́шієм твої́м страда́льці утіша́яй;","ра́дуйся, сло́вом ві́ри малоду́шния возставля́яй.","Ра́дуйся, Іларіо́не, Це́ркве Ру́ськия сла́во і украше́ніє."]},{"h":"Кондак 6","ps":["Пропові́дник і свиді́тель яви́лся єси́ і́стини глаго́ла Христо́ва, я́ко врата́ а́дова не одолі́ють Це́ркві, вся бо су́єтная кова́рства князе́й богобо́рних, Іларіо́не, я́вна соді́лал єси́, просвіща́ющему і укріпля́ющему тя Бо́гу взива́я: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́л єси́ Це́ркві Ру́ськой, Іларіо́не, я́ко звізда́ путево́дная, посреді́ см'яте́ній і раско́лов, от слуг сатани́нських всева́ємих, ти бо ві́ру і пра́вила церко́вная тве́рдо храня́, со преда́телі і отсту́пники в сові́т не вшел єси́, па́че же страда́ти с людьми́ Бо́жиїми ізво́лил єси́, ті́мже тя, священному́чениче, похваля́єм:","Ра́дуйся, ле́сти богобо́рних не послу́шавий;","ра́дуйся, хитросплете́нния ко́зні тіх разори́вий.","Ра́дуйся, і́стину церко́вную сло́вом богому́дрим пропові́давий;","ра́дуйся, страда́льчеським житіє́м сло́во сіє́ ізве́ствовавий.","Ра́дуйся, архипа́стирей і па́стирей во узи́лищі укрепля́вий;","ра́дуйся, от раско́ла церко́внаго смуще́нних огражда́вий.","Ра́дуйся, к єдине́нію с Це́рковію вся призива́вий;","ра́дуйся, не́мощі собра́тій долготерпі́ти увещава́вий.","Ра́дуйся, Іларіо́не, Це́ркве Ру́ськия сла́во і украше́ніє."]},{"h":"Кондак 7","ps":["Хотя́щу ті Це́ркві Христо́ві послужи́ти, Іларіо́не, прия́т Человіколю́бець Госпо́дь страда́льчеськоє твоє́ житіє́ я́ко же́ртву благоуха́нну, хода́тая і моли́твенника тя ві́рним дарова́в, пою́щим Єму́: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вим страстоте́рпцем Це́ркве Ру́ськия сочета́лся єси́, Іларіо́не достоблаже́нне, єгда́ во враче́бниці Петро́ва гра́да тя́жко боля́й, ду́шу твою́ в ру́ці Христу́ пре́дал єси́. Ві́рнії же многострада́льноє ті́ло твоє́ погребо́ша со пла́чем, надгро́бния пі́сні ті воспіва́юще:","Ра́дуйся, от уз і заточе́нія сме́ртію разріши́вийся;","ра́дуйся, свобо́ду сла́ви чад Бо́жиїх улучи́вий.","Ра́дуйся, на землі́ не о себі́, но о Це́ркві Ру́ськой скорбі́вий;","ра́дуйся, на Небесі́ о благостоя́нії єя́ при́сний хода́таю.","Ра́дуйся, ві́рними с любо́вію провожда́ємий;","ра́дуйся, А́нгельськими ли́ки во сла́ві срета́ємий.","Ра́дуйся, блаже́нств єва́нгельських соприча́стниче;","ра́дуйся, я́ко мзда твоя́ мно́га на Небесі́х.","Ра́дуйся, Іларіо́не, Це́ркве Ру́ськия сла́во і украше́ніє."]},{"h":"Кондак 8","ps":["Стра́нник і пришле́ць бил єси́ на землі́, Небе́снаго Ца́рства взиску́я, о́браз того́ і явле́ніє Це́рков святу́ю в ми́рі сем іспові́дуя, і та́йну спасе́нія богодви́жним умо́м іспиту́я, богосло́вствовал і хвали́л єси́ Бо́га о сем: Аллилу́я."]},{"h":"Ікос 8","ps":["Всім се́рдцем і всім умо́м твої́м Христа́ возлюби́в, Іларіо́не блаже́нне, от то́ржища ми́ра к трапе́зі Госпо́дні лю́ди ру́ськия призива́л єси́, сего́ ра́ди с весе́лієм вопіє́м ті:","Ра́дуйся, Єва́нгелія Христо́ва пропові́дниче;","ра́дуйся, апо́стольських преда́ній храни́телю.","Ра́дуйся, уче́ній єрети́чеських обличи́телю;","ра́дуйся, писа́ній оте́чеських сказа́телю.","Ра́дуйся, Христа́ краєуго́льна Ка́меня Це́ркве іспові́давий;","ра́дуйся, на Ка́мені сем упова́ніє твоє́ утверди́вий.","Ра́дуйся, уми́ любому́дрия сло́вом і́стини просвіща́яй;","ра́дуйся, сердца́ проста́я теплото́ю любве́ возгрева́яй.","Ра́дуйся, Іларіо́не, Це́ркве Ру́ськия сла́во і украше́ніє."]},{"h":"Кондак 9","ps":["Все єстество́ А́нгельськоє ра́дости іспо́лнися, Іларіо́не великоімени́те, восходя́щу ті от земни́х к Небе́сним, ти бо, я́ко но́вая звізда́, на тве́рди церко́вній возсія́л єси́ ві́рним, пою́щим о тебі́ Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Віти́йствуяй умолка́єть язи́к пред та́йною твоєго́ за Христа́ страда́нія, мно́гими бо дарова́ньми почте́нний, всебога́те Іларіо́не, нічто́же от них пощаді́л єси́, сме́рті Христо́ві сообразу́яся і науча́я нас воспіва́ти тебі́ такова́я:","Ра́дуйся, крі́пость тіле́сную во у́зах істощи́вий;","ра́дуйся, крі́пость духо́вную в терпі́нії стяжа́вий.","Ра́дуйся, бистроту́ ума́ послуша́нієм Бо́гу связа́вий;","ра́дуйся, благодаре́нієм в ско́рбіх І́ову подража́вий.","Ра́дуйся, я́ко ри́зи злати́я на ру́бищі преміни́л єси́;","ра́дуйся, я́ко оде́ждею весе́лія ни́ні обле́клся єси́.","Ра́дуйся, престо́ла церко́внаго нево́лею зді отлуче́нний;","ра́дуйся, Престо́лу Сла́ви ни́ні предстоя́й, я́ко муж соверше́нний.","Ра́дуйся, Іларіо́не, Це́ркве Ру́ськия сла́во і украше́ніє."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ ду́шу свою́, пло́ті, ми́ру і дия́волу не порабо́тился єси́, Іларіо́не блаже́нне, но, я́ко зла́то в горни́лі, скорбми́ мно́гими іскуша́єм, терпі́нієм ра́зум соверше́н стяжа́л єси́, ра́дуяся о Бо́зі і поя́ Єму́: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ і утвержде́ніє Це́ркві Ру́ськой во дні безбо́жних гоне́ній яви́лся єси́, Іларіо́не святи́телю, ті́мже і нас, в мо́рі жите́йстім обурева́ємих, от лжеуче́ній і собла́знов ізба́ви, вопію́щих ті с любо́вію такова́я:","Ра́дуйся, от ю́ности твоєя́ Це́рков я́ко Ма́тер спаса́ємих возлюби́вий;","ра́дуйся, сло́вом і моли́твою мно́гія в ло́но єя́ возврати́вий.","Ра́дуйся, плоть твою́ воздержа́нієм ду́ху покори́вий;","ра́дуйся, ум твой уче́нієм церко́вним уцілому́дривий.","Ра́дуйся, благоче́стія цві́те нетлі́нний;","ра́дуйся, іспові́данія плод принося́й.","Ра́дуйся, святи́телей ру́ських удобре́ніє;","ра́дуйся, новому́чеников честна́я похвало́.","Ра́дуйся, Іларіо́не, Це́ркве Ру́ськия сла́во і украше́ніє."]},{"h":"Кондак 11","ps":["Пі́ніє всеумиле́нноє прино́сим ті, Іларіо́не, о́тче наш, к ра́ці моще́й твої́х любо́вію притека́юще і моля́щеся: не оста́ви оте́чества твоєго́ земна́го і оби́телі твоєя́, но вся во благоче́стії утверди́, да ви́ну зове́м: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоза́рную звізду́ в нощі́ уни́нія су́щим ви́дим тя, Іларіо́не небоявле́нне, ти бо світ невече́рнія ра́дости в се́рдці нося́, ско́рбний мрак разгоня́єши, возвеселя́я всіх вопію́щих ті:","Ра́дуйся, ра́дости тезоимени́тий;","ра́дуйся, от младе́нства Бо́гом ізбра́нний.","Ра́дуйся, Воскресе́нія Христо́ва і́стинний свиді́телю;","ра́дуйся, сла́ви Ца́рствія в до́льнем ми́рі возвісти́телю.","Ра́дуйся, блаже́нную чистоту́ явля́яй;","ра́дуйся, ра́дости о Бо́зі Спа́сі па́дшия науча́яй.","Ра́дуйся, я́ко житіє́ твоє́ при́сноє єсть Бо́гу хвале́ніє;","ра́дуйся, я́ко смерть твоя́ бисть Христу́ Воскре́сшему побі́дноє пі́ніє.","Ра́дуйся, Іларіо́не, Це́ркве Ру́ськия сла́во і украше́ніє."]},{"h":"Кондак 12","ps":["Благода́ть от Бо́га прия́л єси́, Іларіо́не, неду́жния ісціля́ти, ско́рбния утіша́ти, па́дшия возставля́ти, ті́мже і ми, сві́тло па́м'ять твою́ соверша́юще, благода́рно зове́м: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще по́двиг іспові́данія твоєго́, восхваля́єм тя, святи́телю Іларіо́не пресла́вне, тече́ніє бо непоро́чно сконча́в і ві́ру соблю́д, пра́вди віне́ць прия́л єси́, ті́мже Це́рков Ру́ськая тобо́ю хва́литься, побі́дния пі́сні ті возсила́ющи:","Ра́дуйся, во́їне Христо́в непобіди́мий;","ра́дуйся, сто́лпе Це́ркве несокруши́мий.","Ра́дуйся, за́повідей єва́нгельських ісполни́телю;","ра́дуйся, ни́ви церко́вния ді́лателю і храни́телю.","Ра́дуйся, цві́те украї́нськаго лу́га духо́внаго;","ра́дуйся, пло́де кра́сний сі́янія спаси́тельнаго.","Ра́дуйся, собо́ра но́вих му́чеников сві́тлая звіздо́;","ра́дуйся, о земні́м оте́честві при́сний моли́твенниче.","Ра́дуйся, Іларіо́не, Це́ркве Ру́ськия сла́во і украше́ніє."]},{"h":"Кондак 13","ps":["О преди́вний священному́чениче Христо́в Іларіо́не, Це́ркве Ру́ськия украше́ніє, прийми́ ни́ні ма́лоє моле́ніє сіє́ на́ше, от тлітво́рних собла́знов ізба́ви нас, да от ві́чних мук свобо́ждшеся твої́ми к Бо́гу моли́твами і спасе́ніє улучи́вше, воспоє́м с тобо́ю Святі́й Тро́йці: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгела земна́го і челові́ка Небе́снаго зрим тя, святи́телю Іларіо́не, чистоту́ душе́вную ізмла́да соблю́дшаго і по́двигом духо́вним дар благода́ті стяжа́вшаго, ті́мже ни́ні ско́рую по́мощ всім подає́ши, в моли́твах та́ко тя призива́ющим:","Ра́дуйся, благоче́стія роди́телева наслі́дниче;","ра́дуйся, Це́ркве Христо́ви ізбра́нноє ча́до.","Ра́дуйся, от младе́нства уче́нію прилежа́вий;","ра́дуйся, і́стини Боже́ственния умо́м і се́рдцем взиска́вий.","Ра́дуйся, шко́лу духо́вную я́ко ма́тер і пита́тельницю возлюби́вий;","ра́дуйся, тве́рдою пи́щею богосло́вія воспита́нний.","Ра́дуйся, под кро́вом моли́тв преподо́бнаго Се́ргия ві́рою укріпи́вийся;","ра́дуйся, на брань духо́вную с миродержи́телем тьми ві́ка сего́ ізше́дий.","Ра́дуйся, Іларіо́не, Це́ркве Ру́ськия сла́во і украше́ніє."]},{"h":"Кондак 1","ps":["Ізбра́нний во́їне Христо́в і свиді́телю ві́рний, єди́ну Святу́ю, Собо́рную і Апо́стольськую Це́рков во спасе́ніє всіх іспові́давий, за ню́же пострада́ти да́же до сме́рти ізво́лил єси́, і ни́ні в Це́ркві торжеству́ющей прославля́ємий, помина́й нас, любо́вію ті взива́ющих:","Ра́дуйся, Іларіо́не, Це́ркве Ру́ськия сла́во і украше́ніє."]},{"h":"Молитва","ps":["О пресла́вний уго́дниче Бо́жий священному́чениче Іларіо́не, о́тче наш, ти во дні маловре́меннаго житія́ земна́го посреді́ гоне́ній і скорбе́й мно́гих ві́ру сохрани́в, ду́ха не угаси́л єси́ і ві́рния научи́л єси́, ка́ко подоба́єть жи́ти в Дому́ Бо́жії, і́же єсть Це́рков Бо́га Жи́ва, столп і утвержде́ніє і́стини. Сего́ ра́ди к тебі́ припа́дающе мо́лимся: помози́ нам твої́ми моли́твами догма́ти і кано́ни церко́вния тве́рдо храни́ти, зрі́ніє согріше́ній свої́х ду́хом смире́нним стяжа́ти, вся́каго челові́ка я́ко нетлі́нний о́браз Христо́в по глаго́лу єва́нгельському возлюби́ти, ні єди́наго же презира́юще іли́ отріва́юще, но всім по си́лі служа́ще, і та́ко Го́сподеві рабо́тающе, да сподо́бимся с тобо́ю і со всі́ми новому́ченики Це́ркве Ру́ськия воспіва́ти Святу́ю Тро́йцю, во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Во́їне Христо́в Іларіо́не, сла́во і похвало́ Це́ркве Ру́ськия, пред ги́бнущим ми́ром Христа́ іспові́дал єси́, кровми́ твої́ми Це́рков утверди́ся, ра́зум Боже́ственний стяжа́л єси́, лю́дем ві́рним возглаша́ше: без Це́ркві ність спасе́нія."]},{"h":"Інший тропар, глас 4","ps":["Святи́телю Христо́в Іларіо́не, / сла́во і похвало́ Це́ркве Ру́ськия, / ра́зум боже́ственний стяжа́в, / пред безбо́жники Христа́ дерзнове́нно іспові́дал єси́, / Єго́же ра́ди страда́нія претерпіва́я, / лю́дем ві́рним возглаша́л єси́: // без Це́ркве ність спасе́нія."]},{"h":"Кондак, глас 6","ps":["Іларіо́не, священному́чениче Христо́в, служи́телей гряду́щаго анти́христа не убоя́лся єси́, Христа́ му́жеськи іспові́дал єси́, за Це́рков Бо́жию живо́т твой положи́. Красо́ новому́ченик Украї́нських, Русі́ святи́я похвало́, ти Це́ркве на́шея сла́ва і утвержде́ніє."]},{"h":"Інший кондак, глас 2","ps":["Сла́ву ми́ра сего́ оста́вив, / Христу́ до́блественне послі́довал єси́ / і, святи́тельськоє служе́ніє восприї́м, / вінце́м му́ченичества украси́лся єси́, / і ни́ні, Престо́лу Бо́жию предстоя́, / моли́ся, Іларіо́не, ієра́рше прему́дре, // спасти́ся душа́м на́шим."]},{"h":"Величання","ps":["Велича́єм тя, / священному́чениче Іларіо́не, / і чтим святу́ю па́м'ять твою́, / ти бо мо́лиши о нас // Христа́ Бо́га на́шего."]}],"notes":[]},{"u":"Акафіст святителю Герману, архієпископу Казанському","e":"Akathist to St Germanus, Archbishop of Kazan","secs":[{"h":"Кондак 1","ps":["Ізбра́нний святи́телю, те́плий о нас к Бо́гу моли́твенниче, уго́дниче Христо́в, преподо́бне о́тче Ге́рмане, я́ко імі́яй дерзнове́ніє ко Го́споду, от вся́ких нас бід твої́м предста́тельством ізбавля́й, да зове́м ті:","Ра́дуйся, святи́телю Ге́рмане, вели́кий чудотво́рче."]},{"h":"Ікос 1","ps":["А́нгелом уподобляя непоро́чним житіє́м святи́я твоя́ Го́споди, отве́рзи мі ум і язи́к, восхвали́ти богоуго́дную жизнь, і преподо́бния дія́нія святи́теля Твоєго́ Ге́рмана, да зове́м єму́, взе́мшему от ю́ности благи́й яре́м Твой на ра́мо своє́:","Ра́дуйся, благочести́ваго ко́рене благочести́вая о́трасле.","Ра́дуйся, от чре́ва ма́терня ізбра́нний служи́ти в преподо́бії і пра́вді.","Ра́дуйся, от отрочестких літ кро́тким і благи́м нра́вом себі́ украси́вий.","Ра́дуйся, от млада́го во́зраста в пості́ і моли́тві па́че во́зраста преуспі́вий.","Ра́дуйся, с уче́нієм кни́жним па́че стра́ху Бо́жию себі́ обучавий.","Ра́дуйся, в ю́них лі́тіх крі́пким подви́жником воздержа́нія себе́ яви́вий.","Ра́дуйся, ма́нієм Боже́ственним іздале́ча к вели́кому твоєму́ ізбра́нію ві́домий.","Ра́дуйся, тім же вседі́тельним ма́нієм, іспе́рва я́ко зі́ниця о́ка блюдо́мий.","Ра́дуйся, святи́телю Ге́рмане, вели́кий чудотво́рче."]},{"h":"Кондак 2","ps":["Ви́дя тщету́ мирська́го житія́, і многом'ятежность челові́чеських попече́ній, блаже́нне, жизнь твою́ іспе́рва посвяти́л єси́ Бо́гу, во є́же непреста́нно, і усти́ і се́рдцем, воспіва́ти Єму́: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зумом просвіща́ємий сви́ше, і жела́нієм влеко́мий ко го́рній жи́зні, ти вку́пі с богому́дрим роди́телем твої́м, па́че всего́ тща́ся о угожде́нії Бо́гу, отве́ргий кра́сная ми́ра, ті́сний і́ночеський путь ізбра́л єси́. Восхваля́юще твоє́ благо́є ізволе́ніє, взива́єм тебі́:","Ра́дуйся, вні мирська́го м'яте́жа, от мла́дости рабо́тати Бо́гу предложи́вий.","Ра́дуйся, ю́ность твою́, я́ко же́ртву непоро́чну, отверже́нієм от ми́ра Бо́гу принеси́й.","Ра́дуйся, в жи́зні по Бо́зі под духо́вним ігу́менством бу́дущаго святи́теля Гу́рія преспіва́вий.","Ра́дуйся, єму́же вку́пі во вели́ком па́стирстім служе́нії в споспі́шника і преє́мника благода́тію уготовлявийся.","Ра́дуйся, в то́йжде (Волоколамськой оби́телі) і сам в мі́ру духо́внаго вожденачальства дости́гнувий.","Ра́дуйся, пе́рвим тщавийся би́ти в послуша́нії, а́ще і послі́днім во і́ноціх себі́ іменова́вий.","Ра́дуйся, я́ко єли́ко смиря́л єси́ себе́, толи́ко па́че благода́тію к возвише́нію бил єси́ уготовляєм.","Ра́дуйся, і смире́нним возвраще́нієм от нача́льства на пре́жнєє послуша́ніє, но́вия духо́вния си́ли для послі́дующаго служе́нія твоєго́ стяжа́вий.","Ра́дуйся, святи́телю Ге́рмане, вели́кий чудотво́рче."]},{"h":"Кондак 3","ps":["Си́лою Ви́шняго, уготовлявшею тя во спасе́ніє твоє́ і мно́гих, ти, ізбра́нниче Бо́жий, ведо́м бил єси́ от си́ли в си́лу богоугодной жи́зні і діл. Ті́мже і воззва́н бил єси́ благода́тію на служе́ніє Це́ркве, в новопросвіще́ннім ца́рстві Казанстем, во є́же научи́ти і неві́дущих Спаси́теля ми́ра, зва́ти Єму́: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я благо́є помишле́ніє цар, новоприобретенноє си́лою кре́стною ца́рство Казанськоє, па́че всего́ устро́їти во єди́нстві благоче́стія, да єди́ним ду́хом ві́ри приобщи́ться о́но к вели́цій держа́ві ца́рства Украї́нськаго, а́ки часть к своєму́ тілесі́, при первосвятителі Гурії ізбра́ тя Собо́ром Це́ркве в сослуже́бника єму́, о сем ублажа́юще тя, присноблаже́нне, глаго́лем:","Ра́дуйся, собо́рним гла́сом на ді́ло апо́стольськоє досто́йно ізбра́нний.","Ра́дуйся, усе́рдний ді́лателю Христо́во в новопросвіще́нній страні́ магометанськаго заблужде́нія.","Ра́дуйся, я́ко благопло́дний сад, святу́ю оби́тель во гра́ді Свіяжсте насади́вий.","Ра́дуйся, храм во сла́ву Успе́нія Богома́тере, а́ки неув'яда́ємий трудо́в твої́х пам'ятник в ней сооруди́вий.","Ра́дуйся, ту́ю пе́рвіє присноцветущею лі́потою по́двигов твої́х украси́вий.","Ра́дуйся, в богоспаса́ємом бра́тстві новонасажденния оби́телі твоєя́, па́че всего́ плоди́ послуша́нія і стра́ха Бо́жия возрасти́вий.","Ра́дуйся, собира́я слове́сних ове́ць в слове́сний двор, всіх і ра́ди спаси́тельнаго жи́тельства, і ра́ди наставле́нія приходивших к тебі́, любе́зно прийма́вий.","Ра́дуйся, сла́вою доброді́телей твої́х, мно́гих із мра́ка магометанськаго нече́стія во світ і́стиннаго благоче́стія обращавий.","Ра́дуйся, святи́телю Ге́рмане, вели́кий чудотво́рче."]},{"h":"Кондак 4","ps":["Бу́рю мирська́го житія́, многообра́зними превратностьми злоключе́ній ви́ну воздвиза́ємую, благоотишно, я́ко му́дрий ко́рмчий, преше́д святи́тель Гу́рій, в приста́нище безмо́лвнаго поко́я дости́же; на по́прищі бо новопросвіще́нния па́стви, среді́ непреривних трудо́в подвиза́яся, первосвяти́тель Каза́нський у́спе ми́рним сном безсме́ртія, ти же, блаже́нне, я́ко пе́рвий сослужи́тель і ре́вностний сотрудник сконча́вшагося яви́лся, і досто́йний преє́мник єму́, да на престо́лі святителства пастиреначалственне віща́єши Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шав богоправимий собо́р вели́кия Украї́нськия Це́ркве, о блаже́нній кончи́ні пе́рваго святи́теля вели́кия па́стви Каза́нськия, єдиногла́сно суди́, я́ко то́кмо ти ізбра́нний Бо́жий досто́їн возсести на сіда́лищі блаже́ннаго Гу́рія, ті́мже воззванний в ца́рствующий град, а́ще і отрицялся єси́ по оби́чному тебі́ смире́нію от са́на святителськаго, оба́че повину́яся собо́рному опреділе́нію, восприя́л єси́ святителський жезл па́стви каза́нськия, ті́мже і ми во весе́лії приветствуєм тя:","Ра́дуйся, благи́й ра́бе Го́спода, ві́рностію в ме́ншем соделавийся досто́йним бо́льшаго служе́нія.","Ра́дуйся, світи́льниче, на свешниці во спасе́ніє мно́гим поста́вленний.","Ра́дуйся, наста́вниче, і сло́вом, а па́че приме́ром жи́зні твоєя́ наставля́вий ві́рних і неві́рних на путь Христо́в.","Ра́дуйся, па́стирю до́брий, неуси́пним попече́нієм полага́вий ду́шу твою́ о спасе́нії душ пасо́мих.","Ра́дуйся, му́дрий приста́вниче до́ма Госпо́дня всім, по коєго́ждо потре́бі ну́жная устроявий.","Ра́дуйся, ві́рний раздаятелю благ Го́спода твоєго́, по́мощ бі́дствующим, утіше́ніє скорб'я́щим, неоску́дно подава́вий.","Ра́дуйся, в благоговейнем служе́нії твоє́м, і се́рдце і преподо́бния ру́ці твоя́ о па́стві ко Го́споду воздевавий.","Ра́дуйся, благоприя́тними моли́твами твої́ми мир, ми́лость і благода́ть Бо́жию на новопросвіще́нния лю́ди низводивий.","Ра́дуйся, святи́телю Ге́рмане, вели́кий чудотво́рче."]},{"h":"Кондак 5","ps":["Боготе́чній звізді́ уподо́бился єси́, всехва́льне святи́телю; восходя́ бо благода́тію Бо́жиєю от си́ли в си́лу, по свяще́нним степе́нем ієрархії, воззва́н бил єси́ от па́стви каза́нськия на висоту́ престо́ла митропо́лії моско́вськия, да со все́ю Це́рковію воспіва́єши Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дів благові́рний цар богоуго́дноє твоє́ житіє́, святи́телю, соізво́ли на ви́шшій свешник всероссі́йськия митропо́лії поста́вити тя; ти же, блаже́нне, по смиренному́дрію твоєму́, явля́я себі́ недосто́йна би́ти такова́го са́на, досто́йнійшаго поста́вити умоля́л єси́ держа́внаго, оба́че повину́яся зва́нію, уготовлялся іспо́лнити во́лю царе́ву; но положи́л єси́ в се́рдці пе́рвіє ізрещи́ царю́ сло́во пра́вди, я́же пра́вда а́ки зло вміни́ся, і зап'я́ тя на путі́ вручаємаго тебі́ первопрестолія. Сего́ ра́ди сугу́бо ублажа́єм тя:","Ра́дуйся, і на висоті́ святителства смире́нная о себі́ мудрствовавий.","Ра́дуйся, на первопрестолії Украї́нськия Це́ркве па́че бре́м'я, не́же честь себі́ ви́дівий.","Ра́дуйся, я́ко во є́же бо́льшим послужи́ти во спасе́ніє, гото́в бил єси́ і ви́шшеє служе́ніє прия́ти.","Ра́дуйся, пре́жде восше́ствія на висоту́ престо́ла, во смире́нії сло́во царю́ провещавий.","Ра́дуйся, пра́вди ра́ди гоне́ніє і ізгна́ніє от предлежа́щия че́сти прия́вий.","Ра́дуйся, сло́во пра́во пред царе́м, па́че прия́тія вре́менния сла́ви предсудивий.","Ра́дуйся, ві́рою і пра́вдою служи́ти бла́гу це́ркві і ца́рства, необинове́нно на первосвятителськом престо́ле помишля́вий.","Ра́дуйся, ізгна́нієм пра́вди ра́ди, блаже́нство небе́сноє себі́ угото́вивий.","Ра́дуйся, святи́телю Ге́рмане, вели́кий чудотво́рче."]},{"h":"Кондак 6","ps":["Пропові́дник і́стини бил єси́, святи́телю Ге́рмане; єгда́ зло́бнії опричници воста́ша на святи́теля Фили́ппа, ти єди́н на суді́ непра́веднім глаго́лал єси́ пред царе́м о непра́вді, возводимой на му́жа непови́ннаго, віща́я в непоколеби́мій пра́вді Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́, святи́телю, в но́вом сві́те правота́ ду́ха твоєго́, єгда́ непови́нний святи́тель Фили́пп непра́ведно бил суди́м і осужде́н, ти єди́н із святи́телей воздви́гл єси́ глас в защи́ту страда́льця, благодерзнове́нно віща́я пред царе́м: я́ко блаже́нний он от ю́ности не суда́ ло́жна, ні лицеприя́тія не веде́. Ублажа́юще праволюбіє твоє́ віща́єм тебі́:","Ра́дуйся, при а́нгельськой кро́тости твоєя́, крі́пкий ревни́телю благоче́стія, єгда́ зрел то́є небрегомим от нече́стія.","Ра́дуйся, побо́рниче угнетаємой правоти́.","Ра́дуйся, безтрепетний защи́тниче неповинности.","Ра́дуйся, ре́вностію твоє́ю по і́стині, дре́внім святи́м ревни́телем уподо́бивийся.","Ра́дуйся, благодерзнове́нієм Гро́знаго удиви́вий, но смиренному́дрієм того́ на кро́тость преміни́вий.","Ра́дуйся, примі́р любве́ к правоті́ і послі́дующим родо́м оста́вивий.","Ра́дуйся, при за́паді жи́зні твоєя́, пла́менния лучи́ сві́тлаго ду́ха твоєго́ в споборе́нії і́стині показа́вий.","Ра́дуйся, праволюбивим защищенієм правоти́, тече́ніє праведной жи́зні твоєя́ увінча́вий.","Ра́дуйся, святи́телю Ге́рмане, вели́кий чудотво́рче."]},{"h":"Кондак 7","ps":["Хотя́ непоро́чную жизнь твою́, я́ко до́брий по́двиг сконча́ти, потща́лся єси́ і царю́ в смиренному́дрії сло́во бла́го рещи́ і пред царе́м в защи́ту му́жа пра́веднаго пра́воє сло́во провіща́ти, ті́мже соверши́в тече́ніє твоє́, я́ко ревни́тель благоче́стія і побо́рник і́стини, стяжа́л єси́ дерзнове́ніє во ісхо́ді твоє́м взива́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́ваго тя ревни́теля по благоче́стії, і побо́рника позна́ Гро́зний цар і весь сові́т єго́, єгда́ віща́л єси́ царю́ в пастирстей кро́тости словеса́ правоти́ і стра́ха Бо́жия, і на суді́ святи́теля, глаго́лал єси́ пред царе́м во огражде́ніє непови́ннаго, ті́мже вні па́стви твоєя́, в ца́рствующем гра́де пребива́я в терпі́нії, та́мо і блаже́нную жизнь твою́, от посіще́нія Бо́жия гра́да, смертоностним посіще́нієм сконча́л єси́. Ублажа́я смире́нноє в ду́сі, но висо́коє в ді́ліх тече́ніє жи́зні твоєя́ і смире́нную кончи́ну твою́ такова́я тебі́ прино́сим:","Ра́дуйся, ревни́телю смиренному́дрія от ю́ности путь смире́нія ізбра́вий.","Ра́дуйся, і на свяще́нния степе́ні зва́ніє і ізбра́ніє с смире́нним уклоне́нієм прийма́вий.","Ра́дуйся, жизнь твою́ при боговодимом шествії, я́коже в смире́нії соверша́вий, та́коже в смире́нії і сконча́вий.","Ра́дуйся, при кончи́ні твоє́й очистительною же́ртвою прегріше́ній от посіще́нія Бо́жия уме́рших би́вий.","Ра́дуйся, я́коже не іска́вий сла́ви челові́чеськія в жи́зні, та́ко смире́нноє погребе́ніє восприя́вий і в сме́рті.","Ра́дуйся, я́ко воі́стину стра́нник, ви́ну іска́вий небе́снаго гра́да, в ца́рствующем гра́де із до́льній ко го́рній жи́зні преше́дий.","Ра́дуйся, я́ко іді́же во смире́нії сном сме́ртним єси́ опочил, та́можде Госпо́дь пресла́вно тя чудодействем яви́л.","Ра́дуйся, святи́телю Ге́рмане, вели́кий чудотво́рче."]},{"h":"Кондак 8","ps":["Стра́нноє і пресла́вноє сотвори́ о тебі́, преподо́бне, прославля́яй преподо́бния своя́ Госпо́дь. Сли́шавше бо при́сная твоя́ ча́да, новосажденной тобо́ю оби́телі і́ноці, і благочести́вії богоспасаємия па́стви твоєя́ лю́діє, гра́да Свіяжська жи́теліє, от святи́х моще́й твої́х в ца́рствующем гра́де Москві́ ізлива́ющияся ісціле́нія, потща́шася возврати́ти тя во град свой, в мі́сто пе́рвих по́двигов твої́х на по́прищі просвіще́нія ві́рою новоприобретенния страни́, во є́же благоприятнєє при нетлі́нних мощеіх твої́х пі́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Вседу́шно, от всея́ любве́, і всенаро́дно, вся́каго чи́на і зва́нія, мона́си і мирсті́ї, гра́да Свіяжська жи́теліє вожделі́ша імі́ти мо́щі твоя́, святи́телю, в созда́нній тобо́ю оби́телі, в мі́сті сла́ви благода́ті, действовавшия тобо́ю в духо́вном созида́нії і́ночества, і назида́нії всіх приходя́щих к тебі́ ра́ди душе́вния по́льзи. Ті́мже іспроси́вше соізволе́ніє благочести́війшаго царя́, с неізглаго́ланною ра́достію пренесо́ша святи́я мо́щі твоя́, в созда́нную тобо́ю оби́тель, і ми в ра́дості їх, ве́село приветствуєм тя:","Ра́дуйся, я́ко по смире́нній кончи́ні просла́вленним тобо́ю Господом просла́влен єси́.","Ра́дуйся, я́ко для прия́тія святи́х моще́й твої́х, в благогові́йно сретавший тя град сподвигся і сам архипа́стир, святи́тель Ермоге́н.","Ра́дуйся, я́ко то́йже вели́кий святи́тель, со всім освяще́нним собо́ром, подоба́ющеє твоє́й святи́ні надгро́бноє пі́ніє соверши́.","Ра́дуйся, я́ко, при внесенії моще́й твої́х в созда́нний тобо́ю храм Богоро́диці, ди́вноє благоуха́ніє преісполни храм і оби́тель.","Ра́дуйся, я́ко к о́бщей благоговейней ра́дости, святи́я мо́щі твоя́ ці́ли і нетлі́нни обріто́шася.","Ра́дуйся, я́ко многоразли́чними ісціле́нії зна́меновася сла́ва святи́х моще́й твої́х.","Ра́дуйся, я́ко ті́ми же чудоді́йствії засвидетелствовася, я́ко обрі́л єси́ благода́ть у Го́спода.","Ра́дуйся, я́ко і симбирстії гра́ждане вожделі́ша імі́ти часть моще́й твої́х, во освяще́ніє і благода́тную по́мощ.","Ра́дуйся, святи́телю Ге́рмане, вели́кий чудотво́рче."]},{"h":"Кондак 9","ps":["Вся́кия болі́зні, живу́щею в тебі́ благода́тію Свята́го Ду́ха, ти святи́телю врачу́єши с ві́рою притека́ющих к цільбоно́сним моще́м твої́м. Сего́ ра́ди приє́млюще тобо́ю благода́ть ісціле́ній, благода́рні прия́вшему на себі́ неду́ги на́ша Спаси́телю поє́м: Аллилу́я."]},{"h":"Ікос 9","ps":["Ветийство челові́чеськоє не мо́жеть ізрещи́ благода́ті нетлі́нія моще́й твої́х, ні пові́дати си́ли чудоді́йствія о́них. Ми же та́їнство ві́рою приє́млюще, благоче́стно віща́єм:","Ра́дуйся, чистото́ю ду́ха от вся́каго бре́нія отріши́вийся.","Ра́дуйся, посто́м і воздержа́нієм, я́ко благово́нною сми́рною, ті́ло твоє́ тлі́нія неприча́стно сотвори́вий.","Ра́дуйся, непреста́нною моли́твою, я́ко небе́сним світоли́тієм, то́єжде благода́тния си́ли іспо́лнивий.","Ра́дуйся, все́льшимся в тя Животворя́щим Ду́хом по сме́рті чудоді́йствуя.","Ра́дуйся, сіявшим в тебі́ сві́том Христо́вим, тіле́сния і душе́вния о́чі просвіща́яй.","Ра́дуйся, богодарова́нною тебі́ си́лою, нечи́стия ду́хи от одержи́мих і́ми отгоня́яй.","Ра́дуйся, в прибіга́ющих к тебі́ стра́сті душе́вния і тіле́сния врачу́яй.","Ра́дуйся, я́ко бо́дренно соделовавий спасе́ніє твоє́, і всіх усе́рдно притека́ющих к тебі́ спасе́нію споспешествуяй.","Ра́дуйся, святи́телю Ге́рмане, вели́кий чудотво́рче."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ ду́шу твою́, отне́ліже нача́л єси́ рабо́тати Го́сподеві, вся́кия ско́рби, лише́нія і унічиже́нія до́бльственно терп'я́, по блаже́нній кончи́ні твоєя́, соді́лался єси́ прибі́жище всім скорбми́ жите́йськими обурева́ємим, во є́же со всі́ми взива́ти благода́рно Ізба́вителю всіх: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ і огражде́ніє нам святи́я мо́щі твоя́, присноблаже́нне; прибіга́я бо с ві́рою под цільбоно́сную сінь о́них, нікто́же моли́твами твої́ми, із хра́ма твоєго́ без благода́тнаго утіше́нія отхо́дить. В не́мже бо сам іскуше́н бил єси́, в сем і іскуша́ємим іспрашиваєши по́мощі. Предстоя́ще у́бо с любо́вію живоприє́мному гро́бу твоєму́, взива́єм:","Ра́дуйся, при́сний о нас к Бо́гу хода́таю.","Ра́дуйся, бі́дствующих предста́телю.","Ра́дуйся, печа́льних уті́шителю.","Ра́дуйся, нужда́ющихся помо́щниче.","Ра́дуйся, гони́мих прибі́жище.","Ра́дуйся, обурева́ємих злоключе́нії ти́хоє приста́нище.","Ра́дуйся, во мра́ці недоумі́нія су́щих богосві́тлоє вразумле́ніє.","Ра́дуйся, оби́димих засту́пниче.","Ра́дуйся, ізнемога́ющих ду́хом богому́дроє подкріпле́ніє.","Ра́дуйся, святи́телю Ге́рмане, вели́кий чудотво́рче."]},{"h":"Кондак 11","ps":["Пі́ніє похва́льноє принося́ще тебі́ святи́телю, ві́ми, я́ко ні свята́го житія́ твоєго́, ні преподо́бних дія́ній, ні чуде́с, благода́тію Бо́жиєю от моще́й твої́х оби́льно нам подава́ємих, по достоя́нію не то́кмо восхвали́ти, но ніже́, я́коже подоба́єть, ізвісти́ти возмого́хом. Оба́че ві́дуще тя преви́ше всіх похва́л су́ща, во сві́тлостіх святи́х, веселя́щеся простира́єм моле́бний глас о тебі́, прославля́ющему святи́я своя́: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоза́рний світи́льник іму́ще святи́я мо́щі твоя́, путь пра́вий нам освещающий, і гріхо́вний мрак разгоня́ющий, блажи́м тя во оби́теліх го́рніх веселя́щася, і от неістощи́маго істо́чника благода́ті Бо́жия, блага́я і поле́зная по коєго́ждо потре́бі нам іспрашивающа:","Ра́дуйся, за земни́я по́двиги твоя́ пренебе́сними благами от Подвигополо́жника обдарованний.","Ра́дуйся, за нищету́ духо́вную Ца́рство Небе́сноє восприє́мий.","Ра́дуйся, за воздиха́нія і сле́зи непреходящим весе́лієм утешаяйся.","Ра́дуйся, за кро́тость твою́ зе́млю ві́чнаго облада́нія наслі́дивий.","Ра́дуйся, за а́лчбу і жа́жду от неістощи́маго пото́ка сла́дости насищаяйся.","Ра́дуйся, за милосе́рдіє твоє́, ми́лость от Бо́га получи́вий.","Ра́дуйся, за чистоту́ твою́ лицезрі́нієм Бо́жиїм наслажда́яйся.","Ра́дуйся, за гоне́ніє пра́вди ра́ди, на мі́сті зла́чні примирнаго поко́я вселяйся.","Ра́дуйся, святи́телю Ге́рмане, вели́кий чудотво́рче."]},{"h":"Кондак 12","ps":["Благода́ть, все́льшуюся в тя Свята́го Ду́ха, яви́во в жи́зні, во сме́рти і по сме́рті твоєя́, святи́телю, облагодати́ на́шу мисль; недоумі́єм бо, ка́ко соверши́м ску́дную піснь на́шу в похвалу́ тебі́, ра́зві запечатлі́єм ту́ю совокупле́нієм во єди́но, я́ко разділе́нних луче́й, воспетих на́ми до́блестей твої́х, да хва́ляще тя ви́ну усти́ і се́рдцем поє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще твоє́ христоподражателноє житіє́, богому́драя дія́нія, блаже́нную кончи́ну, пресла́вная по кончи́ні чудоді́йствія, і явленнейшия до́блести твоя́, я́ко сві́тлия лучи́ соєдиня́юще вку́пі, от со́бственних твої́х добро́т, прино́сим тебі́ хвале́ніє таково́є:","Ра́дуйся, от ю́ности твоєя́ крі́пким по́стником і неосла́бним подви́жником себе́ яви́вий.","Ра́дуйся, по свяще́нним степе́нем возводимий благода́тію, па́че восхожде́нієм в се́рдці по вну́тренній свя́тости смиренному́дренно возвишавийся.","Ра́дуйся, до́бльственний блаже́ннаго Гу́рія в духо́вном созида́нії па́стви каза́нськия сотру́дниче.","Ра́дуйся, того́жде досто́йний в пастиреначальстві преє́мниче.","Ра́дуйся, імі́вий зва́ніє світи́ти і на висоті́ Всероссі́йськия митропо́лії.","Ра́дуйся, іспові́дниче і́стини пред царе́м, і защи́тниче страда́льчеськия правоти́ святи́теля.","Ра́дуйся, на мі́сті смире́ннаго поко́їща чудоді́йственною благода́тію проявленний.","Ра́дуйся, пресла́вно із царствующего гра́да нетлі́нними моща́ми твої́ми во оби́тель твою́ пренесенний.","Ра́дуйся, основа́нния тобо́ю оби́телі свяще́нноє огражде́ніє і украше́ніє.","Ра́дуйся, я́ко в ско́рбіх утіше́ніє, в болі́зніх ісціле́ніє, мо́щі твоя́ нам дарова́шася.","Ра́дуйся, благоприя́тний о нас до́льних і пе́рстних, вку́пі смире́нних і грі́шних, в го́рніх к Бо́гу предста́телю, і немо́лчний моли́твенниче.","Ра́дуйся, святи́телю Ге́рмане, вели́кий чудотво́рче."]},{"h":"Кондак 13","ps":["О вели́кий уго́дниче Бо́жий, святи́телю Ге́рмане, прийми́ сіє́ усе́рдноє к тебі́ моле́ніє на́ше, і благоприя́тним твої́м пред престо́лом Святи́я Тро́йці предста́тельством, моли́ о нас недосто́йних рабі́х твої́х, є́же ізба́витися нам от належа́щих бід, внеза́пния сме́рти і ві́чнаго осужде́нія, да сподо́бимся вку́пі с тобо́ю, в ли́ці святи́х, ви́ну Єди́ному в Тро́йці Бо́гу, Спаси́телю на́шему, воспіва́ти: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелом уподобляя непоро́чним житіє́м святи́я твоя́ Го́споди, отве́рзи мі ум і язи́к, восхвали́ти богоуго́дную жизнь, і преподо́бния дія́нія святи́теля Твоєго́ Ге́рмана, да зове́м єму́, взе́мшему от ю́ности благи́й яре́м Твой на ра́мо своє́:","Ра́дуйся, благочести́ваго ко́рене благочести́вая о́трасле.","Ра́дуйся, от чре́ва ма́терня ізбра́нний служи́ти в преподо́бії і пра́вді.","Ра́дуйся, от отрочестких літ кро́тким і благи́м нра́вом себі́ украси́вий.","Ра́дуйся, от млада́го во́зраста в пості́ і моли́тві па́че во́зраста преуспі́вий.","Ра́дуйся, с уче́нієм кни́жним па́че стра́ху Бо́жию себі́ обучавий.","Ра́дуйся, в ю́них лі́тіх крі́пким подви́жником воздержа́нія себе́ яви́вий.","Ра́дуйся, ма́нієм Боже́ственним іздале́ча к вели́кому твоєму́ ізбра́нію ві́домий.","Ра́дуйся, тім же вседі́тельним ма́нієм, іспе́рва я́ко зі́ниця о́ка блюдо́мий.","Ра́дуйся, святи́телю Ге́рмане, вели́кий чудотво́рче."]},{"h":"Кондак 1","ps":["Ізбра́нний святи́телю, те́плий о нас к Бо́гу моли́твенниче, уго́дниче Христо́в, преподо́бне о́тче Ге́рмане, я́ко імі́яй дерзнове́ніє ко Го́споду, от вся́ких нас бід твої́м предста́тельством ізбавля́й, да зове́м ті:","Ра́дуйся, святи́телю Ге́рмане, вели́кий чудотво́рче."]},{"h":"Молитва","ps":["О святи́телю Христо́в Ге́рмане, богому́дрий оби́телі сея́ основа́телю, духо́вний і́ночествующих вождю́, приме́ром христоподражательной жи́зні твоєя́ наставля́яй! К тебі́ прибіга́єм і тебі́ усе́рдно мо́лим: соді́лай святи́ми твої́ми моли́твами, да і ми благода́тію Бо́жиєю сози́ждемся во оби́тель Ду́ха Свята́го, послі́дованієм жи́зні твоєя́ воображаємся во о́браз Христо́в, во о́браз преподо́бія і пра́вди і осіня́ємії си́лою богоприя́тних моли́тв твої́х, прино́сим плоди́ благи́х діл; благоугожда́юще Го́споду, да тщі́мся ходи́ти во сві́ті лиця́ Єго́, па́че всего́ люби́ти Єго́, служи́ти во бла́го бли́жніх на́ших; і всемі́рно соді́ловати спасе́ніє своє́, на путі́ многопременчивия жи́зні, терпі́нієм вся́кия тісноти́, скорбе́й, лише́ній. А даби́ возмощи́ нам понести́ благо́є і́го Христо́во, моли́, свя́тче Бо́жий, о укріпле́нії не́мощі на́шея по́мощію сви́ше, да ізба́вить нас Госпо́дь от враг ви́димих і неви́димих, от о́гненнаго і водна́го потребле́нія, от неблагорастворе́нія возду́ха і тлітво́рних вітр, а па́че от душепа́губнаго пла́мені, потопле́нія і обурева́нія страсте́й на́ших, да под кро́вом благості і милосе́рдія Бо́жия, ти́хоє і безмо́лвноє житіє́ поживе́м, жду́ще блаже́ннаго явле́нія Го́спода і Спа́са на́шего Ісу́са Христа́; Єму́же со Отце́м і Святи́м Ду́хом честь і сла́ва, во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["От ю́ности і́го Христо́во усе́рдно восприї́м, / бді́нними по́двиги поста́ і моли́тви, просла́вился єси́. / Отону́дуже призива́ющу тя Бо́гу на служе́ніє Це́ркві / в новопросвіще́ннім ца́рстві Каза́нстем, / вку́пі со святи́телем Гу́рієм воззва́н бил єси́, / іді́же, я́ко первонача́льник созда́нной тобо́ю в гра́ді Свія́жске оби́телі, / і досто́йний первосвяти́телю преє́мник яви́лся єси́. / Ду́хом предстоя́ Престо́лу Влади́чню, / моли́ся, святи́телю Ге́рмане, со святи́телем Гу́рієм, / правосла́вній па́стві во благоче́стії преспіва́ти, // і тьмі інові́рія сві́том ві́ри разгна́тися."]},{"h":"Кондак, глас 4","ps":["До́блестями преподо́бія і пра́вди / вруче́нноє тебі́ слове́сноє ста́до озаря́я, / і на зла́чних Сло́ва Христо́ва па́житях пита́я, / на пра́вий путь за́повідей Госпо́дніх / си́лою ду́ха твоєго́ наставля́л єси́ є. / Ті́мже і ни́ні осеня́ємоє цільбоно́сними чудотворе́нії твої́ми, / в святу́ю па́м'ять твою́, зове́м тебі́: / не преста́й, святи́телю, предста́тельствовати / пред Пастиренача́льником о ста́ді твоє́м, / я́ко па́стви твоєя́ утвержде́ніє, // і су́щим по тебі́ святи́телем удобре́ніє."]},{"h":"Величання","ps":["Велича́єм тя, / святи́телю о́тче Ге́рмане, / і чтим святу́ю па́м'ять твою́, / ти бо мо́лиши о нас // Христа́ Бо́га на́шего."]}],"notes":[]}];
export default D;
